        [MenuItem("Tools/Wuxia RPG/Validate Prototype01 Scene Hierarchy & Play Mode")]
        public static bool ValidatePrototype01SceneHierarchyAndPlayMode()
        {
            string scenePath = "Assets/_Game/Scenes/Prototype01.unity";
            Debug.Log($"==================================================");
            Debug.Log($"   VALIDATING PROTOTYPE01 SCENE AT '{scenePath}'");
            Debug.Log($"==================================================");

            if (!System.IO.File.Exists(scenePath))
            {
                Debug.LogError($"[SCENE VALIDATION FAILED] Scene file not found at {scenePath}");
                return false;
            }

            var scene = UnityEditor.SceneManagement.EditorSceneManager.OpenScene(scenePath, UnityEditor.SceneManagement.OpenSceneMode.Single);
            if (!scene.IsValid() || !scene.isLoaded)
            {
                Debug.LogError($"[SCENE VALIDATION FAILED] Could not open scene {scenePath}");
                return false;
            }

            // Helper to find any GameObject (active or inactive) in the scene
            GameObject FindInScene(string name)
            {
                foreach (var root in scene.GetRootGameObjects())
                {
                    if (root.name == name) return root;
                    var t = root.transform.Find(name);
                    if (t != null) return t.gameObject;
                    foreach (var child in root.GetComponentsInChildren<Transform>(true))
                    {
                        if (child.name == name) return child.gameObject;
                    }
                }
                return null;
            }

            // Check Hierarchy GameObjects
            GameObject camGO = FindInScene("Main Camera");
            GameObject managersGO = FindInScene("--- MANAGERS ---");
            GameObject heroGO = FindInScene("Hero");
            GameObject monsterGO = FindInScene("Monster_Wild");
            GameObject groundGO = FindInScene("GroundVisual");
            GameObject canvasGO = FindInScene("UI Canvas");
            GameObject eventSystemGO = FindInScene("EventSystem");

            bool camValid = camGO != null && camGO.GetComponent<Camera>() != null;
            bool mgrValid = managersGO != null &&
                            managersGO.GetComponent<GameManager>() != null &&
                            managersGO.GetComponent<BattleManager>() != null &&
                            managersGO.GetComponent<GameBootstrap>() != null &&
                            managersGO.GetComponent<ProgressionManager>() != null &&
                            managersGO.GetComponent<EquipmentManager>() != null &&
                            managersGO.GetComponent<Inventory.Inventory>() != null &&
                            managersGO.GetComponent<ResourceManager>() != null &&
                            managersGO.GetComponent<DropSystem>() != null;
            bool heroValid = heroGO != null && heroGO.GetComponent<Hero>() != null;
            bool monsterValid = monsterGO != null && monsterGO.GetComponent<Monster>() != null;
            bool groundValid = groundGO != null;
            bool canvasValid = canvasGO != null && canvasGO.GetComponent<Canvas>() != null;
            bool eventSysValid = eventSystemGO != null && eventSystemGO.GetComponent<EventSystem>() != null;

            // Check UI Components under Canvas
            GameObject heroUI = FindInScene("HeroUI");
            GameObject monsterUI = FindInScene("MonsterUI");
            GameObject heroHPBar = FindInScene("HeroHPBar");
            GameObject monsterHPBar = FindInScene("MonsterHPBar");
            GameObject heroRageBar = FindInScene("HeroRageBar");
            GameObject expBar = FindInScene("ExpBar");
            GameObject eqDropPanel = FindInScene("EquipmentDropPanel");
            GameObject lootDecisionPanel = FindInScene("LootDecisionPanel");
            GameObject comparisonPanel = FindInScene("ComparisonPanel");
            GameObject debugPanel = FindInScene("DeveloperDebugPanel");

            bool uiElementsValid = heroUI != null && monsterUI != null && heroHPBar != null &&
                                   monsterHPBar != null && heroRageBar != null && expBar != null &&
                                   eqDropPanel != null && lootDecisionPanel != null &&
                                   comparisonPanel != null && debugPanel != null;

            Debug.Log($"[SCENE OBJECTS] Main Camera: {camValid}, Managers: {mgrValid}, Hero: {heroValid}, Monster: {monsterValid}, Ground: {groundValid}, Canvas: {canvasValid}, EventSystem: {eventSysValid}, UI Elements: {uiElementsValid}");

            bool allSceneObjectsValid = camValid && mgrValid && heroValid && monsterValid && groundValid && canvasValid && eventSysValid && uiElementsValid;

            if (allSceneObjectsValid)
            {
                Debug.Log("[SCENE VALIDATION: PASS] Prototype01.unity contains all required gameplay objects, managers, entities, and UI elements.");
                return true;
            }
            else
            {
                Debug.LogError("[SCENE VALIDATION: FAILED] Missing one or more required scene objects.");
                return false;
            }
        }

        public static List<EquipmentInstance> Generate10TestEquipmentItems()
        {
            GameObject sysGO = new GameObject("TestDropSys");
            DropSystem dropSys = sysGO.AddComponent<DropSystem>();
            dropSys.LoadDatabasesIfMissing();
            dropSys.NormalMonsterDropRate = 100f;

            List<EquipmentInstance> items = new List<EquipmentInstance>();
            for (int i = 0; i < 10; i++)
            {
                EquipmentInstance item = dropSys.GenerateDrop(null, 16);
                if (item != null) items.Add(item);
            }

            Object.DestroyImmediate(sysGO);
            return items;
        }

        // ==========================================
        // PROTOTYPE 02 ACCEPTANCE TEST CASES
        // ==========================================

        private static bool Test01_MonsterDeath()
        {
            GameObject monsterGO = new GameObject("TestMonster");
            Monster monster = monsterGO.AddComponent<Monster>();
            HealthComponent health = monsterGO.GetComponent<HealthComponent>();
            health.InitializeHealth(10f);

            bool died = false;
            System.Action<Entity> handler = (e) => { if (e == monster) died = true; };
            EventBus.OnEntityDied += handler;

            health.TakeDamage(new DamageResult(null, null, 100f, 100f, false, false, DamageType.BasicAttack));

            EventBus.OnEntityDied -= handler;
            Object.DestroyImmediate(monsterGO);
            Debug.Log($"[TEST 01] Monster Death -> Monster Died: {died} | {(died ? "PASS" : "FAIL")}");
            return died;
        }

