        private static bool Test07_NoDuplicateAffixes()
        {
            GameObject sysGO = new GameObject("TestDropSys");
            DropSystem dropSys = sysGO.AddComponent<DropSystem>();
            dropSys.NormalMonsterDropRate = 100f;

            bool allUnique = true;
            for (int i = 0; i < 50; i++)
            {
                EquipmentInstance item = dropSys.GenerateDrop(null, 16);
                if (item != null)
                {
                    HashSet<string> ids = new HashSet<string>();
                    foreach (var a in item.Affixes)
                    {
                        if (ids.Contains(a.AffixId)) allUnique = false;
                        ids.Add(a.AffixId);
                    }
                }
            }

            Object.DestroyImmediate(sysGO);
            Debug.Log($"[TEST 07] No Duplicate Affixes -> 50 Items All Unique: {allUnique} | {(allUnique ? "PASS" : "FAIL")}");
            return allUnique;
        }

        private static bool Test08_AffixValueScaling()
        {
            RarityDefinitionSO rarity1 = ScriptableObject.CreateInstance<RarityDefinitionSO>();
            rarity1.InitializeRarity("r1", "Pure", Color.white, 1, 1, 2, 1.0f);

            RarityDefinitionSO rarity2 = ScriptableObject.CreateInstance<RarityDefinitionSO>();
            rarity2.InitializeRarity("r2", "Relic", Color.yellow, 2, 1, 2, 2.0f);

            AffixDefinitionSO affix = ScriptableObject.CreateInstance<AffixDefinitionSO>();
            affix.InitializeAffix("aff_atk", "+ ATK", StatType.Attack, 10f, 10f, 100f);

            float val1 = AffixValueCalculator.CalculateAffixValue(affix, 1, rarity1);
            float val2 = AffixValueCalculator.CalculateAffixValue(affix, 1, rarity2);

            bool ok = (val1 == 10f) && (val2 == 20f);
            Debug.Log($"[TEST 08] Affix Value Scaling -> Rarity 1.0x: {val1}, Rarity 2.0x: {val2} | {(ok ? "PASS" : "FAIL")}");
            return ok;
        }

