        private static bool P04_Test16_NoDuplicateItemIDsAfterUpgrades()
        {
            GameObject resGO = new GameObject("TestRes");
            ResourceManager res = resGO.AddComponent<ResourceManager>();
            res.SetResources(50000, 100);

            GameObject upgGO = new GameObject("TestUpg");
            EquipmentUpgradeService upg = upgGO.AddComponent<EquipmentUpgradeService>();

            List<EquipmentInstance> items = Generate10TestEquipmentItems();
            HashSet<string> idsBefore = new HashSet<string>();
            foreach (var item in items) idsBefore.Add(item.InstanceId);

            foreach (var item in items)
            {
                upg.UpgradeEquipment(item);
            }

            HashSet<string> idsAfter = new HashSet<string>();
            foreach (var item in items) idsAfter.Add(item.InstanceId);

            bool ok = (idsBefore.Count == 10) && (idsAfter.Count == 10) && idsBefore.SetEquals(idsAfter);

            Object.DestroyImmediate(resGO);
            Object.DestroyImmediate(upgGO);
            Debug.Log($"[P04 TEST 16] No duplicate Item IDs after upgrades -> Unique Count: {idsAfter.Count} | {(ok ? "PASS" : "FAIL")}");
            return ok;
        }

        private static bool P04_Test17_100UpgradeOperationsMaintainIdentity()
        {
            GameObject resGO = new GameObject("TestRes");
            ResourceManager res = resGO.AddComponent<ResourceManager>();
            res.SetResources(500000, 1000);

            GameObject upgGO = new GameObject("TestUpg");
            EquipmentUpgradeService upg = upgGO.AddComponent<EquipmentUpgradeService>();

            GameObject sysGO = new GameObject("TestDropSys");
            DropSystem dropSys = sysGO.AddComponent<DropSystem>();
            dropSys.LoadDatabasesIfMissing();
            dropSys.NormalMonsterDropRate = 100f;

            bool allMaintained = true;
            for (int i = 0; i < 100; i++)
            {
                EquipmentInstance item = dropSys.GenerateDrop(null, 16);
                if (item != null)
                {
                    string initId = item.InstanceId;
                    RarityDefinitionSO initRarity = item.Rarity;
                    EquipmentSlotType initSlot = item.SlotType;

                    upg.UpgradeEquipment(item);

                    if (item.InstanceId != initId || item.Rarity != initRarity || item.SlotType != initSlot || item.EquipmentLevel < 2)
                    {
                        allMaintained = false;
                    }
                }
            }

            Object.DestroyImmediate(resGO);
            Object.DestroyImmediate(upgGO);
            Object.DestroyImmediate(sysGO);
            Debug.Log($"[P04 TEST 17] 100 Upgrade Operations Maintain Identity -> Maintained: {allMaintained} | {(allMaintained ? "PASS" : "FAIL")}");
            return allMaintained;
        }

