        private static bool P05_Test25_100RepeatedRecalculationsRemainDeterministic()
        {
            EventBus.ClearAllListeners();
            GameObject heroGO = new GameObject("TestHero");
            Hero hero = heroGO.AddComponent<Hero>();
            hero.InitializeHero();

            hero.ApplyLevelBaseStats(5, false); // Level 5
            float expectedHp = hero.Stats.GetValue(StatType.MaxHealth);
            float expectedAtk = hero.Stats.GetValue(StatType.Attack);
            float expectedDef = hero.Stats.GetValue(StatType.Defense);

            bool deterministic = true;
            for (int i = 0; i < 100; i++)
            {
                hero.RecalculateStats(false);
                if (hero.Stats.GetValue(StatType.MaxHealth) != expectedHp ||
                    hero.Stats.GetValue(StatType.Attack) != expectedAtk ||
                    hero.Stats.GetValue(StatType.Defense) != expectedDef)
                {
                    deterministic = false;
                }
            }

            Object.DestroyImmediate(heroGO);
            EventBus.ClearAllListeners();
            Debug.Log($"[P05 TEST 25] 100 Repeated Recalculations Remain Deterministic -> Deterministic: {deterministic} | {(deterministic ? "PASS" : "FAIL")}");
            return deterministic;
        }

