            return ok;
        }

        private static bool P05_1_Test05_TenConsecutiveAttacksReduceMonsterHPCorrectly()
        {
            BattleManager.ResetInstance();
            EventBus.ClearAllListeners();
            GameObject heroGO = new GameObject("TestHero");
            Hero hero = heroGO.AddComponent<Hero>();
            hero.InitializeHero();
            GameObject bmGO = new GameObject("TestBM");
            BattleManager bm = bmGO.AddComponent<BattleManager>();
            bm.RegisterHero(hero);
            bm.StartBattle();

            float initHp = bm.CurrentMonster.Health.CurrentHealth;
            float totalDmg = 0f;
            for (int i = 0; i < 5; i++)
            {
                float hpBefore = bm.CurrentMonster.Health.CurrentHealth;
                BasicAttackProcessor.ExecuteBasicAttack(hero, bm.CurrentMonster);
                float hpAfter = bm.CurrentMonster.Health.CurrentHealth;
                totalDmg += (hpBefore - hpAfter);
            }
            float finalHp = bm.CurrentMonster.Health.CurrentHealth;
            bool ok = Mathf.Approximately(initHp - totalDmg, finalHp);

            Object.DestroyImmediate(heroGO);
            if (bm.CurrentMonster != null) Object.DestroyImmediate(bm.CurrentMonster.gameObject);
            Object.DestroyImmediate(bmGO);
            BattleManager.ResetInstance();
            EventBus.ClearAllListeners();
            Debug.Log($"[P05.1 TEST 05] Multiple consecutive attacks reduce HP correctly -> Remaining: {finalHp:F2}, Total Dmg: {totalDmg:F2} | {(ok ? "PASS" : "FAIL")}");
            return ok;
        }

