        private static bool P05_2_Test27_StressTest_100ConsecutiveEncounters()
        {
            ProgressionManager.ResetInstance();
            BattleManager.ResetInstance();
            EventBus.ClearAllListeners();

            GameObject progGO = new GameObject("TestProg");
            ProgressionManager prog = progGO.AddComponent<ProgressionManager>();
            prog.InitializeProgression(1, 0f);

            GameObject heroGO = new GameObject("TestHero");
            Hero hero = heroGO.AddComponent<Hero>();
            hero.InitializeHero();

            GameObject bmGO = new GameObject("TestBM");
            BattleManager bm = bmGO.AddComponent<BattleManager>();
            bm.RegisterHero(hero);
            bm.StartBattle();

            bool stressValid = true;
            for (int i = 1; i <= 100; i++)
            {
                Monster m = bm.CurrentMonster;
                if (m == null || !m.CombatReady || m.CurrentTarget != hero || m.Health.CurrentHealth != 500f)
                {
                    stressValid = false;
                    break;
                }
                float h0 = hero.Health.CurrentHealth;
                BasicAttackProcessor.ExecuteBasicAttack(m, hero);
                if (hero.Health.CurrentHealth >= h0)
                {
                    stressValid = false;
                    break;
                }
                hero.Health.SetCurrentHealth(1000f);
                prog.HandleEntityDied(m);
                bm.EndEncounterAndStartNext();
            }

            int finalEnc = bm.EncounterIndex;
            int finalLv = prog.CurrentLevel;
            bool ok = stressValid && (finalEnc == 101) && (finalLv == 5 || finalLv == 6);

            Object.DestroyImmediate(heroGO);
            if (bm.CurrentMonster != null) Object.DestroyImmediate(bm.CurrentMonster.gameObject);
            Object.DestroyImmediate(bmGO);
            Object.DestroyImmediate(progGO);
            ProgressionManager.ResetInstance();
            BattleManager.ResetInstance();
            EventBus.ClearAllListeners();
            Debug.Log($"[P05.2 TEST 27] Stress test: 100 encounters with monster attacks -> Valid: {stressValid}, Enc: {finalEnc}, Lv: {finalLv} | {(ok ? "PASS" : "FAIL")}");
            return ok;
        }

