        private static bool P05_3_Test08_RealPlayModeSimulation_10Encounters_NaturalDualCombat()
        {
            ProgressionManager.ResetInstance();
            BattleManager.ResetInstance();
            EventBus.ClearAllListeners();

            GameObject progGO = new GameObject("TestProg");
            ProgressionManager prog = progGO.AddComponent<ProgressionManager>();
            prog.InitializeProgression(1, 0f);

            GameObject heroGO = new GameObject("TestHero");
            Hero hero = heroGO.AddComponent<Hero>();
            hero.InitializeHero();
            heroGO.transform.position = new Vector3(-4f, -1.2f, 0f);

            GameObject bmGO = new GameObject("TestBM");
            BattleManager bm = bmGO.AddComponent<BattleManager>();
            bm.RegisterHero(hero);
            bm.StartBattle();

            bool simSuccess = true;
            int encountersCompleted = 0;

            for (int enc = 1; enc <= 10; enc++)
            {
                Monster m = bm.CurrentMonster;
                if (m == null) { simSuccess = false; break; }

                float monsterInitialHp = m.Health.CurrentHealth;
                float heroInitialHp = hero.Health.CurrentHealth;
                bool heroTookDamageInThisEncounter = false;
                bool monsterTookDamageInThisEncounter = false;

                // Frame by frame simulation (0.05s per step, max 300 steps = 15s)
                for (int step = 0; step < 300; step++)
                {
                    if (bm.EncounterIndex > enc) break;

                    hero.Movement.ManualTick(0.05f);
                    if (bm.CurrentMonster != null && bm.CurrentMonster.Movement != null) bm.CurrentMonster.Movement.ManualTick(0.05f);
                    hero.Attack.ManualTick(0.05f);
                    if (bm.CurrentMonster != null && bm.CurrentMonster.Attack != null) bm.CurrentMonster.Attack.ManualTick(0.05f);

                    if (hero.Health.CurrentHealth < heroInitialHp) heroTookDamageInThisEncounter = true;
                    if (bm.CurrentMonster == null || bm.CurrentMonster.Health.CurrentHealth < monsterInitialHp) monsterTookDamageInThisEncounter = true;
                }

                if (!heroTookDamageInThisEncounter || !monsterTookDamageInThisEncounter)
                {
                    simSuccess = false;
                    break;
                }

                encountersCompleted++;
                hero.Health.SetCurrentHealth(1000f); // Reset hero HP for next round
            }

            bool ok = simSuccess && (encountersCompleted == 10) && (bm.EncounterIndex == 11);

            Object.DestroyImmediate(heroGO);
            if (bm.CurrentMonster != null) Object.DestroyImmediate(bm.CurrentMonster.gameObject);
            Object.DestroyImmediate(bmGO);
            Object.DestroyImmediate(progGO);
            ProgressionManager.ResetInstance();
            BattleManager.ResetInstance();
            EventBus.ClearAllListeners();
            Debug.Log($"[P05.3 TEST 08] Real Play Mode Simulation (10 encounters with natural movement & attacks): Completed: {encountersCompleted}, SimSuccess: {simSuccess} | {(ok ? "PASS" : "FAIL")}");
            return ok;
        }

