        private static bool P05_4_Test28_10ConsecutiveEncountersCompleteNaturally()
        {
            SetupTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject progGO, out ProgressionManager prog);

            bool allEncountersSuccessful = true;
            for (int enc = 1; enc <= 10; enc++)
            {
                Monster m = bm.CurrentMonster;
                if (m == null) { allEncountersSuccessful = false; break; }

                float initHeroHp = hero.Health.CurrentHealth;
                float initMonsterHp = m.Health.CurrentHealth;
                bool heroTookDamage = false;
                bool monsterTookDamage = false;

                for (int step = 0; step < 300; step++)
                {
                    if (bm.EncounterIndex > enc) break;

                    hero.Movement.ManualTick(0.05f);
                    if (bm.CurrentMonster != null) bm.CurrentMonster.Movement.ManualTick(0.05f);
                    hero.Attack.ManualTick(0.05f);
                    if (bm.CurrentMonster != null) bm.CurrentMonster.Attack.ManualTick(0.05f);

                    if (hero.Health.CurrentHealth < initHeroHp) heroTookDamage = true;
                    if (bm.CurrentMonster == null || bm.CurrentMonster.Health.CurrentHealth < initMonsterHp) monsterTookDamage = true;
                }

                if (!heroTookDamage || !monsterTookDamage)
                {
                    allEncountersSuccessful = false;
                    break;
                }

                hero.Health.SetCurrentHealth(1000f);
            }

            bool ok = allEncountersSuccessful && bm.EncounterIndex == 11;
            Debug.Log($"[P05.4 TEST 28] 10 consecutive encounters complete naturally -> EncounterIndex: {bm.EncounterIndex}, Success: {allEncountersSuccessful} | {(ok ? "PASS" : "FAIL")}");
            TeardownTestEncounter(heroGO, bmGO, progGO);
            return ok;
        }

        private static bool P05_4_Test29_RestartBattlePreservesHeroState()
        {
            SetupTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject progGO, out ProgressionManager prog);
