        private static bool P05_4_Test31_100EncounterStressTest()
        {
            SetupTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject progGO, out ProgressionManager prog);

            int encountersCompleted = 0;
            bool stressSuccess = true;

            for (int i = 1; i <= 100; i++)
            {
                Monster m = bm.CurrentMonster;
                if (m == null || !m.IsAlive || m.CurrentTarget != hero)
                {
                    stressSuccess = false;
                    break;
                }

                heroGO.transform.position = new Vector3(-0.5f, 0, 0);
                m.transform.position = new Vector3(0.5f, 0, 0);

                hero.Health.SetCurrentHealth(1000f);
                m.Attack.ManualTick(2.1f);
                if (hero.Health.CurrentHealth >= 1000f)
                {
                    stressSuccess = false;
                    break;
                }

                hero.Attack.ManualTick(1.6f);
                m.Health.TakeDamage(new Combat.DamageResult(hero, m, 9999f, 9999f, false, false, Combat.DamageType.BasicAttack));
                encountersCompleted++;
            }

            bool ok = stressSuccess && encountersCompleted == 100 && bm.EncounterIndex == 101;
            Debug.Log($"[P05.4 TEST 31] 100 encounter stress test -> Completed: {encountersCompleted}, Encounter: {bm.EncounterIndex} | {(ok ? "PASS" : "FAIL")}");
            TeardownTestEncounter(heroGO, bmGO, progGO);
            return ok;
        }

