        private static bool P05_5_Test02_RealPlayMode_HPSynchronization_HeroAndMonster()
        {
            SetupTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject progGO, out ProgressionManager prog);

            GameObject hudGO = new GameObject("TestHealthBarHUD");

            GameObject heroHpBarGO = new GameObject("HeroHPBar");
            heroHpBarGO.transform.SetParent(hudGO.transform);
            GameObject heroFillGO = new GameObject("HeroFill");
            heroFillGO.transform.SetParent(heroHpBarGO.transform);
            Image heroFill = heroFillGO.AddComponent<Image>();
            GameObject heroTextGO = new GameObject("HeroText");
            heroTextGO.transform.SetParent(heroHpBarGO.transform);
            TextMeshProUGUI heroText = heroTextGO.AddComponent<TextMeshProUGUI>();
            HealthBarUI heroHpUI = heroHpBarGO.AddComponent<HealthBarUI>();
            heroHpUI.SetReferences(heroFill, heroText, EntityType.Hero);
            heroHpUI.BindEntity(hero);

            GameObject monsterHpBarGO = new GameObject("MonsterHPBar");
            monsterHpBarGO.transform.SetParent(hudGO.transform);
            GameObject monsterFillGO = new GameObject("MonsterFill");
            monsterFillGO.transform.SetParent(monsterHpBarGO.transform);
            Image monsterFill = monsterFillGO.AddComponent<Image>();
            GameObject monsterTextGO = new GameObject("MonsterText");
            monsterTextGO.transform.SetParent(monsterHpBarGO.transform);
            TextMeshProUGUI monsterText = monsterTextGO.AddComponent<TextMeshProUGUI>();
            HealthBarUI monsterHpUI = monsterHpBarGO.AddComponent<HealthBarUI>();
            monsterHpUI.SetReferences(monsterFill, monsterText, EntityType.Monster);
            monsterHpUI.BindEntity(bm.CurrentMonster);

            bool syncPassed = true;

            for (int f = 0; f < 50; f++)
            {
                Monster m = bm.CurrentMonster;
                if (m == null || !m.IsAlive) break;

                hero.Movement.ManualTick(0.05f);
                if (m != null && m.gameObject != null && m.IsAlive) m.Movement.ManualTick(0.05f);
                hero.Attack.ManualTick(0.05f);
                if (m != null && m.gameObject != null && m.IsAlive) m.Attack.ManualTick(0.05f);

                float expectedHeroFill = hero.Health.MaxHealth > 0 ? hero.Health.CurrentHealth / hero.Health.MaxHealth : 0f;
                if (Mathf.Abs(heroHpUI.CurrentDisplayedFill - expectedHeroFill) > 0.01f ||
                    heroHpUI.CurrentDisplayedText != $"{hero.Health.CurrentHealth:F2} / {hero.Health.MaxHealth:F2}")
                {
                    syncPassed = false;
                    break;
                }

                if (m != null && m.gameObject != null && m.IsAlive)
                {
                    float expectedMonsterFill = m.Health.MaxHealth > 0 ? m.Health.CurrentHealth / m.Health.MaxHealth : 0f;
                    if (Mathf.Abs(monsterHpUI.CurrentDisplayedFill - expectedMonsterFill) > 0.01f ||
                        monsterHpUI.CurrentDisplayedText != $"{m.Health.CurrentHealth:F2} / {m.Health.MaxHealth:F2}")
                    {
                        syncPassed = false;
                        break;
                    }
                }
            }

            Object.DestroyImmediate(hudGO);
            Debug.Log($"[P05.5 TEST 02] HP Synchronization (HealthComponent, UI Text, UI Fill) -> Sync: {syncPassed} | {(syncPassed ? "PASS" : "FAIL")}");
            TeardownTestEncounter(heroGO, bmGO, progGO);
            return syncPassed;
        }

