        private static bool P05_5_Test05_RealPlayMode_Monster2_NaturalDualCombat_AttacksHero()
        {
            SetupTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject progGO, out ProgressionManager prog);

            Monster m1 = bm.CurrentMonster;
            for (int f = 0; f < 300; f++)
            {
                if (m1 == null || !m1.IsAlive) break;
                hero.Movement.ManualTick(0.05f);
                if (m1 != null && m1.gameObject != null && m1.IsAlive) m1.Movement.ManualTick(0.05f);
                hero.Attack.ManualTick(0.05f);
                if (m1 != null && m1.gameObject != null && m1.IsAlive) m1.Attack.ManualTick(0.05f);
            }

            Monster m2 = bm.CurrentMonster;
            float heroHpBeforeM2 = hero.Health.CurrentHealth;
            float m2HpBefore = m2 != null ? m2.Health.CurrentHealth : 0f;

            for (int f = 0; f < 100; f++)
            {
                if (m2 == null || !m2.IsAlive) break;
                hero.Movement.ManualTick(0.05f);
                if (m2 != null && m2.gameObject != null && m2.IsAlive) m2.Movement.ManualTick(0.05f);
                hero.Attack.ManualTick(0.05f);
                if (m2 != null && m2.gameObject != null && m2.IsAlive) m2.Attack.ManualTick(0.05f);
                if (hero.Health.CurrentHealth < heroHpBeforeM2 && m2.Health.CurrentHealth < m2HpBefore) break;
            }

            bool m2AttackedHero = hero.Health.CurrentHealth < heroHpBeforeM2;
            bool heroAttackedM2 = m2 == null || !m2.IsAlive || m2.Health.CurrentHealth < m2HpBefore;
            bool ok = m2AttackedHero && heroAttackedM2;

            Debug.Log($"[P05.5 TEST 05] Monster #2 Natural Dual Combat -> Monster #2 Damaged Hero: {m2AttackedHero}, Hero Damaged Monster #2: {heroAttackedM2} | {(ok ? "PASS" : "FAIL")}");
            TeardownTestEncounter(heroGO, bmGO, progGO);
            return ok;
        }

        private static bool P05_5_Test06_RealPlayMode_Encounters1To10_ContinuousNaturalCombatSimulation()
        {
            SetupTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject progGO, out ProgressionManager prog);

            bool all10Passed = true;

            for (int enc = 1; enc <= 10; enc++)
            {
                Monster m = bm.CurrentMonster;
                if (m == null || !m.IsAlive || bm.EncounterIndex != enc)
                {
                    all10Passed = false;
                    break;
                }

                if (hero.Health.CurrentHealth < 300f)
                {
                    hero.Health.SetCurrentHealth(1000f);
                }

                float mStartHp = m.Health.CurrentHealth;
                float hStartHp = hero.Health.CurrentHealth;
                bool mAttacked = false;
                bool hAttacked = false;

                for (int f = 0; f < 300; f++)
                {
                    if (m == null || !m.IsAlive) break;
                    hero.Movement.ManualTick(0.05f);
                    if (m != null && m.gameObject != null && m.IsAlive) m.Movement.ManualTick(0.05f);
                    hero.Attack.ManualTick(0.05f);
                    if (m != null && m.gameObject != null && m.IsAlive) m.Attack.ManualTick(0.05f);

                    if (hero.Health.CurrentHealth < hStartHp) mAttacked = true;
                    if (m != null && m.gameObject != null && m.Health.CurrentHealth < mStartHp) hAttacked = true;
                }

                if (!mAttacked || !hAttacked || (m != null && m.IsAlive))
                {
                    all10Passed = false;
                    break;
                }
            }

            bool ok = all10Passed && bm.EncounterIndex == 11;
            Debug.Log($"[P05.5 TEST 06] Continuous Natural Combat 10 Encounters -> All Completed: {all10Passed}, Final Enc: {bm.EncounterIndex} | {(ok ? "PASS" : "FAIL")}");
            TeardownTestEncounter(heroGO, bmGO, progGO);
            return ok;
        }

