        private static bool P05_6_19_EquipmentBonusesRemainCorrectlyApplied()
        {
            SetupTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject progGO, out ProgressionManager prog);
            EquipmentManager eqMgr = EquipmentManager.Instance;

            List<AffixInstance> affixes = new List<AffixInstance> { new AffixInstance("a1", "+ ATK", StatType.Attack, 40f) };
            EquipmentInstance sword = new EquipmentInstance("wuxia_sword", "Wuxia Sword", EquipmentSlotType.Weapon, 1, null, affixes);
            eqMgr.Equip(sword);
            hero.RecalculateStats();

            float atkBeforeBk = hero.Stats.GetValue(StatType.Attack); // 100 + 40 = 140

            prog.AddExp(700f);
            prog.SetMockStageCleared(1);
            prog.SetMockDropLevel(2);
            prog.TryBreakthrough(); // Base ATK -> 200

            float atkAfterBk = hero.Stats.GetValue(StatType.Attack); // 200 + 40 = 240
            bool ok = (atkBeforeBk == 140f) && (atkAfterBk == 240f);
            Debug.Log($"[P05.6-19] Equipment bonuses remain correctly applied -> Before Breakthrough: {atkBeforeBk} (100+40), After: {atkAfterBk} (200+40) | {(ok ? "PASS" : "FAIL")}");
            TeardownTestEncounter(heroGO, bmGO, progGO);
            return ok;
        }

