        private static GameObject CreateTestUIRect(Transform parent, string name, Vector2 anchorMin, Vector2 anchorMax, Vector2 pos, Vector2 size)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);
            RectTransform rect = go.AddComponent<RectTransform>();
            rect.anchorMin = anchorMin;
            rect.anchorMax = anchorMax;
            rect.anchoredPosition = pos;
            rect.sizeDelta = size;
            return go;
        }

        private static Image CreateTestUIImage(Transform parent, string name, Color color, bool raycastTarget = false)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);
            RectTransform rect = go.AddComponent<RectTransform>();
            rect.anchorMin = Vector2.zero;
            rect.anchorMax = Vector2.one;
            rect.sizeDelta = Vector2.zero;
            Image img = go.AddComponent<Image>();
            img.color = color;
            img.raycastTarget = raycastTarget;
            return img;
        }

        private static TextMeshProUGUI CreateTestUIText(Transform parent, string name, string text, float fontSize, TextAlignmentOptions align, Color color, bool raycastTarget = false)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);
            RectTransform rect = go.AddComponent<RectTransform>();
            rect.anchorMin = Vector2.zero;
            rect.anchorMax = Vector2.one;
            rect.sizeDelta = Vector2.zero;
            TextMeshProUGUI tmp = go.AddComponent<TextMeshProUGUI>();
            tmp.text = text;
            tmp.fontSize = fontSize;
            tmp.alignment = align;
            tmp.color = color;
            tmp.raycastTarget = raycastTarget;
            return tmp;
        }

        private static (GameObject bgGO, Image fillImg, TextMeshProUGUI tmpText) CreateTestUIBar(Transform parent, string name, Vector2 pos, Vector2 size, Color fillColor)
        {
            GameObject bgGO = CreateTestUIRect(parent, name, new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), pos, size);
            Image bgImg = bgGO.AddComponent<Image>();
            bgImg.color = new Color(0.1f, 0.1f, 0.1f, 0.85f);
            bgImg.raycastTarget = false;

            GameObject fillGO = CreateTestUIRect(bgGO.transform, "Fill", Vector2.zero, Vector2.one, Vector2.zero, Vector2.zero);
            Image fillImg = fillGO.AddComponent<Image>();
            fillImg.color = fillColor;
            fillImg.type = Image.Type.Filled;
            fillImg.fillMethod = Image.FillMethod.Horizontal;
            fillImg.raycastTarget = false;

            GameObject textGO = CreateTestUIRect(bgGO.transform, "Text", Vector2.zero, Vector2.one, Vector2.zero, Vector2.zero);
            TextMeshProUGUI tmp = textGO.AddComponent<TextMeshProUGUI>();
            tmp.fontSize = 16;
            tmp.fontStyle = FontStyles.Bold;
            tmp.alignment = TextAlignmentOptions.Center;
            tmp.color = Color.white;
            tmp.raycastTarget = false;

            return (bgGO, fillImg, tmp);
        }

        private static Button CreateTestUIButton(Transform parent, string name, string label, Vector2 pos, Vector2 size)
        {
            GameObject btnGO = CreateTestUIRect(parent, name, new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), pos, size);
            Image img = btnGO.AddComponent<Image>();
            img.color = new Color(0.2f, 0.55f, 0.9f);
            img.raycastTarget = true;
            Button btn = btnGO.AddComponent<Button>();
            btn.targetGraphic = img;
            btn.interactable = true;

            GameObject textGO = CreateTestUIRect(btnGO.transform, "Text", Vector2.zero, Vector2.one, Vector2.zero, Vector2.zero);
            TextMeshProUGUI tmp = textGO.AddComponent<TextMeshProUGUI>();
            tmp.text = label;
            tmp.fontSize = 20;
            tmp.fontStyle = FontStyles.Bold;
            tmp.alignment = TextAlignmentOptions.Center;
            tmp.color = Color.white;
            tmp.raycastTarget = false;

            return btn;
        }

        public static bool SimulateRealPointerClick(Button btn)
        {
            if (btn == null)
            {
                Debug.LogError("[POINTER CLICK SIMULATION] Button is null!");
                return false;
            }
            if (!btn.interactable)
            {
                Debug.LogWarning($"[POINTER CLICK SIMULATION] Button '{btn.name}' is not interactable!");
                return false;
            }
            if (!btn.gameObject.activeInHierarchy)
            {
                Debug.LogWarning($"[POINTER CLICK SIMULATION] Button '{btn.name}' is not active in hierarchy!");
                return false;
            }

            Canvas.ForceUpdateCanvases();

            RectTransform rt = btn.GetComponent<RectTransform>();
            Canvas canvas = btn.GetComponentInParent<Canvas>();
            GraphicRaycaster gr = canvas != null ? canvas.GetComponent<GraphicRaycaster>() : null;
            Camera cam = (canvas != null && canvas.renderMode != RenderMode.ScreenSpaceOverlay) ? canvas.worldCamera : null;

            Vector3[] corners = new Vector3[4];
            rt.GetWorldCorners(corners);
            Vector3 centerWorld = (corners[0] + corners[2]) * 0.5f;
            Vector2 screenPos = (cam != null) ? (Vector2)RectTransformUtility.WorldToScreenPoint(cam, centerWorld) : new Vector2(centerWorld.x, centerWorld.y);

            EventSystem es = EventSystem.current;
            if (es == null) es = Object.FindAnyObjectByType<EventSystem>();

            PointerEventData pointerData = new PointerEventData(es)
            {
                position = screenPos,
                button = PointerEventData.InputButton.Left,
                clickCount = 1
            };

            List<RaycastResult> results = new List<RaycastResult>();
            if (gr != null)
            {
                gr.Raycast(pointerData, results);
            }
            else if (es != null)
            {
                es.RaycastAll(pointerData, results);
            }

            if (results.Count > 0)
            {
                GameObject hitGO = results[0].gameObject;
                Button hitBtn = hitGO.GetComponentInParent<Button>();
                if (hitBtn != null && hitBtn != btn)
                {
                    Debug.LogError($"[POINTER CLICK SIMULATION] Raycast BLOCKED! Top hit: '{hitGO.name}' (parent button: '{hitBtn.name}'), expected: '{btn.name}'");
                    return false;
                }
                pointerData.pointerPressRaycast = results[0];
                pointerData.pointerCurrentRaycast = results[0];
                pointerData.rawPointerPress = hitGO;
            }

            // Execute pointer click lifecycle on button
            ExecuteEvents.Execute(btn.gameObject, pointerData, ExecuteEvents.pointerDownHandler);
            ExecuteEvents.Execute(btn.gameObject, pointerData, ExecuteEvents.pointerUpHandler);
            ExecuteEvents.Execute(btn.gameObject, pointerData, ExecuteEvents.pointerClickHandler);

            return true;
        }

