        private static void TeardownUIEncounter(UIEncounterContext ctx)
        {
            if (ctx.canvasGO != null) Object.DestroyImmediate(ctx.canvasGO);
            if (ctx.eventSystemGO != null) Object.DestroyImmediate(ctx.eventSystemGO);
            if (ctx.progGO != null) Object.DestroyImmediate(ctx.progGO);
            if (ctx.invGO != null) Object.DestroyImmediate(ctx.invGO);
            if (ctx.eqGO != null) Object.DestroyImmediate(ctx.eqGO);
            if (ctx.resGO != null) Object.DestroyImmediate(ctx.resGO);
            if (ctx.upgGO != null) Object.DestroyImmediate(ctx.upgGO);
            if (ctx.heroGO != null) Object.DestroyImmediate(ctx.heroGO);

            EquipmentManager.ResetInstance();
            Inventory.Inventory.ResetInstance();
            ResourceManager.ResetInstance();
            ProgressionManager.ResetInstance();
            BattleManager.ResetInstance();
            EventBus.ClearAllListeners();
        }

