            // Equip becomes interactable when unequipped item is selected
            EquipmentInstance item = new EquipmentInstance("wuxia_sword", "Wuxia Sword", EquipmentSlotType.Weapon, 1, null, new List<AffixInstance>());
            ctx.dropUI.SelectItem(item, false, EquipmentSlotType.Weapon);
            bool equip = ctx.eqBtn.interactable;

            // Unequip becomes interactable when equipped item is selected
            ctx.eqMgr.Equip(item);
            ctx.dropUI.SelectItem(item, true, EquipmentSlotType.Weapon);
            bool unequip = ctx.uneqBtn.interactable;
            bool upgrade = ctx.upgBtn.interactable;

            bool ok = add10 && add100 && add1000 && drop && addG && addM && drop1000 && equip && unequip && upgrade;
            Debug.Log($"[P05.6 UI TEST 05] All debug buttons are interactable: {(ok ? "PASS" : "FAIL")}");
            TeardownUIEncounter(ctx);
            return ok;
        }

