        private static bool P05_6_UI_09_Add10ExpClickChangesAuthoritativeExp()
        {
            var ctx = SetupUIEncounter();
            float expBefore = ctx.progMgr.CurrentExp; // 20
            bool clickOk = SimulateRealPointerClick(ctx.add10Btn);
            float expAfter = ctx.progMgr.CurrentExp; // 30
            bool uiTextOk = ctx.progUI.ExpText != null && ctx.progUI.ExpText.text.Contains("30");
