        #endregion

        #region Helpers

        private static void SetupTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject progGO, out ProgressionManager prog)
        {
            EquipmentManager.ResetInstance();
            Inventory.Inventory.ResetInstance();
            ResourceManager.ResetInstance();
            ProgressionManager.ResetInstance();
            BattleManager.ResetInstance();
            EventBus.ClearAllListeners();

            GameObject servicesGO = new GameObject("TestServices");
            servicesGO.AddComponent<EquipmentManager>();
            servicesGO.AddComponent<Inventory.Inventory>();
            servicesGO.AddComponent<ResourceManager>();

            progGO = new GameObject("TestProg");
            prog = progGO.AddComponent<ProgressionManager>();
            prog.InitializeProgression(1, 0f);

            heroGO = new GameObject("TestHero");
            hero = heroGO.AddComponent<Hero>();
            hero.InitializeHero();
            heroGO.transform.position = new Vector3(-4f, -1.2f, 0f);

            bmGO = new GameObject("TestBM");
            bm = bmGO.AddComponent<BattleManager>();
            bm.RegisterHero(hero);
            bm.StartBattle();
        }

        private static void TeardownTestEncounter(GameObject heroGO, GameObject bmGO, GameObject progGO)
        {
            if (heroGO != null) Object.DestroyImmediate(heroGO);
            if (bmGO != null)
            {
                BattleManager bm = bmGO.GetComponent<BattleManager>();
                if (bm != null && bm.CurrentMonster != null) Object.DestroyImmediate(bm.CurrentMonster.gameObject);
                Object.DestroyImmediate(bmGO);
            }
            if (progGO != null) Object.DestroyImmediate(progGO);

            GameObject servicesGO = GameObject.Find("TestServices");
            if (servicesGO != null) Object.DestroyImmediate(servicesGO);

            EquipmentManager.ResetInstance();
            Inventory.Inventory.ResetInstance();
            ResourceManager.ResetInstance();
            ProgressionManager.ResetInstance();
            BattleManager.ResetInstance();
            EventBus.ClearAllListeners();
        }

        #endregion

