            battleSO.Update();
            // Trigger complete loot decision with equip
            EquipmentManager.Instance.Equip(weapon);
            hero.RecalculateStats(true);

            float atkAfter = hero.Stats.GetValue(StatType.Attack);
            bool ok = (atkAfter == atkBefore + 35f);

            Debug.Log($"[P05.7-11] Hero Final Stats update after EQUIP -> ATK: {atkBefore} -> {atkAfter} (+35) | {(ok ? "PASS" : "FAIL")}");

