        // 6. STRESS TESTS (P05.7-30 to P05.7-31)
        private static bool P05_7_30_TenConsecutiveEncountersWithLootDecisions()
        {
            SetupTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject progGO, out ProgressionManager prog);
            GameObject dropSysGO = new GameObject("TestDropSys");
            DropSystem dropSys = dropSysGO.AddComponent<DropSystem>();
            dropSys.LoadDatabasesIfMissing();
            dropSys.NormalMonsterDropRate = 100f;

            bool loopOk = true;
            for (int i = 1; i <= 10; i++)
            {
                if (bm.CurrentMonster == null || !bm.CurrentMonster.IsAlive)
                {
                    loopOk = false;
                    break;
                }

                bm.CurrentMonster.Health.TakeDamage(2000f);
                if (bm.CurrentBattleState != BattleState.LootPending || bm.PendingLootItem == null)
                {
                    loopOk = false;
                    break;
                }

                bool equipThis = (i % 2 == 1);
                bm.CompleteLootDecisionAndResume(equip: equipThis, dismantle: !equipThis);

                if (bm.CurrentBattleState != BattleState.InProgress || !bm.IsBattleActive)
                {
                    loopOk = false;
                    break;
                }
            }

            bool ok = loopOk && (bm.EncounterIndex == 11);
            Debug.Log($"[P05.7-30] 10 consecutive encounters with loot decisions -> Loop: {loopOk}, Final Enc: {bm.EncounterIndex} | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(dropSysGO);
            TeardownTestEncounter(heroGO, bmGO, progGO);
            return ok;
        }

