            SetupTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject progGO, out ProgressionManager prog);
            GameObject canvasGO = new GameObject("TestCanvas");
            GameObject panelGO = new GameObject("LootDecisionPanel");
            panelGO.transform.SetParent(canvasGO.transform);
            LootDecisionUI lootUI = canvasGO.AddComponent<LootDecisionUI>();
            lootUI.SetReferences(panelGO, null, null, null, null, null, null, null, null);

            GameObject dropSysGO = new GameObject("TestDropSys");
            DropSystem dropSys = dropSysGO.AddComponent<DropSystem>();
            dropSys.LoadDatabasesIfMissing();
            dropSys.NormalMonsterDropRate = 100f;

            bm.CurrentMonster.Health.TakeDamage(2000f);
            lootUI.HandleLootDecisionRequested(bm.PendingLootItem);
            bool panelOpenInLootPending = panelGO.activeSelf;

            lootUI.OnEquipClicked();
            bool panelClosedAfterEquip = !panelGO.activeSelf;

            bool ok = panelOpenInLootPending && panelClosedAfterEquip;
            Debug.Log($"[P05.7.1-04] Loot UI closes after EQUIP -> OpenBefore: {panelOpenInLootPending}, ClosedAfter: {panelClosedAfterEquip} | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(canvasGO);
            Object.DestroyImmediate(dropSysGO);
            TeardownTestEncounter(heroGO, bmGO, progGO);
            return ok;
        }

