        private static bool P05_7_1_13_HeroAttackResumes()
        {
            SetupTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject progGO, out ProgressionManager prog);
            GameObject dropSysGO = new GameObject("TestDropSys");
            DropSystem dropSys = dropSysGO.AddComponent<DropSystem>();
            dropSys.LoadDatabasesIfMissing();
            dropSys.NormalMonsterDropRate = 100f;

            bm.CurrentMonster.Health.TakeDamage(2000f);
            bm.CompleteLootDecisionAndResume(equip: true, dismantle: false);

            float hpBefore = bm.CurrentMonster.Health.CurrentHealth;
            // Bring hero and monster in attack range
            bm.CurrentMonster.transform.position = hero.transform.position + new Vector3(1.0f, 0f, 0f);

            for (int i = 0; i < 5 && bm.CurrentMonster.Health.CurrentHealth >= hpBefore; i++)
            {
                hero.Attack.ManualTick(2.5f);
            }
            float hpAfter = bm.CurrentMonster.Health.CurrentHealth;
            bool ok = (hpAfter < hpBefore);
            Debug.Log($"[P05.7.1-13] Hero attack resumes -> Monster HP: {hpBefore} -> {hpAfter} | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(dropSysGO);
            TeardownTestEncounter(heroGO, bmGO, progGO);
            return ok;
        }

