            bool ok = (hero.Health.CurrentHealth < heroStart) && (bm.CurrentMonster.Health.CurrentHealth < monsterStart);
            Debug.Log($"[P05.7.1-17] Both sides exchange damage over multiple cycles -> Hero: {heroStart}->{hero.Health.CurrentHealth}, Monster: {monsterStart}->{bm.CurrentMonster.Health.CurrentHealth} | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(dropSysGO);
            TeardownTestEncounter(heroGO, bmGO, progGO);
            return ok;
        }

