        private static bool P05_7_2_07_StatDifferenceCorrect()
        {
            SetupTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject progGO, out ProgressionManager prog);
            EquipmentInstance curItem = new EquipmentInstance("cur_ring", "Bronze Ring", EquipmentSlotType.Ring, 1, null, new List<AffixInstance> {
                new AffixInstance("a1", "HP", StatType.MaxHealth, 100f),
                new AffixInstance("a2", "ATK", StatType.Attack, 20f),
                new AffixInstance("a3", "Crit", StatType.CritRate, 2.0f)
            });
            EquipmentManager.Instance.Equip(curItem);

            EquipmentInstance newItem = new EquipmentInstance("new_ring", "Silver Ring", EquipmentSlotType.Ring, 2, null, new List<AffixInstance> {
                new AffixInstance("a4", "HP", StatType.MaxHealth, 150f),
                new AffixInstance("a5", "ATK", StatType.Attack, 10f),
                new AffixInstance("a6", "Crit", StatType.CritRate, 3.5f),
                new AffixInstance("a7", "DEF", StatType.Defense, 15f)
            });

            ComparisonResult result = CombatPowerCalculator.CalculateComparison(hero, EquipmentManager.Instance, newItem);

            float hpDelta = result.GetStatDelta(StatType.MaxHealth); // +50
            float atkDelta = result.GetStatDelta(StatType.Attack);    // -10
            float critDelta = result.GetStatDelta(StatType.CritRate); // +1.5
            float defDelta = result.GetStatDelta(StatType.Defense);   // +15

            bool ok = (Mathf.Approximately(hpDelta, 50f) && Mathf.Approximately(atkDelta, -10f) && Mathf.Approximately(critDelta, 1.5f) && Mathf.Approximately(defDelta, 15f));
            Debug.Log($"[P05.7.2-07] Each supported stat difference is correct -> HP Delta: {hpDelta}, ATK Delta: {atkDelta}, Crit Delta: {critDelta:F1}, DEF Delta: {defDelta} | {(ok ? "PASS" : "FAIL")}");

            TeardownTestEncounter(heroGO, bmGO, progGO);
            return ok;
        }

