            bool deterministic = true;

            for (int i = 0; i < 100; i++)
            {
                ComparisonResult run = CombatPowerCalculator.CalculateComparison(hero, EquipmentManager.Instance, newItem);
                if (run.CurrentPower != first.CurrentPower || run.ProjectedPower != first.ProjectedPower || run.PowerDifference != first.PowerDifference)
                {
                    deterministic = false;
                    break;
                }
            }

            Debug.Log($"[P05.7.2-20] Comparison is deterministic across 100 calculations -> Deterministic: {deterministic} | {(deterministic ? "PASS" : "FAIL")}");

            TeardownTestEncounter(heroGO, bmGO, progGO);
            return deterministic;
        }

