        private static bool P05_7_3_11_NoMissingGlyphWarningOnRepeatedUpdates()
        {
            SetupTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject progGO, out ProgressionManager prog);
            GameObject canvasGO = new GameObject("TestCanvas");
            GameObject panelGO = new GameObject("LootDecisionPanel");
            panelGO.transform.SetParent(canvasGO.transform);
            GameObject pwrGO = new GameObject("PowerChange");
            pwrGO.transform.SetParent(panelGO.transform);
            TextMeshProUGUI pwrTmp = pwrGO.AddComponent<TextMeshProUGUI>();

            GameObject statGO = new GameObject("StatChanges");
            statGO.transform.SetParent(panelGO.transform);
            TextMeshProUGUI statTmp = statGO.AddComponent<TextMeshProUGUI>();

            LootDecisionUI lootUI = canvasGO.AddComponent<LootDecisionUI>();
            lootUI.SetReferences(panelGO, null, null, null, null, null, null, null, null, pwrChgTmp: pwrTmp, statChgTmp: statTmp);

            bool clean = true;
            for (int i = 0; i < 50; i++)
            {
                EquipmentInstance item = new EquipmentInstance($"item_{i}", $"Item {i}", (EquipmentSlotType)(i % 6), 1, null, new List<AffixInstance> {
                    new AffixInstance("a1", "DEF", StatType.Defense, 10f * i)
                });
                lootUI.DisplayComparison(item);

                if (pwrTmp.text.Contains("\u2794") || statTmp.text.Contains("\u2794"))
                {
                    clean = false;
                    break;
                }
            }

            Debug.Log($"[P05.7.3-11] No missing-glyph characters across 50 UI updates -> Clean: {clean} | {(clean ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(canvasGO);
            TeardownTestEncounter(heroGO, bmGO, progGO);
            return clean;
        }

