        private static bool P05_7_4_34_InventoryRemainsConsistent()
        {
            SetupTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject progGO, out ProgressionManager prog);
            Inventory.Inventory inv = Inventory.Inventory.Instance;
            inv.Clear();

            EquipmentInstance itm1 = new EquipmentInstance("itm1", "Ring 1", EquipmentSlotType.Ring, 1, null, null);
            EquipmentInstance itm2 = new EquipmentInstance("itm2", "Ring 2", EquipmentSlotType.Ring, 1, null, null);
            inv.AddItem(itm1);
            inv.AddItem(itm2);

            bool hasBoth = inv.HasItem(itm1.InstanceId) && inv.HasItem(itm2.InstanceId) && inv.Items.Count == 2;
            inv.RemoveItem(itm1);
            bool removed1 = !inv.HasItem(itm1.InstanceId) && inv.HasItem(itm2.InstanceId) && inv.Items.Count == 1;

            bool ok = hasBoth && removed1;
            Debug.Log($"[P05.7.4-34] Inventory remains consistent -> HasBoth: {hasBoth}, Removed1: {removed1} | {(ok ? "PASS" : "FAIL")}");

            TeardownTestEncounter(heroGO, bmGO, progGO);
            return ok;
        }

