            bm.CompleteLootDecisionAndResume(equip: true, dismantle: false);

            bool staysDead = (!hero.IsAlive && bm.CurrentBattleState == BattleState.AwaitingPlayerStart && !bm.IsBattleActive);
            Debug.Log($"[P05.7.4-35] Hero death state cannot be bypassed by loot transaction -> StaysDead: {staysDead}, State: {bm.CurrentBattleState} | {(staysDead ? "PASS" : "FAIL")}");

            TeardownTestEncounter(heroGO, bmGO, progGO);
            return staysDead;
        }

