        private static bool P05_8_01_MonsterDeathAwardsExpAndGoldNormally()
        {
            SetupTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject progGO, out ProgressionManager prog);
            GameObject resGO = new GameObject("TestResMgr");
            ResourceManager resMgr = resGO.AddComponent<ResourceManager>();

            float initialExp = prog.CurrentExp;
            int initialGold = resMgr.Gold;

            prog.AddExp(50f);
            resMgr.AddGold(100);

            bool ok = Mathf.Approximately(prog.CurrentExp, initialExp + 50f) && (resMgr.Gold == initialGold + 100);
            Debug.Log($"[P05.8-01] Monster death awards EXP & Gold normally -> EXP: {prog.CurrentExp}, Gold: {resMgr.Gold} | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(resGO);
            TeardownTestEncounter(heroGO, bmGO, progGO);
            return ok;
        }

