        private static bool P05_8_08_LootTierRarityWeightsTotal100Percent()
        {
            DropLevelDatabaseSO dlDb = Resources.Load<DropLevelDatabaseSO>("Data/DropLevelDatabase");
            bool ok = true;
            if (dlDb != null && dlDb.DropLevels != null)
            {
                foreach (var dl in dlDb.DropLevels)
                {
                    if (dl == null) continue;
                    float sum = 0f;
                    foreach (var rw in dl.RarityWeights) sum += rw.WeightPercentage;
                    if (Mathf.Abs(sum - 100f) > 0.1f && sum > 0f) ok = false;
                }
            }
            Debug.Log($"[P05.8-08] LootTier rarity weights total 100% -> Valid: {ok} | {(ok ? "PASS" : "FAIL")}");
            return ok;
        }

