        private static bool P05_8_14_NoDuplicateAffixesOnGeneratedEquipment()
        {
            AffixDatabaseSO affDb = Resources.Load<AffixDatabaseSO>("Data/AffixDatabase");
            RarityDefinitionSO r = ScriptableObject.CreateInstance<RarityDefinitionSO>();
            r.InitializeRarity("r_test", "Test Rarity", Color.magenta, 4, 4, 5, 2.0f);

            var affixes = AffixGenerator.GenerateAffixes(affDb, EquipmentSlotType.Armor, r, 10);
            HashSet<string> seen = new HashSet<string>();
            bool hasDuplicate = false;
            foreach (var a in affixes)
            {
                if (seen.Contains(a.AffixId)) hasDuplicate = true;
                seen.Add(a.AffixId);
            }

            bool ok = !hasDuplicate && affixes.Count > 0;
            Debug.Log($"[P05.8-14] No duplicate affixes on equipment -> UniqueCount: {seen.Count}, Total: {affixes.Count} | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(r);
            return ok;
        }

