        private static bool P05_8_22_EquipTransactionEquipsNewItemMovesOldToInventoryAndResumesCombat()
        {
            SetupTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject progGO, out ProgressionManager prog);
            EquipmentManager eq = EquipmentManager.Instance;
            Inventory.Inventory inv = Inventory.Inventory.Instance;
            inv.Clear();

            EquipmentInstance oldItem = new EquipmentInstance("old_w", "Old Sword", EquipmentSlotType.Weapon, 1, null, null);
            eq.EquipToSlot(EquipmentSlotType.Weapon, oldItem);

            EquipmentInstance newItem = new EquipmentInstance("new_w", "New Sword", EquipmentSlotType.Weapon, 5, null, null, 5, 16);
            typeof(BattleManager).GetField("pendingLootItem", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance).SetValue(bm, newItem);

            bm.CompleteLootDecisionAndResume(equip: true, dismantle: false);

            bool ok = (eq.GetEquippedItem(EquipmentSlotType.Weapon) == newItem) && inv.HasItem(oldItem.InstanceId);
            Debug.Log($"[P05.8-22] Equip transaction equips new item & moves old to inventory -> Equipped: {eq.GetEquippedItem(EquipmentSlotType.Weapon)?.ItemName}, OldInInv: {inv.HasItem(oldItem.InstanceId)} | {(ok ? "PASS" : "FAIL")}");

            TeardownTestEncounter(heroGO, bmGO, progGO);
            return ok;
        }

        private static bool P05_8_23_TachTransactionDismantlesNewItemKeepsOldAndResumesCombat()
        {
            SetupTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject progGO, out ProgressionManager prog);
            EquipmentManager eq = EquipmentManager.Instance;
            Inventory.Inventory inv = Inventory.Inventory.Instance;
            inv.Clear();

            EquipmentInstance oldItem = new EquipmentInstance("old_w", "Old Sword", EquipmentSlotType.Weapon, 1, null, null);
            eq.EquipToSlot(EquipmentSlotType.Weapon, oldItem);

            EquipmentInstance newItem = new EquipmentInstance("new_w", "New Sword", EquipmentSlotType.Weapon, 5, null, null, 5, 16);
            inv.AddItem(newItem);
            typeof(BattleManager).GetField("pendingLootItem", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance).SetValue(bm, newItem);

            bm.CompleteLootDecisionAndResume(equip: false, dismantle: true);

            bool ok = (eq.GetEquippedItem(EquipmentSlotType.Weapon) == oldItem) && (!inv.HasItem(newItem.InstanceId));
            Debug.Log($"[P05.8-23] Tách transaction dismantles new item & keeps old -> Equipped: {eq.GetEquippedItem(EquipmentSlotType.Weapon)?.ItemName}, NewRemoved: {!inv.HasItem(newItem.InstanceId)} | {(ok ? "PASS" : "FAIL")}");

            TeardownTestEncounter(heroGO, bmGO, progGO);
            return ok;
        }

