        private static bool P05_9_10_UpgradeTransactionIsAtomic()
        {
            GameObject mgrGO = new GameObject("TestLootProgMgr");
            LootTierProgressionManager mgr = mgrGO.AddComponent<LootTierProgressionManager>();
            mgr.LoadDatabaseIfMissing();
            mgr.SetMockTier(1);
            mgr.SetMockProgress(50); // Insufficient

            int tierBefore = mgr.CurrentTierId;
            int progBefore = mgr.CurrentProgress;
            bool started = mgr.StartUpgrade();

            bool atomic = (!started) && (mgr.CurrentTierId == tierBefore) && (mgr.CurrentProgress == progBefore) && (!mgr.IsUpgrading);
            Debug.Log($"[P05.9-10] Upgrade transaction is atomic on failure -> Started: {started}, Tier: {mgr.CurrentTierId}, Prog: {mgr.CurrentProgress} | {(atomic ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(mgrGO);
            LootTierProgressionManager.ResetInstance();
            return atomic;
        }

