        private static bool P05_9_19_CombatRegressionPass()
        {
            SetupTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject progGO, out ProgressionManager prog);
            bm.StartBattle();

            float initialHeroHp = hero.Health.CurrentHealth;
            float initialMonsterHp = bm.CurrentMonster.Health.CurrentHealth;

            BasicAttackProcessor.ExecuteBasicAttack(hero, bm.CurrentMonster);
            BasicAttackProcessor.ExecuteBasicAttack(bm.CurrentMonster, hero);

            bool heroDamaged = hero.Health.CurrentHealth < initialHeroHp;
            bool monsterDamaged = bm.CurrentMonster.Health.CurrentHealth < initialMonsterHp;
            bool ok = heroDamaged && monsterDamaged;
            Debug.Log($"[P05.9-19] Combat regression PASS -> HeroDamaged: {heroDamaged}, MonsterDamaged: {monsterDamaged} | {(ok ? "PASS" : "FAIL")}");

            TeardownTestEncounter(heroGO, bmGO, progGO);
            return ok;
        }

        private static bool P05_9_20_EquipmentRegressionPass()
        {
            SetupTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject progGO, out ProgressionManager prog);
            EquipmentManager eq = EquipmentManager.Instance;
            Inventory.Inventory inv = Inventory.Inventory.Instance;
            inv.Clear();

            EquipmentInstance oldItem = new EquipmentInstance("old_w", "Old Weapon", EquipmentSlotType.Weapon, 1, null, null);
            eq.EquipToSlot(EquipmentSlotType.Weapon, oldItem);

            EquipmentInstance newItem = new EquipmentInstance("new_w", "New Weapon", EquipmentSlotType.Weapon, 5, null, null, 5, 2);
            typeof(BattleManager).GetField("pendingLootItem", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance).SetValue(bm, newItem);

            bm.CompleteLootDecisionAndResume(equip: true, dismantle: false);

            bool ok = eq.GetEquippedItem(EquipmentSlotType.Weapon) == newItem && inv.HasItem(oldItem.InstanceId);
            Debug.Log($"[P05.9-20] Equipment regression PASS -> Equipped: {eq.GetEquippedItem(EquipmentSlotType.Weapon)?.ItemName}, OldInInv: {inv.HasItem(oldItem.InstanceId)} | {(ok ? "PASS" : "FAIL")}");

            TeardownTestEncounter(heroGO, bmGO, progGO);
            return ok;
        }

