        private static bool D23_1_07_ProbabilityTableTotalEquals100Percent()
        {
            LootTierProgressionManager.ResetInstance();
            GameObject mgrGO = new GameObject("TestLootProgMgr");
            LootTierProgressionManager mgr = mgrGO.AddComponent<LootTierProgressionManager>();
            mgr.LoadDatabaseIfMissing();

            bool allValid = true;
            if (mgr.Database != null && mgr.Database.Tiers != null)
            {
                foreach (var tier in mgr.Database.Tiers)
                {
                    if (tier == null || !tier.Validate(out _))
                    {
                        allValid = false;
                        break;
                    }
                    float sum = 0f;
                    foreach (var rw in tier.RarityWeights) sum += rw.WeightPercentage;
                    if (Mathf.Abs(sum - 100f) > 0.1f)
                    {
                        allValid = false;
                        break;
                    }
                }
            }

            Debug.Log($"[D23.1-07] Probability table total = 100% for all tiers -> AllValid: {allValid} | {(allValid ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(mgrGO);
            LootTierProgressionManager.ResetInstance();
            return allValid;
        }

        private static bool D23_1_08_LockedRarityCannotDrop()
        {
            RarityDefinitionSO rCommon = ScriptableObject.CreateInstance<RarityDefinitionSO>();
            rCommon.InitializeRarity("r_common", "Common", Color.white, 1, 1, 2, 1f);

            RarityDefinitionSO rLegendary = ScriptableObject.CreateInstance<RarityDefinitionSO>();
            rLegendary.InitializeRarity("r_legendary", "Legendary", Color.yellow, 5, 4, 5, 2f);

            LootTierConfigSO tierCfg = ScriptableObject.CreateInstance<LootTierConfigSO>();
            tierCfg.InitializeTier(1, "Tier 1", new List<RarityWeightData>
            {
                new RarityWeightData(rCommon, 100f),
                new RarityWeightData(rLegendary, 0f) // Locked
            });

            bool legendaryDropped = false;
            for (int i = 0; i < 200; i++)
            {
                RarityDefinitionSO rolled = tierCfg.RollRarity();
                if (rolled == rLegendary)
                {
                    legendaryDropped = true;
                    break;
                }
            }

            bool ok = !legendaryDropped && !tierCfg.IsRarityUnlocked("r_legendary");
            Debug.Log($"[D23.1-08] Locked rarity cannot drop -> LegendaryDropped: {legendaryDropped}, IsUnlocked: {tierCfg.IsRarityUnlocked("r_legendary")} | {(ok ? "PASS" : "FAIL")}");
            return ok;
        }

