        private static bool D23_1_15_FullEncounterCycleWithLootTierDropAndCombatResume()
        {
            SetupTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject progGO, out ProgressionManager prog);
            DropSystem.ResetInstance();
            LootTierProgressionManager.ResetInstance();

            GameObject mgrGO = new GameObject("TestLootProgMgr");
            LootTierProgressionManager mgr = mgrGO.AddComponent<LootTierProgressionManager>();
            mgr.LoadDatabaseIfMissing();
            mgr.SetMockTier(2);

            GameObject dropGO = new GameObject("TestDropSys");
            DropSystem dropSys = dropGO.AddComponent<DropSystem>();
            dropSys.LoadDatabasesIfMissing();
            dropSys.NormalMonsterDropRate = 100f;

            bm.StartBattle();
            Monster m = bm.CurrentMonster;
            m.Health.TakeDamage(99999f); // Kill monster -> triggers drop -> pauses combat

            bool isPaused = (bm.CurrentBattleState == BattleState.LootPending);
            bm.CompleteLootDecisionAndResume(equip: true, dismantle: false);

            bool resumed = (bm.CurrentBattleState != BattleState.LootPending);
            bool ok = isPaused && resumed;
            Debug.Log($"[D23.1-15] Full encounter cycle with LootTier drop & combat resume -> WasPaused: {isPaused}, Resumed: {resumed} | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(dropGO);
            Object.DestroyImmediate(mgrGO);
            DropSystem.ResetInstance();
            LootTierProgressionManager.ResetInstance();
            TeardownTestEncounter(heroGO, bmGO, progGO);
            return ok;
        }

