        private static bool D23_1_H02_LootTierDoesNotMaintainDuplicateGold()
        {
            var fields = typeof(LootTierProgressionManager).GetFields(System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance);
            bool hasDuplicateGoldField = false;
            foreach (var f in fields)
            {
                string name = f.Name.ToLower();
                if (name.Contains("gold") || name.Contains("playergold") || name.Contains("ownedgold"))
                {
                    hasDuplicateGoldField = true;
                    break;
                }
            }

            bool ok = !hasDuplicateGoldField;
            Debug.Log($"[D23.1.H02] Loot Tier does not maintain duplicate Gold field -> HasDuplicate: {hasDuplicateGoldField} | {(ok ? "PASS" : "FAIL")}");
            return ok;
        }

