        private static bool D23_1_H05_UpgradeConsumesGoldCorrectly()
        {
            ResourceManager.ResetInstance();
            GameObject resGO = new GameObject("TestRes");
            ResourceManager res = resGO.AddComponent<ResourceManager>();
            res.SetResources(8200, 14);

            RarityDefinitionSO r1 = ScriptableObject.CreateInstance<RarityDefinitionSO>();
            r1.InitializeRarity("r1", "R1", Color.white, 1, 1, 2, 1f);

            LootTierConfigSO t1 = ScriptableObject.CreateInstance<LootTierConfigSO>();
            t1.InitializeTier(1, "Tier 1", new List<RarityWeightData> { new RarityWeightData(r1, 100f) }, 0, 0f, 5000, 2);
            LootTierConfigSO t2 = ScriptableObject.CreateInstance<LootTierConfigSO>();
            t2.InitializeTier(2, "Tier 2", new List<RarityWeightData> { new RarityWeightData(r1, 100f) });

            LootTierDatabaseSO db = ScriptableObject.CreateInstance<LootTierDatabaseSO>();
            db.SetTiers(new List<LootTierConfigSO> { t1, t2 });

            LootTierProgressionManager.ResetInstance();
            GameObject mgrGO = new GameObject("TestLootProgMgr");
            LootTierProgressionManager mgr = mgrGO.AddComponent<LootTierProgressionManager>();
            mgr.SetDatabase(db);
            mgr.SetMockTier(1);

            bool started = mgr.StartUpgrade();
