            upgInfoGO.transform.SetParent(canvasGO.transform);
            var upgInfoTmp = upgInfoGO.AddComponent<TMPro.TextMeshProUGUI>();

            ui.SetReferences(canvasGO, null, null, null, null, null, null, upgInfoTmp, null, null, null, null, null);
            ui.RefreshUI();

            bool initial0 = upgInfoTmp.text.Contains("0");

            // Click debug +1K G
            GameObject debugUIGO = new GameObject("DebugUI");
            EquipmentDropDebugUI debugUI = debugUIGO.AddComponent<EquipmentDropDebugUI>();
