            bool updated1000 = upgInfoTmp.text.Contains("1,000") || upgInfoTmp.text.Contains("1.000") || upgInfoTmp.text.Contains("1000");
            bool ok = initial0 && updated1000;

            Debug.Log($"[D23.1.H13] Debug +1K G updates Loot Tier UI -> Initial: {initial0}, AfterAdd: {updated1000}, Text: '{upgInfoTmp.text}' | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(debugUIGO);
            Object.DestroyImmediate(canvasGO);
            Object.DestroyImmediate(mgrGO);
            Object.DestroyImmediate(resGO);
            LootTierProgressionManager.ResetInstance();
            ResourceManager.ResetInstance();
            return ok;
        }

