        [MenuItem("Tools/Wuxia RPG/Run Prototype 05 / D24 Tests (Title Breakthrough)")]
        public static bool RunAllPrototype05_D24Tests()
        {
            int passed = 0;
            int total = 25;
            Debug.Log("==================================================");
            Debug.Log("   PROTOTYPE 05 / D24 - TITLE BREAKTHROUGH & LEVEL CAP TESTS");
            Debug.Log("==================================================");

            if (D24_01_InitialLevelCapIsCorrect()) passed++;
            if (D24_02_HeroCanLevelNormallyBelowLevelCap()) passed++;
            if (D24_03_HeroCannotExceedLevelCap()) passed++;
            if (D24_04_ExpReceivedAtLevelCapIsRetained()) passed++;
            if (D24_05_ExpReceivedAtLevelCapDoesNotIncreaseLevel()) passed++;
            if (D24_06_FirstBreakthroughRequiresLevel5()) passed++;
            if (D24_07_Breakthrough2RequirementIsLevel15()) passed++;
            if (D24_08_Breakthrough3RequirementIsLevel25()) passed++;
            if (D24_09_Breakthrough4RequirementIsLevel40()) passed++;
            if (D24_10_Breakthrough5RequirementIsLevel60()) passed++;
            if (D24_11_FormulaUsesNDirectlyAndNotNPlus1()) passed++;
            if (D24_12_BreakthroughCannotHappenBelowRequiredLevel()) passed++;
            if (D24_13_BreakthroughCannotHappenWhenGoldIsInsufficient()) passed++;
            if (D24_14_BreakthroughCannotHappenWhenMaterialIsInsufficient()) passed++;
            if (D24_15_FailedBreakthroughConsumesNothing()) passed++;
            if (D24_16_SuccessfulBreakthroughIncrementsBreakthroughCount()) passed++;
            if (D24_17_SuccessfulBreakthroughUpdatesLevelCap()) passed++;
            if (D24_18_StoredExpIsPreservedAfterBreakthrough()) passed++;
            if (D24_19_StoredExpIsConsumedToLevelAutomaticallyAfterBreakthrough()) passed++;
            if (D24_20_HeroStopsAgainWhenReachingTheNewLevelCap()) passed++;
            if (D24_21_SaveLoadPreservesBreakthroughCount()) passed++;
            if (D24_22_SaveLoadPreservesLevelCap()) passed++;
            if (D24_23_SaveLoadPreservesStoredExp()) passed++;
            if (D24_24_ExistingPrototype05EquipmentSystemsRemainFunctional()) passed++;
            if (D24_25_FullProgressionCycleWorksCorrectly()) passed++;

            Debug.Log("==================================================");
            Debug.Log($"   PROTOTYPE 05 / D24 TOTAL: {passed}/{total} PASSED");
            Debug.Log("==================================================");
            return passed == total;
        }

        private static bool D24_01_InitialLevelCapIsCorrect()
        {
            TitleBreakthroughManager.ResetInstance();
            ProgressionManager.ResetInstance();

            GameObject tbkGO = new GameObject("TestTitleBkMgr");
            TitleBreakthroughManager tbkMgr = tbkGO.AddComponent<TitleBreakthroughManager>();
            tbkMgr.ResetPersistence();

            GameObject progGO = new GameObject("TestProgMgr");
            ProgressionManager prog = progGO.AddComponent<ProgressionManager>();

            int cap = prog.GetEffectiveLevelCap();
            int tbkCap = tbkMgr.CurrentLevelCap;

            bool ok = (cap == 5) && (tbkCap == 5);
            Debug.Log($"[D24_01] Initial Level Cap is correct -> Progression Cap: {cap}, Title Cap: {tbkCap} (Expected 5) | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(progGO);
            Object.DestroyImmediate(tbkGO);
            TitleBreakthroughManager.ResetInstance();
            ProgressionManager.ResetInstance();
            return ok;
        }

