        private static bool D24_12_BreakthroughCannotHappenBelowRequiredLevel()
        {
            ResourceManager.ResetInstance();
            TitleBreakthroughManager.ResetInstance();
            ProgressionManager.ResetInstance();

            GameObject resGO = new GameObject("TestRes");
            ResourceManager res = resGO.AddComponent<ResourceManager>();
            res.SetResources(100000, 1000);

            GameObject tbkGO = new GameObject("TestTitleBkMgr");
            TitleBreakthroughManager tbkMgr = tbkGO.AddComponent<TitleBreakthroughManager>();
            tbkMgr.LoadDatabaseIfMissing();
            tbkMgr.SetMockStage(0); // Req Lv. 5

            GameObject progGO = new GameObject("TestProgMgr");
            ProgressionManager prog = progGO.AddComponent<ProgressionManager>();
            prog.SetMockLevel(4);

            bool canBk = tbkMgr.CanBreakthrough();
            bool ok = !canBk;
