        private static bool D24_25_FullProgressionCycleWorksCorrectly()
        {
            ResourceManager.ResetInstance();
            TitleBreakthroughManager.ResetInstance();
            ProgressionManager.ResetInstance();
            LootTierProgressionManager.ResetInstance();

            GameObject resGO = new GameObject("TestRes");
            ResourceManager res = resGO.AddComponent<ResourceManager>();
            res.SetResources(1000000, 10000);
            LootTierProgressionManager lt = resGO.AddComponent<LootTierProgressionManager>();

            GameObject tbkGO = new GameObject("TestTitleBkMgr");
            TitleBreakthroughManager tbkMgr = tbkGO.AddComponent<TitleBreakthroughManager>();
            tbkMgr.LoadDatabaseIfMissing();
            tbkMgr.ResetPersistence();

            GameObject progGO = new GameObject("TestProgMgr");
            ProgressionManager prog = progGO.AddComponent<ProgressionManager>();
            prog.InitializeProgression(1, 0f);

            // Step 1: Start at Lv.1 / Cap 5 -> add EXP to cap at 5
            prog.AddExp(500000f);
            bool step1 = (prog.CurrentLevel == 5) && (tbkMgr.CurrentLevelCap == 5);

            // Step 2: Perform Breakthrough #1 -> Cap becomes 10, Next Req becomes 10
            lt.SetMockTier(2);
            tbkMgr.TryPerformBreakthrough();
            bool step2 = (tbkMgr.CurrentBreakthroughCount == 1) && (tbkMgr.CurrentLevelCap == 10) && (prog.CurrentLevel == 10);

            // Step 3: Perform Breakthrough #2 -> Cap becomes 20, Next Req becomes 20
            lt.SetMockTier(3);
            prog.AddExp(500000f);
            tbkMgr.TryPerformBreakthrough();
            bool step3 = (tbkMgr.CurrentBreakthroughCount == 2) && (tbkMgr.CurrentLevelCap == 20) && (prog.CurrentLevel == 20);

            // Step 4: Perform Breakthrough #3 -> Cap becomes 35, Next Req becomes 35
            lt.SetMockTier(4);
            prog.AddExp(500000f);
            tbkMgr.TryPerformBreakthrough();
            bool step4 = (tbkMgr.CurrentBreakthroughCount == 3) && (tbkMgr.CurrentLevelCap == 35) && (prog.CurrentLevel == 35);

            // Step 5: Perform Breakthrough #4 -> Cap becomes 55, Next Req becomes 55
            lt.SetMockTier(5);
            prog.AddExp(500000f);
            tbkMgr.TryPerformBreakthrough();
            bool step5 = (tbkMgr.CurrentBreakthroughCount == 4) && (tbkMgr.CurrentLevelCap == 55) && (prog.CurrentLevel == 55);

            bool ok = step1 && step2 && step3 && step4 && step5;
            Debug.Log($"[D24_25] Full progression cycle works correctly -> S1(5): {step1}, S2(10): {step2}, S3(20): {step3}, S4(35): {step4}, S5(55): {step5} | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(progGO);
            Object.DestroyImmediate(tbkGO);
            Object.DestroyImmediate(resGO);
            LootTierProgressionManager.ResetInstance();
            ResourceManager.ResetInstance();
            TitleBreakthroughManager.ResetInstance();
            ProgressionManager.ResetInstance();
            return ok;
        }

