        private static bool TBREQ_05_OpeningBreakthroughPanelDoesNotPauseCombat()
        {
            TitleBreakthroughManager.ResetInstance();
            TitleBreakthroughUI.ResetInstance();
            BattleManager.ResetInstance();

            GameObject mgrGO = new GameObject("TestMgr");
            BattleManager bm = mgrGO.AddComponent<BattleManager>();
            TitleBreakthroughManager tbkMgr = mgrGO.AddComponent<TitleBreakthroughManager>();
            tbkMgr.LoadDatabaseIfMissing();

            GameObject panelGO = new GameObject("Panel");
            GameObject canvasGO = new GameObject("Canvas");
            TitleBreakthroughUI ui = canvasGO.AddComponent<TitleBreakthroughUI>();
            ui.SetReferences(panelGO, null, null, null, null, null, null, null, null, null, null, null, null);

            bm.ResumeCombat();
            ui.ShowPanel();

            bool combatPaused = bm.IsCombatPausedByUI;
            bool ok = !combatPaused;
