        private static bool TBREQ_15_HeroSpecificRequirements()
        {
            TitleBreakthroughManager.ResetInstance();
            ProgressionManager.ResetInstance();
            ResourceManager.ResetInstance();

            // Create custom database for Hero B with LootTier >= 4
            var customDb = ScriptableObject.CreateInstance<TitleBreakthroughDatabaseSO>();
            var cfg0 = ScriptableObject.CreateInstance<TitleBreakthroughConfigSO>();
            cfg0.InitializeBreakthrough("heroB_00", "Custom Title 0", 0, 5, 10, 5, 0, 0, 1000f, 100f, 20f, 0f, 0f, 0f, "", 0, "",
                new List<BreakthroughRequirement>
                {
                    new BreakthroughRequirement(BreakthroughRequirementType.HeroLevel, 5),
                    new BreakthroughRequirement(BreakthroughRequirementType.LootTier, 4)
                });
            var cfg1 = ScriptableObject.CreateInstance<TitleBreakthroughConfigSO>();
            cfg1.InitializeBreakthrough("heroB_01", "Custom Title 1", 1, 10, 20, 10, 0, 0, 1200f, 150f, 40f);
            customDb.SetBreakthroughs(new List<TitleBreakthroughConfigSO> { cfg0, cfg1 });

            GameObject heroGO = new GameObject("HeroB");
            Hero hero = heroGO.AddComponent<Hero>();
            HeroConfigSO heroCfg = ScriptableObject.CreateInstance<HeroConfigSO>();
            heroCfg.SetBreakthroughProfile(customDb);
            hero.SetHeroConfig(heroCfg);

            GameObject mgrGO = new GameObject("TestMgr");
            TitleBreakthroughManager tbkMgr = mgrGO.AddComponent<TitleBreakthroughManager>();
            LootTierProgressionManager lt = mgrGO.AddComponent<LootTierProgressionManager>();
            lt.SetMockTier(2); // Meets default (Tier 2), but FAILS Hero B (Tier 4)
            ProgressionManager prog = mgrGO.AddComponent<ProgressionManager>();
            prog.InitializeProgression(5, 0f, 0);

            var eval = tbkMgr.EvaluateBreakthrough();
            bool ok = !eval.CanBreakthrough && (eval.RequiredLootTier == 4);
            Debug.Log($"[TBREQ_15] Hero-specific requirements -> RequiredLootTier: {eval.RequiredLootTier}, CanBk: {eval.CanBreakthrough} | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(heroGO);
            Object.DestroyImmediate(mgrGO);
            LootTierProgressionManager.ResetInstance();
            ResourceManager.ResetInstance();
            TitleBreakthroughManager.ResetInstance();
            ProgressionManager.ResetInstance();
            return ok;
        }

