        #region Prototype 05 / Hotfix Tests - Title Breakthrough Must Never Be Automatic

        [MenuItem("Tools/Wuxia RPG/Run Prototype 05 / Hotfix Tests (Non-Automatic Breakthrough)")]
        public static bool RunAllPrototype05_HotfixTests()
        {
            int passed = 0;
            int total = 11;
            Debug.Log("==================================================");
            Debug.Log("   PROTOTYPE 05 / HOTFIX - NON-AUTOMATIC BREAKTHROUGH TESTS");
            Debug.Log("==================================================");

            if (HOTFIX_01_HeroReachesLevel5()) passed++;
            if (HOTFIX_02_HeroReceivesExpWhileLevel5CapReached()) passed++;
            if (HOTFIX_03_WaitingAtLevelCapForMultipleExpRewards()) passed++;
            if (HOTFIX_04_BreakthroughAvailabilityBecomesTrue()) passed++;
            if (HOTFIX_05_NoAutomaticResourceConsumption()) passed++;
            if (HOTFIX_06_PlayerPressesBreakthrough()) passed++;
            if (HOTFIX_07_StoredExpRemainsAfterBreakthrough()) passed++;
            if (HOTFIX_08_StoredExpCanThenCauseLevelProgression()) passed++;
            if (HOTFIX_09_HeroEventuallyReachesNewCap()) passed++;
            if (HOTFIX_10_HeroDoesNotAutomaticallyPerformBreakthrough2()) passed++;
            if (HOTFIX_11_OnlyPressingBreakthroughCanExecuteBreakthrough2()) passed++;

            Debug.Log("==================================================");
            Debug.Log($"   PROTOTYPE 05 / HOTFIX TOTAL: {passed}/{total} PASSED");
            Debug.Log("==================================================");
            return passed == total;
        }

        private static bool HOTFIX_01_HeroReachesLevel5()
        {
            TitleBreakthroughManager.ResetInstance();
            ProgressionManager.ResetInstance();

            GameObject tbkGO = new GameObject("TestTitleBkMgr");
            TitleBreakthroughManager tbkMgr = tbkGO.AddComponent<TitleBreakthroughManager>();
            tbkMgr.ResetPersistence();

            GameObject progGO = new GameObject("TestProgMgr");
            ProgressionManager prog = progGO.AddComponent<ProgressionManager>();
            prog.InitializeProgression(1, 0f);

            // Add EXP to reach Level 5 exactly
            float expFor5 = prog.GetRequiredExpForLevel(1) + prog.GetRequiredExpForLevel(2) + prog.GetRequiredExpForLevel(3) + prog.GetRequiredExpForLevel(4);
            prog.AddExp(expFor5);

            bool ok = (prog.CurrentLevel == 5) && (tbkMgr.CurrentLevelCap == 5) && (tbkMgr.BreakthroughCount == 0);
            Debug.Log($"[HOTFIX_01] Hero reaches Level 5 -> Level: {prog.CurrentLevel}, Cap: {tbkMgr.CurrentLevelCap}, Count: {tbkMgr.BreakthroughCount} | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(progGO);
            Object.DestroyImmediate(tbkGO);
            TitleBreakthroughManager.ResetInstance();
            ProgressionManager.ResetInstance();
            return ok;
        }

