        [MenuItem("Tools/Wuxia RPG/Run Count Fix Tests (14 Tests)")]
        public static bool RunAllPrototype05_CountFixTests()
        {
            int passed = 0;
            int total = 14;
            Debug.Log("==================================================");
            Debug.Log("   PROTOTYPE 05 / COUNT_FIX - TITLE BREAKTHROUGH COUNT DISPLAY & 1ST BK LOGIC");
            Debug.Log("==================================================");

            if (COUNT_FIX_01_FreshHeroHasBreakthroughCount0()) passed++;
            if (COUNT_FIX_02_FreshHeroUIDisplaysCurrentBreakthrough0()) passed++;
            if (COUNT_FIX_03_OpeningBreakthroughPanelDoesNotIncrementCount()) passed++;
            if (COUNT_FIX_04_EvaluatingRequirementsDoesNotIncrementCount()) passed++;
            if (COUNT_FIX_05_ReachingLevel5DoesNotIncrementCount()) passed++;
            if (COUNT_FIX_06_ReachingLevel5DisplaysNextBreakthrough1()) passed++;
            if (COUNT_FIX_07_NextBreakthrough1RequiresLevel5()) passed++;
            if (COUNT_FIX_08_NextCapAfterBreakthrough1Is15()) passed++;
            if (COUNT_FIX_09_SuccessfulBreakthrough1ChangesCount0To1()) passed++;
            if (COUNT_FIX_10_AfterBreakthrough1UIDisplaysCurrentBreakthrough1()) passed++;
            if (COUNT_FIX_11_AfterBreakthrough1NextBreakthroughIs2()) passed++;
            if (COUNT_FIX_12_Breakthrough2RequiresLevel15()) passed++;
            if (COUNT_FIX_13_SuccessfulBreakthrough2ChangesCount1To2()) passed++;
            if (COUNT_FIX_14_AfterBreakthrough2NextCapIs25()) passed++;

            Debug.Log("==================================================");
            Debug.Log($"   PROTOTYPE 05 / COUNT_FIX TOTAL: {passed}/{total} PASSED");
