        #region Prototype 05 State Fix Tests (STATE_FIX_01 - STATE_FIX_20)

        [MenuItem("Tools/Wuxia RPG/Run Prototype 05 State Fix Tests (STATE_FIX_01 to STATE_FIX_20)")]
        public static bool RunAllPrototype05_StateFixTests()
        {
            Debug.Log("==================================================");
            Debug.Log("   STARTING PROTOTYPE 05 STATE FIX TESTS (STATE_FIX_01 to STATE_FIX_20)");
            Debug.Log("==================================================");

            int passed = 0;
            int total = 20;

            if (STATE_FIX_01_FreshProgressionStartsWithBreakthroughCountZero()) passed++;
            if (STATE_FIX_02_FreshProgressionStartsWithLevelCapFive()) passed++;
            if (STATE_FIX_03_FreshProgressionStartsWithCurrentTitleNoviceDisciple()) passed++;
            if (STATE_FIX_04_OpeningBreakthroughUIDoesNotChangeCount()) passed++;
            if (STATE_FIX_05_EvaluatingRequirementsDoesNotChangeCount()) passed++;
            if (STATE_FIX_06_ReachingLevelFiveDoesNotChangeCount()) passed++;
            if (STATE_FIX_07_ExpAtLevelFiveDoesNotChangeCount()) passed++;
            if (STATE_FIX_08_ExpAtLevelFiveDoesNotIncreaseLevelBeyondFive()) passed++;
            if (STATE_FIX_09_InsufficientBreakthroughRequirementsDoNotChangeCount()) passed++;
            if (STATE_FIX_10_InsufficientRequirementsDoNotConsumeResources()) passed++;
            if (STATE_FIX_11_SuccessfulFirstBreakthroughChangesCountZeroToOne()) passed++;
            if (STATE_FIX_12_SuccessfulFirstBreakthroughChangesCapFiveToFifteen()) passed++;
            if (STATE_FIX_13_SuccessfulSecondBreakthroughChangesCountOneToTwo()) passed++;
            if (STATE_FIX_14_SuccessfulSecondBreakthroughChangesCapFifteenToTwentyFive()) passed++;
            if (STATE_FIX_15_NoAutomaticSecondBreakthrough()) passed++;
            if (STATE_FIX_16_NoAutomaticThirdBreakthrough()) passed++;
            if (STATE_FIX_17_CurrentCountAndNextCountAreDisplayedSeparately()) passed++;
            if (STATE_FIX_18_InvalidStateDetectionCatchesMismatch()) passed++;
            if (STATE_FIX_19_ResetProgressionReturnsZeroCapFiveLvOne()) passed++;
            if (STATE_FIX_20_SaveLoadPreservesLegitimateProgressionState()) passed++;

            Debug.Log("==================================================");
            Debug.Log($"   PROTOTYPE 05 / STATE_FIX TOTAL: {passed}/{total} {(passed == total ? "PASSED" : "FAILED")}");
            Debug.Log("==================================================");

            // Clean up persistent state after tests so no test mock leaks into real Play Mode
            PlayerPrefs.DeleteKey("TLTD_Title_StageIndex");
            PlayerPrefs.DeleteKey("TLTD_Hero_Level");
            PlayerPrefs.DeleteKey("TLTD_Hero_Exp");
            PlayerPrefs.DeleteKey("TLTD_Hero_TitleIndex");
            PlayerPrefs.Save();

            return passed == total;
        }

