        private static bool P06_01_MultipleMindMethodsOwned()
        {
            MindMethodManager.ResetInstance();
            EventBus.ClearAllListeners();

            GameObject go = new GameObject("TestMMM");
            MindMethodManager mgr = go.AddComponent<MindMethodManager>();
            mgr.LoadDatabaseIfMissing();
            mgr.InitializeFromDatabase();

            bool taijiUnlocked = mgr.IsMindMethodUnlocked("mm_taiji");
            mgr.UnlockMindMethod("mm_nine_yang");
            bool nineYangUnlocked = mgr.IsMindMethodUnlocked("mm_nine_yang");

            bool ok = taijiUnlocked && nineYangUnlocked;
            Debug.Log($"[P06_01] Multiple Mind Methods can be owned -> Taiji: {taijiUnlocked}, NineYang: {nineYangUnlocked} | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(go);
            MindMethodManager.ResetInstance();
            EventBus.ClearAllListeners();
            return ok;
        }

