        private static bool P06_06_EveryMindMethodHasExactly5SkillSlots()
        {
            MindMethodManager.ResetInstance();
            EventBus.ClearAllListeners();

            GameObject go = new GameObject("TestMMM");
            MindMethodManager mgr = go.AddComponent<MindMethodManager>();
            mgr.LoadDatabaseIfMissing();
            mgr.InitializeFromDatabase();

            bool ok = true;
            foreach (var mm in mgr.Database.MindMethods)
            {
                if (mm == null) continue;
                for (int slotIdx = 1; slotIdx <= 5; slotIdx++)
                {
                    SkillSlotType slot = (SkillSlotType)slotIdx;
                    var skillsInSlot = mm.GetSkillsForSlot(slot);
                    if (skillsInSlot == null || skillsInSlot.Count == 0)
                    {
                        ok = false;
                        Debug.LogError($"[P06_06] Mind Method '{mm.MindMethodId}' missing skills for slot {slot}!");
                    }
                }
            }

            Debug.Log($"[P06_06] Every Mind Method has exactly 5 Skill Slots | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(go);
            MindMethodManager.ResetInstance();
            EventBus.ClearAllListeners();
            return ok;
        }

        private static bool P06_07_SkillsBelongToCorrectMindMethod()
        {
            MindMethodManager.ResetInstance();
            EventBus.ClearAllListeners();

            GameObject go = new GameObject("TestMMM");
            MindMethodManager mgr = go.AddComponent<MindMethodManager>();
            mgr.LoadDatabaseIfMissing();
            mgr.InitializeFromDatabase();

            bool ok = true;
            foreach (var mm in mgr.Database.MindMethods)
            {
                if (mm == null || mm.Skills == null) continue;
                foreach (var sk in mm.Skills)
                {
                    if (sk == null || sk.MindMethodId != mm.MindMethodId)
                    {
                        ok = false;
                        Debug.LogError($"[P06_07] Skill '{sk?.SkillId}' MindMethodId mismatch! Expected '{mm.MindMethodId}', got '{sk?.MindMethodId}'");
                    }
                }
            }

            Debug.Log($"[P06_07] Skills belong to the correct Mind Method (100% exclusivity) | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(go);
            MindMethodManager.ResetInstance();
            EventBus.ClearAllListeners();
            return ok;
        }

