        private static bool P06_13_ActiveMindMethodPassiveAffectsStats()
        {
            MindMethodManager.ResetInstance();
            EventBus.ClearAllListeners();

            GameObject go = new GameObject("TestHero");
            Hero hero = go.AddComponent<Hero>();
            hero.InitializeHero();

            GameObject mmGO = new GameObject("TestMMM");
            MindMethodManager mgr = mmGO.AddComponent<MindMethodManager>();
            mgr.LoadDatabaseIfMissing();
            mgr.InitializeFromDatabase();

            hero.RecalculateStats(true);
            float maxHp = hero.Stats.GetValue(StatType.MaxHealth);
            float def = hero.Stats.GetValue(StatType.Defense);

            // Taiji adds +200 HP, +30 DEF at level 1
            bool ok = (maxHp >= 1200f) && (def >= 50f);
            Debug.Log($"[P06_13] Active Mind Method passive affects stats -> MaxHP: {maxHp} (Expected >= 1200), DEF: {def} (Expected >= 50) | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(go);
            Object.DestroyImmediate(mmGO);
            MindMethodManager.ResetInstance();
            EventBus.ClearAllListeners();
            return ok;
        }

