        private static bool P06_16_MindMethodRageModifiersAffectRageCalculation()
        {
            MindMethodManager.ResetInstance();
            EventBus.ClearAllListeners();

            GameObject heroGO = new GameObject("TestHero");
            Hero hero = heroGO.AddComponent<Hero>();
            hero.InitializeHero();

            GameObject monsterGO = new GameObject("TestMonster");
            Monster monster = monsterGO.AddComponent<Monster>();
            monster.InitializeMonster();

            GameObject mmGO = new GameObject("TestMMM");
            MindMethodManager mgr = mmGO.AddComponent<MindMethodManager>();
            mgr.LoadDatabaseIfMissing();
            mgr.InitializeFromDatabase();
            mgr.UnlockMindMethod("mm_nine_yang");

            // Nine Yang adds +1 to Basic Attack Rage Gain (base 1 -> total 2)
            mgr.SetActiveMindMethod("mm_nine_yang");
            hero.Rage.ResetRage(0f);
            BasicAttackProcessor.ExecuteBasicAttack(hero, monster);
            float rageAfterNY = hero.Rage.CurrentRage;

            // Taiji adds 0 to Basic Attack Rage Gain (base 1 -> total 1)
            mgr.SetActiveMindMethod("mm_taiji");
            hero.Rage.ResetRage(0f);
            BasicAttackProcessor.ExecuteBasicAttack(hero, monster);
            float rageAfterTJ = hero.Rage.CurrentRage;

            bool ok = (rageAfterNY == 2f) && (rageAfterTJ == 1f);
            Debug.Log($"[P06_16] Mind Method Rage modifiers affect Rage calculation -> NY Basic Attack Rage: {rageAfterNY} (Exp 2), TJ: {rageAfterTJ} (Exp 1) | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(heroGO);
            Object.DestroyImmediate(monsterGO);
            Object.DestroyImmediate(mmGO);
            MindMethodManager.ResetInstance();
            EventBus.ClearAllListeners();
            return ok;
        }

        private static bool P06_17_MindMethodLevelUsedAsBreakthroughCondition()
        {
            MindMethodManager.ResetInstance();
            TitleBreakthroughManager.ResetInstance();
            ProgressionManager.ResetInstance();
            EventBus.ClearAllListeners();

            GameObject mgrGO = new GameObject("TestManagers");
            MindMethodManager mmMgr = mgrGO.AddComponent<MindMethodManager>();
            mmMgr.LoadDatabaseIfMissing();
            mmMgr.InitializeFromDatabase();
            mmMgr.SetMindMethodLevel("mm_taiji", 3);

            ProgressionManager prog = mgrGO.AddComponent<ProgressionManager>();
            prog.InitializeProgression(5, 0f, 0);

            ResourceManager res = mgrGO.AddComponent<ResourceManager>();
            res.SetMockResources(50000, 500);

            LootTierProgressionManager lt = mgrGO.AddComponent<LootTierProgressionManager>();
            lt.SetMockTier(2);

            TitleBreakthroughManager tbk = mgrGO.AddComponent<TitleBreakthroughManager>();
            tbk.LoadDatabaseIfMissing();

            // Create title stage config requiring MindMethodLevel 5
            var customReqs = new List<BreakthroughRequirement>
            {
                new BreakthroughRequirement(BreakthroughRequirementType.HeroLevel, 5),
                new BreakthroughRequirement(BreakthroughRequirementType.MindMethodLevel, 5)
            };

            TitleBreakthroughConfigSO customCfg = ScriptableObject.CreateInstance<TitleBreakthroughConfigSO>();
            customCfg.InitializeBreakthrough("tb_test", "Test Stage", 0, 5, 10, 5, 0, 0, 1000f, 100f, 20f, customReqs: customReqs);

            TitleBreakthroughConfigSO customNextCfg = ScriptableObject.CreateInstance<TitleBreakthroughConfigSO>();
            customNextCfg.InitializeBreakthrough("tb_test_next", "Next Stage", 1, 10, 15, 10, 0, 0, 2000f, 200f, 40f);

            TitleBreakthroughDatabaseSO customDb = ScriptableObject.CreateInstance<TitleBreakthroughDatabaseSO>();
            customDb.SetBreakthroughs(new List<TitleBreakthroughConfigSO> { customCfg, customNextCfg });
            tbk.SetMockDatabase(customDb);

            // MindMethodLevel is 3 -> should fail
            var evalFail = tbk.EvaluateBreakthrough();
            bool failOk = !evalFail.CanBreakthrough;

            // Level up MindMethod to 5 -> should pass
            mmMgr.SetMindMethodLevel("mm_taiji", 5);
            var evalPass = tbk.EvaluateBreakthrough();
            bool passOk = evalPass.CanBreakthrough;

            bool ok = failOk && passOk;
            Debug.Log($"[P06_17] Mind Method Level can be used as a Breakthrough condition -> At Lv.3: {failOk} (Blocked), At Lv.5: {passOk} (Pass) | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(mgrGO);
            MindMethodManager.ResetInstance();
            TitleBreakthroughManager.ResetInstance();
            ProgressionManager.ResetInstance();
            EventBus.ClearAllListeners();
            return ok;
        }

