        private static bool P06_PM_T01_MultipleMindMethods()
        {
            MindMethodManager.ResetInstance();
            EventBus.ClearAllListeners();

            EditorSceneManager.OpenScene("Assets/_Game/Scenes/Prototype01.unity", OpenSceneMode.Single);
            MindMethodManager mmMgr = Object.FindAnyObjectByType<MindMethodManager>();
            mmMgr.LoadDatabaseIfMissing();
            mmMgr.ResetPersistence();
            mmMgr.InitializeFromDatabase();

            bool taijiInit = mmMgr.IsMindMethodUnlocked("mm_taiji");
            bool nyInit = mmMgr.IsMindMethodUnlocked("mm_nine_yang");
            bool nyinInit = mmMgr.IsMindMethodUnlocked("mm_nine_yin");

            mmMgr.UnlockMindMethod("mm_nine_yang");

            bool taijiOwned = mmMgr.IsMindMethodUnlocked("mm_taiji");
            bool nyOwned = mmMgr.IsMindMethodUnlocked("mm_nine_yang");
            bool nyinOwned = mmMgr.IsMindMethodUnlocked("mm_nine_yin");

            bool bothIndependent = (taijiOwned && nyOwned && !nyinOwned);
            string activeId = mmMgr.ActiveMindMethodId;
            bool exactlyOneActive = (activeId == "mm_taiji");

            bool pass = taijiOwned && nyOwned && bothIndependent && exactlyOneActive;
            Debug.Log($"[T01 MULTIPLE MIND METHODS] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Hero owns mm_taiji={taijiOwned}, mm_nine_yang={nyOwned}; mm_nine_yin={nyinOwned} (independent ownership states verified); Active Mind Method='{activeId}' (exactly one active).\n" +
                      $"Expected behavior: Hero can own at least 2 Mind Methods; both ownership states are independent; exactly one Mind Method is Active.");
            return pass;
        }

        private static bool P06_PM_T02_MindMethodLevel()
        {
            MindMethodManager mmMgr = Object.FindAnyObjectByType<MindMethodManager>();
            mmMgr.LoadDatabaseIfMissing();
            mmMgr.InitializeFromDatabase();
            mmMgr.UnlockMindMethod("mm_nine_yang");

            mmMgr.SetMindMethodLevel("mm_taiji", 5);
            mmMgr.SetMindMethodLevel("mm_nine_yang", 2);

            int aLvlBefore = mmMgr.GetMindMethodLevel("mm_taiji");
            int bLvlBefore = mmMgr.GetMindMethodLevel("mm_nine_yang");

            mmMgr.SetActiveMindMethod("mm_nine_yang");
            int activeUnderB = mmMgr.GetActiveMindMethodLevel();

            mmMgr.SetActiveMindMethod("mm_taiji");
            int activeUnderA = mmMgr.GetActiveMindMethodLevel();

            int aLvlAfter = mmMgr.GetMindMethodLevel("mm_taiji");
            int bLvlAfter = mmMgr.GetMindMethodLevel("mm_nine_yang");

            bool pass = (aLvlBefore == 5) && (bLvlBefore == 2) && (activeUnderB == 2) && (activeUnderA == 5) && (aLvlAfter == 5) && (bLvlAfter == 2);
            Debug.Log($"[T02 MIND METHOD LEVEL] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Set mm_taiji=Lv.5, mm_nine_yang=Lv.2. Switch A->B active level={activeUnderB}. Switch B->A active level={activeUnderA}. A remains Level {aLvlAfter}, B remains Level {bLvlAfter}.\n" +
                      $"Expected behavior: Set Mind Method A = Level 5, Mind Method B = Level 2. Switch A -> B -> A. Verify A remains Level 5, B remains Level 2.");
            return pass;
        }

        private static bool P06_PM_T03_SkillSet()
        {
            MindMethodManager mmMgr = Object.FindAnyObjectByType<MindMethodManager>();
            MindMethodUI mmUI = Object.FindAnyObjectByType<MindMethodUI>();
            mmMgr.LoadDatabaseIfMissing();
            mmMgr.InitializeFromDatabase();
            mmMgr.UnlockMindMethod("mm_nine_yang");
            mmMgr.SetActiveMindMethod("mm_taiji");

            bool aOnlyA = true;
            Dictionary<SkillSlotType, string> aSkills = new Dictionary<SkillSlotType, string>();
            for (int i = 1; i <= 5; i++)
            {
                SkillSlotType slot = (SkillSlotType)i;
                var sk = mmMgr.GetSelectedSkillForSlot(slot);
                if (sk == null || sk.MindMethodId != "mm_taiji") aOnlyA = false;
                if (sk != null) aSkills[slot] = sk.SkillId;
            }

            if (mmUI != null)
            {
                mmUI.ShowPanel();
                mmUI.RefreshUI();
            }

            mmMgr.SetActiveMindMethod("mm_nine_yang");
            if (mmUI != null) mmUI.RefreshUI();

            bool bOnlyB = true;
            bool aDisappeared = true;
            for (int i = 1; i <= 5; i++)
            {
                SkillSlotType slot = (SkillSlotType)i;
                var sk = mmMgr.GetSelectedSkillForSlot(slot);
                if (sk == null || sk.MindMethodId != "mm_nine_yang") bOnlyB = false;
                if (sk != null && aSkills.ContainsValue(sk.SkillId)) aDisappeared = false;
            }

            bool cannotEquipAUnderB = !mmMgr.SelectSkillForSlot(SkillSlotType.NormalAttack, aSkills[SkillSlotType.NormalAttack]);

            mmMgr.SetActiveMindMethod("mm_taiji");
            if (mmUI != null)
            {
                mmUI.RefreshUI();
                mmUI.HidePanel();
            }

            bool aRestored = true;
            for (int i = 1; i <= 5; i++)
            {
                SkillSlotType slot = (SkillSlotType)i;
                var sk = mmMgr.GetSelectedSkillForSlot(slot);
                if (sk == null || sk.SkillId != aSkills[slot]) aRestored = false;
            }

            bool pass = aOnlyA && bOnlyB && aDisappeared && cannotEquipAUnderB && aRestored;
            Debug.Log($"[T03 SKILL SET] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Under A (Taiji): all 5 active skills belong to Taiji ({aOnlyA}). Switch to B (NineYang): A skills disappeared ({aDisappeared}), B skills appeared ({bOnlyB}), equipping A skill under B rejected={cannotEquipAUnderB}. Switch back to A: all 5 original Taiji skills restored exactly ({aRestored}).\n" +
                      $"Expected behavior: Mind Method A displays only Skills belonging to A. Switch to B: A Skills disappear, B Skills appear, no Skill from A usable under B. Switch back to A: A Skill state restored exactly.");
            return pass;
        }

        private static bool P06_PM_T04_SkillAlternatives()
        {
            MindMethodManager mmMgr = Object.FindAnyObjectByType<MindMethodManager>();
            mmMgr.LoadDatabaseIfMissing();
            mmMgr.InitializeFromDatabase();
            mmMgr.SetActiveMindMethod("mm_taiji");

            mmMgr.UnlockSkill("skill_taiji_1_a");
            mmMgr.UnlockSkill("skill_taiji_1_b");

            mmMgr.SelectSkillForSlot(SkillSlotType.NormalAttack, "skill_taiji_1_a");
            string curAfterA1 = mmMgr.GetSelectedSkillIdForSlot(SkillSlotType.NormalAttack);
            bool a1Selected = (curAfterA1 == "skill_taiji_1_a");

            mmMgr.SelectSkillForSlot(SkillSlotType.NormalAttack, "skill_taiji_1_b");
            string curAfterA2 = mmMgr.GetSelectedSkillIdForSlot(SkillSlotType.NormalAttack);
            bool a2Selected = (curAfterA2 == "skill_taiji_1_b");
            bool a1Unselected = (curAfterA2 != "skill_taiji_1_a");

            bool exactlyOneAlternative = a2Selected && a1Unselected;

            bool pass = a1Selected && a2Selected && a1Unselected && exactlyOneAlternative;
            Debug.Log($"[T04 SKILL ALTERNATIVES] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Select A1 (skill_taiji_1_a) -> selected='{curAfterA1}'. Select A2 (skill_taiji_1_b) -> selected='{curAfterA2}', A1 unselected={a1Unselected}. Active alternative count in Slot 1 = 1 (never two active alternatives).\n" +
                      $"Expected behavior: Select Skill A1 -> A1 is selected. Select A2 -> A1 becomes unselected, A2 becomes selected. Never two active alternatives in the same slot.");
            return pass;
        }

        private static bool P06_PM_T05_SkillUnlock()
        {
            MindMethodManager mmMgr = Object.FindAnyObjectByType<MindMethodManager>();
            MindMethodUI mmUI = Object.FindAnyObjectByType<MindMethodUI>();
            ProgressionManager prog = Object.FindAnyObjectByType<ProgressionManager>();

            mmMgr.LoadDatabaseIfMissing();
            mmMgr.InitializeFromDatabase();
            mmMgr.SetActiveMindMethod("mm_taiji");

            prog.InitializeProgression(1, 0f, 0);
            var skState = mmMgr.GetSkillState("skill_taiji_1_b");
            skState.IsUnlocked = false;

            bool isUnlockedInit = mmMgr.IsSkillUnlocked("skill_taiji_1_b");
            bool canSelectLocked = mmMgr.SelectSkillForSlot(SkillSlotType.NormalAttack, "skill_taiji_1_b");

            if (mmUI != null)
            {
                mmUI.ShowPanel();
                mmUI.SelectSlot(SkillSlotType.NormalAttack);
            }

            prog.InitializeProgression(3, 0f, 0);
            bool canUnlock = mmMgr.CanUnlockSkill("skill_taiji_1_b");
            mmMgr.UnlockSkill("skill_taiji_1_b");
            bool isUnlockedAfter = mmMgr.IsSkillUnlocked("skill_taiji_1_b");
            bool canSelectUnlocked = mmMgr.SelectSkillForSlot(SkillSlotType.NormalAttack, "skill_taiji_1_b");

            if (mmUI != null) mmUI.HidePanel();

            bool pass = (!isUnlockedInit) && (!canSelectLocked) && canUnlock && isUnlockedAfter && canSelectUnlocked;
            Debug.Log($"[T05 SKILL UNLOCK] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Locked skill_taiji_1_b at Hero Lv.1 is unlocked={isUnlockedInit}, selection rejected={!canSelectLocked}. After setting Hero Lv.3: canUnlock={canUnlock}, unlocked={isUnlockedAfter}, successfully selected into slot={canSelectUnlocked}.\n" +
                      $"Expected behavior: Locked Skill is visible, displays locked state, and cannot be selected/executed. Satisfying required condition unlocks the Skill and allows selection.");
            return pass;
        }

        private static bool P06_PM_T06_PassiveStat()
        {
            MindMethodManager mmMgr = Object.FindAnyObjectByType<MindMethodManager>();
            Hero hero = Object.FindAnyObjectByType<Hero>();
            if (hero == null)
            {
                GameObject heroGO = new GameObject("Hero");
                hero = heroGO.AddComponent<Hero>();
                hero.InitializeHero();
            }

            mmMgr.LoadDatabaseIfMissing();
            mmMgr.InitializeFromDatabase();
            mmMgr.UnlockMindMethod("mm_nine_yang");
            mmMgr.SetMindMethodLevel("mm_taiji", 1);
            mmMgr.SetMindMethodLevel("mm_nine_yang", 1);

            mmMgr.SetActiveMindMethod("mm_taiji");
            hero.RecalculateStats(true);
            float aAtkInitial = hero.Stats.GetValue(StatType.Attack);
            float aDefInitial = hero.Stats.GetValue(StatType.Defense);
            float aHpInitial = hero.Stats.GetValue(StatType.MaxHealth);

            mmMgr.SetActiveMindMethod("mm_nine_yang");
            hero.RecalculateStats(true);
            float bAtk1 = hero.Stats.GetValue(StatType.Attack);
            float bDef1 = hero.Stats.GetValue(StatType.Defense);
            float bHp1 = hero.Stats.GetValue(StatType.MaxHealth);
            bool bReflected = (bAtk1 == aAtkInitial + 40f) && (bDef1 == aDefInitial - 15f) && (bHp1 == aHpInitial - 100f);

            mmMgr.SetActiveMindMethod("mm_taiji");
            hero.RecalculateStats(true);
            mmMgr.SetActiveMindMethod("mm_nine_yang");
            hero.RecalculateStats(true);
            mmMgr.SetActiveMindMethod("mm_taiji");
            hero.RecalculateStats(true);

            float aAtkFinal = hero.Stats.GetValue(StatType.Attack);
            float aDefFinal = hero.Stats.GetValue(StatType.Defense);
            float aHpFinal = hero.Stats.GetValue(StatType.MaxHealth);

            bool neverStacked = (aAtkFinal == aAtkInitial) && (aDefFinal == aDefInitial) && (aHpFinal == aHpInitial);

            bool pass = bReflected && neverStacked;
            Debug.Log($"[T06 PASSIVE STAT] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Stats under Taiji: ATK={aAtkInitial}, DEF={aDefInitial}, HP={aHpInitial}. Under Nine Yang: ATK={bAtk1}, DEF={bDef1}, HP={bHp1} (reflected immediately={bReflected}). After A->B->A->B->A: ATK={aAtkFinal}, DEF={aDefFinal}, HP={aHpFinal} (equal to initial={neverStacked}, never stacked).\n" +
                      $"Expected behavior: Record stats under A. Switch to B: passive changes immediately reflected. Switch A->B->A->B->A: passive bonuses NEVER stack. Final stats returning to A equal original A values.");
            return pass;
        }

        private static bool P06_PM_T07_Rage()
        {
            MindMethodManager mmMgr = Object.FindAnyObjectByType<MindMethodManager>();
            Hero hero = Object.FindAnyObjectByType<Hero>();
            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            bm.LoadConfigsIfMissing();

            Monster monster = bm.CurrentMonster;
            if (monster == null) monster = bm.SpawnMonster();
            monster.InitializeMonster();
            monster.Health.InitializeHealth(500f, monster);
            hero.Stats.SetStat(StatType.Dodge, 0f);
            monster.Stats.SetStat(StatType.Dodge, 0f);

            CombatConfigSO combatCfg = ScriptableObject.CreateInstance<CombatConfigSO>();

            mmMgr.LoadDatabaseIfMissing();
            mmMgr.InitializeFromDatabase();
            mmMgr.UnlockMindMethod("mm_nine_yang");

            mmMgr.SetActiveMindMethod("mm_taiji");
            hero.Stats.SetStat(StatType.Dodge, 0f);
            monster.Stats.SetStat(StatType.Dodge, 0f);
            hero.Rage.ResetRage();
            BasicAttackProcessor.ExecuteBasicAttack(hero, monster, combatCfg);
            float aAtkRage = hero.Rage.CurrentRage;

            hero.Rage.ResetRage();
            BasicAttackProcessor.ExecuteBasicAttack(monster, hero, combatCfg);
            float aDmgRage = hero.Rage.CurrentRage;

            mmMgr.SetActiveMindMethod("mm_nine_yang");
            hero.Stats.SetStat(StatType.Dodge, 0f);
            monster.Stats.SetStat(StatType.Dodge, 0f);
            hero.Rage.ResetRage();
            BasicAttackProcessor.ExecuteBasicAttack(hero, monster, combatCfg);
            float bAtkRage = hero.Rage.CurrentRage;

            hero.Rage.ResetRage();
            BasicAttackProcessor.ExecuteBasicAttack(monster, hero, combatCfg);
            float bDmgRage = hero.Rage.CurrentRage;

            mmMgr.SetActiveMindMethod("mm_taiji");
            hero.Stats.SetStat(StatType.Dodge, 0f);
            monster.Stats.SetStat(StatType.Dodge, 0f);
            hero.Rage.ResetRage();
            BasicAttackProcessor.ExecuteBasicAttack(hero, monster, combatCfg);
            float aAtkRageRestored = hero.Rage.CurrentRage;

            hero.Rage.ResetRage();
            BasicAttackProcessor.ExecuteBasicAttack(monster, hero, combatCfg);
            float aDmgRageRestored = hero.Rage.CurrentRage;

            bool pass = (aAtkRage == 1f) && (aDmgRage == 2f) &&
                        (bAtkRage == 2f) && (bDmgRage == 1f) &&
                        (aAtkRageRestored == 1f) && (aDmgRageRestored == 2f);

            Debug.Log($"[T07 RAGE] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Under Taiji: Attack Rage gain={aAtkRage}, Damage Rage gain={aDmgRage}. Under Nine Yang: Attack Rage gain={bAtkRage}, Damage Rage gain={bDmgRage}. Return to Taiji: Attack Rage gain={aAtkRageRestored}, Damage Rage gain={aDmgRageRestored}.\n" +
                      $"Expected behavior: Record Rage under A. Switch to B: Rage generation changes according to active Mind Method. Switch back to A: Rage behavior returns to A configuration.");
            return pass;
        }

        private static bool P06_PM_T08_ReviveOnce()
        {
            MindMethodManager mmMgr = Object.FindAnyObjectByType<MindMethodManager>();
            Hero hero = Object.FindAnyObjectByType<Hero>();

            mmMgr.LoadDatabaseIfMissing();
            mmMgr.InitializeFromDatabase();
            mmMgr.SetActiveMindMethod("mm_taiji");
            mmMgr.ResetReviveOnce();

            float maxHp = hero.Health.MaxHealth;
            hero.Health.InitializeHealth(maxHp, hero);

            hero.Health.TakeDamage(maxHp * 2f);

            bool firstHitAlive = hero.Health.IsAlive;
            float revivedHp = hero.Health.CurrentHealth;
            float expectedReviveHp = maxHp * 0.30f;
            bool hpPctCorrect = Mathf.Abs(revivedHp - expectedReviveHp) < 2f;

            hero.Health.TakeDamage(maxHp * 2f);
            bool secondHitDead = !hero.Health.IsAlive;

            bool pass = firstHitAlive && hpPctCorrect && secondHitDead;
            Debug.Log($"[T08 REVIVE ONCE] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Lethal hit 1: Hero died permanently=false, revived with {revivedHp:F0} HP ({expectedReviveHp:F0} expected 30%). Lethal hit 2: Hero died={secondHitDead}, ReviveOnce did not trigger a second time in same battle.\n" +
                      $"Expected behavior: Hero does NOT die permanently on first lethal hit and revives with configured HP%. Triggering lethal damage again does NOT trigger ReviveOnce a second time.");
            return pass;
        }

        private static bool P06_PM_T09_NonPausingUI()
        {
            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            Hero hero = Object.FindAnyObjectByType<Hero>();
            MindMethodUI mmUI = Object.FindAnyObjectByType<MindMethodUI>();

            hero.Health.Revive(hero.Health.MaxHealth);
            hero.EnableEntityActions();

            if (bm.CurrentMonster == null) bm.SpawnMonster();
            Monster monster = bm.CurrentMonster;
            monster.Health.Revive(500f);
            monster.EnableEntityActions();

            bm.RegisterHero(hero);
            bm.RegisterMonster(monster);
            bm.StartBattle();

            float initialHeroHp = hero.Health.CurrentHealth;
            float initialMonsterHp = monster.Health.CurrentHealth;

            mmUI.ShowPanel();
            bool uiOpen = mmUI.Panel != null && mmUI.Panel.activeSelf;
            bool timeScaleNormal = (Time.timeScale == 1.0f);
            bool battleActiveDuringUI = bm.IsBattleActive;

            for (int f = 0; f < 40; f++)
            {
                if (monster == null || !monster.IsAlive) break;
                hero.Movement.ManualTick(0.05f);
                monster.Movement.ManualTick(0.05f);
                hero.Attack.ManualTick(0.05f);
                monster.Attack.ManualTick(0.05f);
            }

            float heroHpAfterUI = hero.Health.CurrentHealth;
            float monsterHpAfterUI = monster != null ? monster.Health.CurrentHealth : 0f;
            bool hpChanged = (monsterHpAfterUI < initialMonsterHp) || (heroHpAfterUI < initialHeroHp) || (monster == null || !monster.IsAlive);

            mmUI.HidePanel();
            bool uiClosed = mmUI.Panel == null || !mmUI.Panel.activeSelf;
            bool combatContinuesAfterClose = bm.IsBattleActive;

            bool pass = uiOpen && timeScaleNormal && battleActiveDuringUI && hpChanged && uiClosed && combatContinuesAfterClose;
            Debug.Log($"[T09 NON-PAUSING UI] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: MindMethod UI opened={uiOpen}, Time.timeScale={Time.timeScale}, Battle active={battleActiveDuringUI}. Combat continued during UI (Hero HP: {initialHeroHp:F0}->{heroHpAfterUI:F0}, Monster HP: {initialMonsterHp:F0}->{monsterHpAfterUI:F0}, combat loop running={hpChanged}). UI closed={uiClosed}, battle continues={combatContinuesAfterClose}.\n" +
                      $"Expected behavior: Start active combat, open Mind Method UI. Verify combat continues, Monster/Hero attack, timers run, HP changes, combat NOT paused. Close UI, combat continues normally.");
            return pass;
        }

        private static bool P06_PM_T10_SwitchDuringCombat()
        {
            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            Hero hero = Object.FindAnyObjectByType<Hero>();
            MindMethodManager mmMgr = Object.FindAnyObjectByType<MindMethodManager>();
            EquipmentManager eqMgr = Object.FindAnyObjectByType<EquipmentManager>();
            Inventory.Inventory inv = Object.FindAnyObjectByType<Inventory.Inventory>();
            ProgressionManager prog = Object.FindAnyObjectByType<ProgressionManager>();

            mmMgr.SetActiveMindMethod("mm_taiji");
            bm.StartBattle();
            Monster monster = bm.CurrentMonster;
            hero.Health.SetCurrentHealth(700f);
            if (monster != null) monster.Health.SetCurrentHealth(monster.Health.MaxHealth * 0.60f);
            hero.Rage.ResetRage(45f);

            float heroHpBefore = hero.Health.CurrentHealth;
            float monsterHpBefore = monster != null ? monster.Health.CurrentHealth : 0f;
            float rageBefore = hero.Rage.CurrentRage;
            int eqCountBefore = eqMgr.GetEquippedItemCount();
            int invCountBefore = inv.GetAllItems().Count;
            float expBefore = prog.CurrentExp;
            int lvlBefore = prog.CurrentLevel;

            mmMgr.SetActiveMindMethod("mm_nine_yang");

            float heroHpAfter = hero.Health.CurrentHealth;
            float monsterHpAfter = monster != null ? monster.Health.CurrentHealth : 0f;
            float rageAfter = hero.Rage.CurrentRage;
            int eqCountAfter = eqMgr.GetEquippedItemCount();
            int invCountAfter = inv.GetAllItems().Count;
            float expAfter = prog.CurrentExp;
            int lvlAfter = prog.CurrentLevel;

            bool noCombatReset = bm.IsBattleActive;
            bool heroHpIntact = (heroHpAfter == heroHpBefore) && (heroHpAfter < hero.Health.MaxHealth);
            bool monsterHpIntact = (monsterHpAfter == monsterHpBefore);
            bool rageIntact = (rageAfter == rageBefore);
            bool eqIntact = (eqCountAfter == eqCountBefore);
            bool invIntact = (invCountAfter == invCountBefore);
            bool expIntact = (expAfter == expBefore);
            bool lvlIntact = (lvlAfter == lvlBefore);

            bool pass = noCombatReset && heroHpIntact && monsterHpIntact && rageIntact && eqIntact && invIntact && expIntact && lvlIntact;
            Debug.Log($"[T10 SWITCH DURING COMBAT] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Combat reset={!noCombatReset}, Hero HP ({heroHpBefore:F0}->{heroHpAfter:F0}, preserved={heroHpIntact}), Monster HP ({monsterHpBefore:F0}->{monsterHpAfter:F0}, intact={monsterHpIntact}), Rage intact={rageIntact} ({rageAfter}), Equip count={eqCountAfter} (intact={eqIntact}), Inv count={invCountAfter} (intact={invIntact}), EXP intact={expIntact}, Level intact={lvlIntact}.\n" +
                      $"Expected behavior: Switching Mind Method during active combat causes no combat reset, Hero HP not unexpectedly reset, Monster HP not reset, Rage not reset, Equipment, Inventory, EXP, and Level unchanged.");
            return pass;
        }

        private static bool P06_PM_T11_TitleBreakthrough()
        {
            TitleBreakthroughManager tbkMgr = Object.FindAnyObjectByType<TitleBreakthroughManager>();
            TitleBreakthroughUI tbkUI = Object.FindAnyObjectByType<TitleBreakthroughUI>();
            ProgressionManager prog = Object.FindAnyObjectByType<ProgressionManager>();
            ResourceManager res = Object.FindAnyObjectByType<ResourceManager>();
            LootTierProgressionManager lt = Object.FindAnyObjectByType<LootTierProgressionManager>();
            MindMethodManager mmMgr = Object.FindAnyObjectByType<MindMethodManager>();

            tbkMgr.LoadDatabaseIfMissing();
            tbkMgr.ResetPersistence();

            prog.InitializeProgression(1, 0f, 0);
            res.SetMockResources(0, 0);
            int initialCount = tbkMgr.CurrentBreakthroughCount;
            string initialTitle = tbkMgr.CurrentTitleName;

            tbkUI.ShowPanel();
            bool uiOpened = tbkUI.Panel != null && tbkUI.Panel.activeSelf;
            bool canBkUnmet = tbkMgr.EvaluateBreakthrough().CanBreakthrough;
            int countUnmet = tbkMgr.CurrentBreakthroughCount;

            prog.InitializeProgression(5, 500f, 0);
            res.SetMockResources(50000, 500);
            lt.SetMockTier(2);
            mmMgr.SetMindMethodLevel("mm_taiji", 8);
            tbkUI.RefreshUI();

            bool canBkMet = tbkMgr.EvaluateBreakthrough().CanBreakthrough;
            int countBeforePress = tbkMgr.CurrentBreakthroughCount;
            bool noAutoBreakthrough = (countBeforePress == initialCount);

            tbkUI.OnBreakthroughButtonClicked();

            int countAfterPress = tbkMgr.CurrentBreakthroughCount;
            string titleAfterPress = tbkMgr.CurrentTitleName;
            bool executedOnce = (countAfterPress == initialCount + 1);
            bool titleChanged = (titleAfterPress != initialTitle);

            tbkUI.HidePanel();

            bool pass = uiOpened && (!canBkUnmet) && (countUnmet == initialCount) && canBkMet && noAutoBreakthrough && executedOnce && titleChanged;
            Debug.Log($"[T11 TITLE BREAKTHROUGH] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Unmet conditions: UI opened={uiOpened}, CanBreakthrough={canBkUnmet}, Count={countUnmet}. Conditions satisfied: CanBreakthrough={canBkMet}, Auto-breakthrough occurred={!noAutoBreakthrough}. Button pressed: Count ({countBeforePress}->{countAfterPress}, executed once={executedOnce}), Title ({initialTitle}->{titleAfterPress}, changed={titleChanged}).\n" +
                      $"Expected behavior: Open UI with unmet conditions: UI opens, conditions visible, Breakthrough does NOT execute, count does NOT increase. Satisfy conditions: UI shows satisfied, does NOT auto-breakthrough. Press button: executes exactly once, Title changes, count +1.");
            return pass;
        }

        private static bool P06_PM_T12_D21LevelCap()
        {
            ProgressionManager prog = Object.FindAnyObjectByType<ProgressionManager>();
            TitleBreakthroughManager tbkMgr = Object.FindAnyObjectByType<TitleBreakthroughManager>();
            ResourceManager res = Object.FindAnyObjectByType<ResourceManager>();
            LootTierProgressionManager lt = Object.FindAnyObjectByType<LootTierProgressionManager>();
            MindMethodManager mmMgr = Object.FindAnyObjectByType<MindMethodManager>();

            tbkMgr.LoadDatabaseIfMissing();
            tbkMgr.ResetPersistence();

            prog.InitializeProgression(5, 0f, 0);
            int capBefore = tbkMgr.CurrentLevelCap;

            prog.AddExp(20000f);
            int lvlCapped = prog.CurrentLevel;
            float expStored = prog.CurrentExp;
            bool cannotExceedCap = (lvlCapped == 5);
            bool expNotLost = (expStored >= 20000f);

            res.SetMockResources(50000, 500);
            lt.SetMockTier(2);
            mmMgr.SetMindMethodLevel("mm_taiji", 8);
            bool playerInitiated = tbkMgr.TryPerformBreakthrough();
            int capAfter = tbkMgr.CurrentLevelCap;

            prog.ProcessStoredExp();
            int lvlAfter = prog.CurrentLevel;
            bool progressionContinued = (lvlAfter > 5);

            bool pass = (capBefore == 5) && cannotExceedCap && expNotLost && playerInitiated && (capAfter > 5) && progressionContinued;
            Debug.Log($"[T12 D21 LEVEL CAP] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: At Cap {capBefore}, adding 20,000 EXP resulted in Level={lvlCapped} (capped={cannotExceedCap}), stored EXP={expStored:F0} (not lost={expNotLost}). Player initiated breakthrough (new Cap={capAfter}). After breakthrough, stored EXP progressed Level to {lvlAfter} (continued={progressionContinued}).\n" +
                      $"Expected behavior: Hero cannot exceed current Level Cap; EXP continues accumulating while capped without loss; Breakthrough is player initiated; after Breakthrough, stored EXP continues Level progression.");
            return pass;
        }

        private static bool P06_PM_T13_D23Regression()
        {
            DropSystem dropSys = Object.FindAnyObjectByType<DropSystem>();
            LootTierProgressionManager lt = Object.FindAnyObjectByType<LootTierProgressionManager>();
            LootDecisionUI lootUI = Object.FindAnyObjectByType<LootDecisionUI>();
            EquipmentManager eqMgr = Object.FindAnyObjectByType<EquipmentManager>();
            Inventory.Inventory inv = Object.FindAnyObjectByType<Inventory.Inventory>();
            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            Hero hero = Object.FindAnyObjectByType<Hero>();

            if (lootUI != null)
            {
                lootUI.enabled = false;
                lootUI.enabled = true;
            }

            hero.Health.Revive(hero.Health.MaxHealth);
            hero.EnableEntityActions();
            dropSys.NormalMonsterDropRate = 100f;
            dropSys.LoadDatabasesIfMissing();
            lt.LoadDatabaseIfMissing();

            bm.StartBattle();
            if (bm.CurrentMonster == null) bm.SpawnMonster();
            bm.CurrentMonster.Health.InitializeHealth(500f, bm.CurrentMonster);
            bm.CurrentMonster.Health.TakeDamage(2000f);

            if (bm.PendingLootItem != null && (lootUI.Panel == null || !lootUI.Panel.activeSelf))
            {
                lootUI.HandleLootDecisionRequested(bm.PendingLootItem);
            }

            bool dropWorks = (bm.PendingLootItem != null) && (bm.CurrentBattleState == BattleState.LootPending);
            EquipmentInstance dropped = bm.PendingLootItem;

            int tier = lt.CurrentTierId;
            bool tierCorrect = (tier >= 1);

            bool compWorks = lootUI.Panel != null && lootUI.Panel.activeSelf && !string.IsNullOrEmpty(lootUI.PowerChangeText.text);

            lootUI.OnEquipClicked();
            EquipmentInstance equipped = eqMgr.GetEquippedItem(dropped.SlotType);
            bool equipWorks = (equipped != null && equipped.InstanceId == dropped.InstanceId);

            if (bm.CurrentMonster == null) bm.SpawnMonster();
            bm.CurrentMonster.Health.InitializeHealth(500f, bm.CurrentMonster);
            bm.CurrentMonster.Health.TakeDamage(2000f);

            if (bm.PendingLootItem != null && (lootUI.Panel == null || !lootUI.Panel.activeSelf))
            {
                lootUI.HandleLootDecisionRequested(bm.PendingLootItem);
            }

            lootUI.OnDismantleClicked();
            bool tachWorks = (lootUI.Panel == null || !lootUI.Panel.activeSelf) && (bm.PendingLootItem == null);

            bool invCorrect = (inv.GetAllItems() != null);
            bool combatResumes = (bm.CurrentBattleState != BattleState.LootPending);

            bool pass = dropWorks && tierCorrect && compWorks && equipWorks && tachWorks && invCorrect && combatResumes;
            Debug.Log($"[T13 D23 REGRESSION] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Equipment drop={dropWorks} ({dropped?.ItemName}), LootTier={tier} (correct={tierCorrect}), Comparison={compWorks}, EQUIP={equipWorks}, TÁCH={tachWorks}, Inventory correct={invCorrect}, Combat resumes={combatResumes}.\n" +
                      $"Expected behavior: In Play Mode: Equipment drop works, LootTier remains correct, Loot comparison works, EQUIP works, TÁCH works, Inventory remains correct, Combat resumes after loot decision.");
            return pass;
        }

        private static bool P06_PM_T14_PersistenceSwitching()
        {
            MindMethodManager mmMgr = Object.FindAnyObjectByType<MindMethodManager>();
            Hero hero = Object.FindAnyObjectByType<Hero>();

            mmMgr.LoadDatabaseIfMissing();
            mmMgr.ResetPersistence();
            mmMgr.InitializeFromDatabase();
            mmMgr.UnlockMindMethod("mm_nine_yang");

            mmMgr.SetMindMethodLevel("mm_taiji", 5);
            mmMgr.SetMindMethodLevel("mm_nine_yang", 2);
            mmMgr.UnlockSkill("skill_taiji_1_b");
            mmMgr.SelectSkillForSlot(SkillSlotType.NormalAttack, "skill_taiji_1_b");

            mmMgr.SetActiveMindMethod("mm_nine_yang");
            mmMgr.SetActiveMindMethod("mm_taiji");
            mmMgr.SaveState();

            MindMethodManager.ResetInstance();
            EditorSceneManager.OpenScene("Assets/_Game/Scenes/Prototype01.unity", OpenSceneMode.Single);
            MindMethodManager newMgr = Object.FindAnyObjectByType<MindMethodManager>();
            newMgr.LoadDatabaseIfMissing();
            newMgr.LoadState();

            bool taijiOwned = newMgr.IsMindMethodUnlocked("mm_taiji");
            bool nyOwned = newMgr.IsMindMethodUnlocked("mm_nine_yang");
            int aLvl = newMgr.GetMindMethodLevel("mm_taiji");
            int bLvl = newMgr.GetMindMethodLevel("mm_nine_yang");
            string activeId = newMgr.ActiveMindMethodId;
            bool skillUnlocked = newMgr.IsSkillUnlocked("skill_taiji_1_b");
            string selectedSkill = newMgr.GetSelectedSkillIdForSlot(SkillSlotType.NormalAttack);

            var passives = newMgr.GetActivePassiveStats();
            if (hero == null) hero = Object.FindAnyObjectByType<Hero>();
            hero.RecalculateStats(true);

            bool noDuplicatePassives = (passives.ContainsKey(StatType.Defense) && passives[StatType.Defense] == 150f);

            bool pass = taijiOwned && nyOwned && (aLvl == 5) && (bLvl == 2) && (activeId == "mm_taiji") && skillUnlocked && (selectedSkill == "skill_taiji_1_b") && noDuplicatePassives;
            Debug.Log($"[T14 PERSISTENCE / SWITCHING] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: After A->B->A and session reload: mm_taiji owned={taijiOwned} (Lv.{aLvl}), mm_nine_yang owned={nyOwned} (Lv.{bLvl}), Active={activeId}, skill_taiji_1_b unlocked={skillUnlocked}, selected={selectedSkill}, passive DEF bonus={passives[StatType.Defense]} (no duplicate passives={noDuplicatePassives}).\n" +
                      $"Expected behavior: Mind Method ownership preserved; Mind Method levels preserved; Skill unlock state preserved; Selected Skills preserved; No duplicated passive modifiers appear.");
            return pass;
        }

