        private static void SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr)
        {
            MindMethodManager.ResetInstance();
            BattleManager.ResetInstance();
            EquipmentManager.ResetInstance();
            Inventory.Inventory.ResetInstance();
            ResourceManager.ResetInstance();
            ProgressionManager.ResetInstance();
            EventBus.ClearAllListeners();

            Prototype01SceneBuilder.BuildPrototype02Data();

            GameObject servicesGO = new GameObject("TestServices");
            servicesGO.AddComponent<EquipmentManager>();
            servicesGO.AddComponent<Inventory.Inventory>();
            servicesGO.AddComponent<ResourceManager>();
            servicesGO.AddComponent<ProgressionManager>();

            mmMgrGO = new GameObject("TestMindMethodManager");
            mmMgr = mmMgrGO.AddComponent<MindMethodManager>();
            mmMgr.LoadDatabaseIfMissing();
            mmMgr.ResetPersistence();
            mmMgr.InitializeFromDatabase();

            heroGO = new GameObject("TestHero");
            hero = heroGO.AddComponent<Hero>();
            hero.InitializeHero();
            heroGO.transform.position = new Vector3(-4f, -1.2f, 0f);

            bmGO = new GameObject("TestBM");
            bm = bmGO.AddComponent<BattleManager>();
            bm.RegisterHero(hero);
            bm.StartBattle();
        }

        private static void TeardownSkillTestEncounter(GameObject heroGO, GameObject bmGO, GameObject mmMgrGO)
        {
            if (heroGO != null) Object.DestroyImmediate(heroGO);
            if (bmGO != null)
            {
                var bm = bmGO.GetComponent<BattleManager>();
                if (bm != null && bm.CurrentMonster != null) Object.DestroyImmediate(bm.CurrentMonster.gameObject);
                Object.DestroyImmediate(bmGO);
            }
            if (mmMgrGO != null) Object.DestroyImmediate(mmMgrGO);

            GameObject servicesGO = GameObject.Find("TestServices");
            if (servicesGO != null) Object.DestroyImmediate(servicesGO);

            MindMethodManager.ResetInstance();
            BattleManager.ResetInstance();
            EventBus.ClearAllListeners();
        }

        private static bool P07_1_01_SelectedSkillResolvedFromActiveMindMethod()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);

            mmMgr.SetActiveMindMethod("mm_taiji");
            SkillDefinitionSO skill = mmMgr.GetSelectedSkillForSlot(SkillSlotType.NormalAttack);

            bool ok = skill != null && skill.SkillId == "skill_taiji_1_a" && skill.MindMethodId == "mm_taiji";
            Debug.Log($"[P07_1_01] Selected skill resolved from active Mind Method -> Skill: {skill?.SkillName} ({skill?.SkillId}), MindMethod: {skill?.MindMethodId} | {(ok ? "PASS" : "FAIL")}");

            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

        private static bool P07_1_02_SelectedSkillExecutesSuccessfully()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);

            mmMgr.SetActiveMindMethod("mm_taiji");
            Monster monster = bm.CurrentMonster;
            monster.Health.InitializeHealth(500f, monster);

            SkillExecutionResult result = hero.ExecuteSelectedSkill(SkillSlotType.NormalAttack, monster);

            bool ok = result.Success &&
                      result.FailureReason == SkillExecutionFailureReason.None &&
                      result.SkillId == "skill_taiji_1_a" &&
                      result.DamageResult.HasValue &&
