        private static bool P07_1_11_SkillExecutionUsesAuthoritativeDamagePipeline()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);

            mmMgr.SetActiveMindMethod("mm_taiji");
            Monster monster = bm.CurrentMonster;
            monster.Health.InitializeHealth(500f, monster);
            float hpBefore = monster.Health.CurrentHealth;

            bool eventFired = false;
            DamageResult receivedResult = default;
            System.Action<Entity, DamageResult> onDamaged = (entity, res) =>
            {
                if (entity == monster)
                {
                    eventFired = true;
                    receivedResult = res;
                }
            };
            EventBus.OnEntityDamaged += onDamaged;

            SkillExecutionResult execResult = hero.ExecuteSelectedSkill(SkillSlotType.NormalAttack, monster);
            EventBus.OnEntityDamaged -= onDamaged;

            float hpAfter = monster.Health.CurrentHealth;
            float damageDealt = hpBefore - hpAfter;

            bool ok = execResult.Success &&
                      damageDealt > 0f &&
                      eventFired &&
                      receivedResult.DamageType == DamageType.Skill &&
                      execResult.DamageResult.HasValue &&
                      execResult.DamageResult.Value.FinalDamage == receivedResult.FinalDamage;

            Debug.Log($"[P07_1_11] Authoritative damage pipeline used -> Success: {execResult.Success}, DamageDealt: {damageDealt:F1}, EventFired: {eventFired}, DmgType: {receivedResult.DamageType} | {(ok ? "PASS" : "FAIL")}");

            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

