        private static bool P07_1_16_BattleRestartDoesNotResetUnrelatedHeroProgression()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);

            var prog = Object.FindAnyObjectByType<ProgressionManager>();
            var inv = Object.FindAnyObjectByType<Inventory.Inventory>();
            var eqMgr = Object.FindAnyObjectByType<EquipmentManager>();

            prog.InitializeProgression(5, 1234f, 0);
            var testItem = new EquipmentInstance("sword_test", "Kiếm Thử Nghiệm", EquipmentSlotType.Weapon, 1, null, null, 5, 1);
            eqMgr.Equip(testItem);

            mmMgr.SetActiveMindMethod("mm_taiji");
            hero.ExecuteSelectedSkill(SkillSlotType.NormalAttack, bm.CurrentMonster);

            bm.StartBattle();

            bool ok = prog.CurrentLevel == 5 &&
                      prog.CurrentExp == 1234f &&
                      eqMgr.GetEquippedItem(EquipmentSlotType.Weapon) != null &&
                      eqMgr.GetEquippedItem(EquipmentSlotType.Weapon).InstanceId == testItem.InstanceId;

            Debug.Log($"[P07_1_16] Battle restart does not reset unrelated Hero progression -> Level: {prog.CurrentLevel}, EXP: {prog.CurrentExp}, WeaponEquipped: {eqMgr.GetEquippedItem(EquipmentSlotType.Weapon) != null} | {(ok ? "PASS" : "FAIL")}");

            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

        [MenuItem("Tools/Wuxia RPG/Run Prototype 07.1 Play Mode Acceptance Tests")]
        public static bool RunPrototype07_1PlayModeAcceptanceTests()
        {
            Debug.Log("==================================================");
            Debug.Log("   STARTING PROTOTYPE 07.1 REAL PLAY MODE ACCEPTANCE SUITE (T01 - T22)");
            Debug.Log("==================================================");

            Prototype01SceneBuilder.BuildPrototype02Data();
            Prototype01SceneBuilder.BuildPrototype01Scene();
            EditorSceneManager.OpenScene("Assets/_Game/Scenes/Prototype01.unity", OpenSceneMode.Single);

            int passed = 0;
            int total = 22;

            if (P07_1_PM_T01_SceneLoaded()) passed++;
            if (P07_1_PM_T02_HeroMonsterSpawned()) passed++;
            if (P07_1_PM_T03_ActiveMindMethodAvailable()) passed++;
            if (P07_1_PM_T04_SelectValidUnlockedSkill()) passed++;
            if (P07_1_PM_T05_TriggerSkillExecution()) passed++;
            if (P07_1_PM_T06_SkillExecutionReachesRuntime()) passed++;
            if (P07_1_PM_T07_TargetReceivesCombatEffect()) passed++;
            if (P07_1_PM_T08_HeroRageUnchanged()) passed++;
            if (P07_1_PM_T09_NoCooldownApplied()) passed++;
