            hero.ExecuteSelectedSkill(SkillSlotType.Skill, monster); // 100 -> 70
            float rageAfterFirst = hero.Rage.CurrentRage;

            hero.ExecuteSelectedSkill(SkillSlotType.Skill, monster); // Blocked by cooldown
            float rageAfterSecond = hero.Rage.CurrentRage;

            bool ok = Mathf.Approximately(rageAfterFirst, 70f) && Mathf.Approximately(rageAfterSecond, 70f);
            Debug.Log($"[P07_2_08] Cooldown failure does not consume Rage -> After1: {rageAfterFirst}, After2: {rageAfterSecond} | {(ok ? "PASS" : "FAIL")}");

            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
