        private static bool P07_2_09_CooldownFailureDoesNotRestartCooldown()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);
            var testTime = new TestTimeProvider(100f);
            CooldownManager.TimeProvider = testTime;

            mmMgr.SetActiveMindMethod("mm_taiji");
            mmMgr.UnlockSkill("skill_taiji_2_a");
            mmMgr.SelectSkillForSlot(SkillSlotType.Skill, "skill_taiji_2_a");

            hero.Rage.ResetRage(100f);
            Monster monster = bm.CurrentMonster;
            monster.Health.InitializeHealth(500f, monster);

            hero.ExecuteSelectedSkill(SkillSlotType.Skill, monster); // Cooldown ends at 103f
            testTime.Advance(1.0f); // Current time = 101f, remaining = 2.0s

            float remBefore = CooldownManager.GetRemainingCooldown("skill_taiji_2_a");
            hero.ExecuteSelectedSkill(SkillSlotType.Skill, monster); // Blocked
            float remAfter = CooldownManager.GetRemainingCooldown("skill_taiji_2_a");

            bool ok = Mathf.Approximately(remBefore, 2.0f) && Mathf.Approximately(remAfter, 2.0f);
            Debug.Log($"[P07_2_09] Cooldown failure does not restart cooldown -> RemBefore: {remBefore:F2}s, RemAfter: {remAfter:F2}s | {(ok ? "PASS" : "FAIL")}");

            CooldownManager.ResetForTesting();
            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

