            mmMgr.UnlockSkill("skill_taiji_2_a");
            mmMgr.SelectSkillForSlot(SkillSlotType.Skill, "skill_taiji_2_a");

            hero.Rage.ResetRage(100f);
            Monster monster = bm.CurrentMonster;
            monster.Health.InitializeHealth(500f, monster);

            var res1 = hero.ExecuteSelectedSkill(SkillSlotType.Skill, monster); // 100 -> 70, CD 3s
            testTime.Advance(3.1f); // Now at 53.1f, CD expired

            var res2 = hero.ExecuteSelectedSkill(SkillSlotType.Skill, monster); // 70 -> 40, succeeds!
            bool ok = res1.Success && res2.Success && Mathf.Approximately(hero.Rage.CurrentRage, 40f);
            Debug.Log($"[P07_2_10] Skill becomes executable after cooldown expires -> Exec1: {res1.Success}, Exec2: {res2.Success}, FinalRage: {hero.Rage.CurrentRage} | {(ok ? "PASS" : "FAIL")}");

            CooldownManager.ResetForTesting();
            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

