        private static bool P07_2_20_SkillExecutionStillUsesAuthoritativeDamagePipeline()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);
            CooldownManager.ResetForTesting();

            mmMgr.SetActiveMindMethod("mm_taiji");
            mmMgr.UnlockSkill("skill_taiji_2_a");
            mmMgr.SelectSkillForSlot(SkillSlotType.Skill, "skill_taiji_2_a");

            hero.Rage.ResetRage(50f);
            Monster monster = bm.CurrentMonster;
            monster.Health.InitializeHealth(500f, monster);

            bool damageEventFired = false;
            EventBus.OnEntityDamaged += (target, dmg) =>
            {
                if (target == monster) damageEventFired = true;
            };

            SkillExecutionResult res = hero.ExecuteSelectedSkill(SkillSlotType.Skill, monster);
            bool ok = res.Success && damageEventFired && res.DamageResult.HasValue && res.DamageResult.Value.FinalDamage > 0f;
            Debug.Log($"[P07_2_20] Skill execution still uses authoritative damage pipeline -> Success: {res.Success}, DmgEvent: {damageEventFired}, Dmg: {res.DamageResult?.FinalDamage:F1} | {(ok ? "PASS" : "FAIL")}");

            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

