        }

        private static bool P07_2_22_SkillRuntimeStateRemainsSeparateFromConfiguration()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);
            CooldownManager.ResetForTesting();

            mmMgr.SetActiveMindMethod("mm_taiji");
            mmMgr.UnlockSkill("skill_taiji_2_a");
            mmMgr.SelectSkillForSlot(SkillSlotType.Skill, "skill_taiji_2_a");

            hero.Rage.ResetRage(50f);
            Monster monster = bm.CurrentMonster;
            monster.Health.InitializeHealth(500f, monster);

            hero.ExecuteSelectedSkill(SkillSlotType.Skill, monster);

            var runtimeState = mmMgr.GetSkillState("skill_taiji_2_a");
            var configSO = mmMgr.FindSkillDefinition("skill_taiji_2_a");

            bool ok = runtimeState != null &&
                      runtimeState.CooldownDuration == 3.0f &&
                      runtimeState.CooldownEndTime > 0f &&
                      configSO != null &&
                      configSO.Cooldown == 3.0f;

            Debug.Log($"[P07_2_22] Skill runtime state remains separate from configuration -> RuntimeCD: {runtimeState?.CooldownDuration}, ConfigCD: {configSO?.Cooldown} | {(ok ? "PASS" : "FAIL")}");

            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

