        private static float p07_2_recordedRageBefore = 0f;
        private static SkillExecutionResult p07_2_lastExecResult = null;
        private static float p07_2_monsterHpBefore = 0f;

        private static bool P07_2_PM_T01_EnterPlayMode()
        {
            bool pass = UnityEngine.SceneManagement.SceneManager.GetActiveScene().name == "Prototype01";
            Debug.Log($"[T01 ENTER PLAY MODE] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Scene '{UnityEngine.SceneManagement.SceneManager.GetActiveScene().name}' loaded successfully (active={pass}).\n" +
                      $"Expected behavior: Enter Play Mode and load active prototype scene.");
            return pass;
        }

        private static bool P07_2_PM_T02_HeroAndMonsterSpawn()
        {
            Hero hero = Object.FindAnyObjectByType<Hero>();
            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            Monster monster = bm != null ? bm.CurrentMonster : Object.FindAnyObjectByType<Monster>();
            if (hero != null) { hero.Health.Revive(hero.Health.MaxHealth); hero.EnableEntityActions(); }
            if (monster != null) { monster.Health.Revive(500f); monster.EnableEntityActions(); }
            bool pass = hero != null && monster != null && hero.IsAlive && monster.IsAlive;
            Debug.Log($"[T02 HERO & MONSTER SPAWN] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Hero exists={hero != null} (alive={hero?.IsAlive}), Monster exists={monster != null} (alive={monster?.IsAlive}).\n" +
                      $"Expected behavior: Hero and Monster spawn normally into the scene.");
            return pass;
        }

        private static bool P07_2_PM_T03_ConfirmActiveMindMethod()
        {
            MindMethodManager mmMgr = Object.FindAnyObjectByType<MindMethodManager>();
            mmMgr.LoadDatabaseIfMissing();
            mmMgr.ResetPersistence();
            mmMgr.InitializeFromDatabase();
            mmMgr.SetActiveMindMethod("mm_taiji");
            bool pass = mmMgr != null && mmMgr.ActiveMindMethodId == "mm_taiji" && mmMgr.ActiveMindMethodDefinition != null;
            Debug.Log($"[T03 ACTIVE TÂM PHÁP] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Active Tâm Pháp='{mmMgr?.ActiveMindMethodId}' ({mmMgr?.ActiveMindMethodDefinition?.MindMethodName}).\n" +
                      $"Expected behavior: Active Tâm Pháp is visible and available.");
            return pass;
        }

        private static bool P07_2_PM_T04_SelectUnlockedSkill()
        {
            MindMethodManager mmMgr = Object.FindAnyObjectByType<MindMethodManager>();
            mmMgr.UnlockSkill("skill_taiji_2_a");
            mmMgr.SelectSkillForSlot(SkillSlotType.Skill, "skill_taiji_2_a");
            var selected = mmMgr.GetSelectedSkillForSlot(SkillSlotType.Skill);
            bool pass = selected != null && selected.SkillId == "skill_taiji_2_a" && selected.RageCost == 30f && selected.Cooldown == 3f;
            Debug.Log($"[T04 SELECT VALID SKILL] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Selected Skill='{selected?.SkillId}', Cost={selected?.RageCost}, Cooldown={selected?.Cooldown}s.\n" +
                      $"Expected behavior: Select a valid unlocked Skill from active Tâm Pháp.");
            return pass;
        }

