        private static bool P07_3_01_SingleDamageEffectExecutesSuccessfully()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);
            CooldownManager.ResetForTesting();

            mmMgr.SetActiveMindMethod("mm_taiji");
            mmMgr.UnlockSkill("skill_taiji_2_a");
            mmMgr.SelectSkillForSlot(SkillSlotType.Skill, "skill_taiji_2_a");

            hero.Rage.ResetRage(50f);
            Monster monster = bm.CurrentMonster;
            monster.Health.InitializeHealth(500f, monster);

            SkillExecutionResult res = hero.ExecuteSelectedSkill(SkillSlotType.Skill, monster);
            bool ok = res.Success && res.EffectResults != null && res.EffectResults.Count == 1 &&
                      res.EffectResults[0].Success && res.EffectResults[0].EffectType == SkillEffectType.Damage &&
                      res.DamageResult.HasValue && res.DamageResult.Value.FinalDamage > 0f;

            Debug.Log($"[P07_3_01] Single DamageEffect executes successfully -> Success: {res.Success}, Effects: {res.EffectResults?.Count}, Dmg: {res.DamageResult?.FinalDamage:F1} | {(ok ? "PASS" : "FAIL")}");

            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

        private static bool P07_3_02_DamageEffectUsesAuthoritativePipeline()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);
            CooldownManager.ResetForTesting();

            mmMgr.SetActiveMindMethod("mm_taiji");
            mmMgr.UnlockSkill("skill_taiji_2_a");
            mmMgr.SelectSkillForSlot(SkillSlotType.Skill, "skill_taiji_2_a");

            hero.Rage.ResetRage(50f);
            Monster monster = bm.CurrentMonster;
            monster.Health.InitializeHealth(500f, monster);
            float hpBefore = monster.Health.CurrentHealth;

            bool eventFired = false;
            EventBus.OnEntityDamaged += (target, dmg) =>
            {
                if (target == monster) eventFired = true;
            };

            SkillExecutionResult res = hero.ExecuteSelectedSkill(SkillSlotType.Skill, monster);
            float hpAfter = monster.Health.CurrentHealth;

            bool ok = res.Success && eventFired && hpAfter < hpBefore &&
                      Mathf.Approximately(hpBefore - hpAfter, res.DamageResult.Value.FinalDamage);

            Debug.Log($"[P07_3_02] DamageEffect uses authoritative pipeline -> EventFired: {eventFired}, HPDelta: {hpBefore - hpAfter:F1}, ResDmg: {res.DamageResult?.FinalDamage:F1} | {(ok ? "PASS" : "FAIL")}");

            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

