        private static bool P07_3_22_BattleRestartPreservesProgression()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);
            CooldownManager.ResetForTesting();

            ProgressionManager prog = ProgressionManager.Instance;
            int lvlBefore = prog.CurrentLevel;

            bm.StartBattle();
            bm.EndEncounterAndStartNext();
            bm.StartBattle();

            bool ok = prog.CurrentLevel == lvlBefore && mmMgr.ActiveMindMethodId == "mm_taiji";
            Debug.Log($"[P07_3_22] Battle restart preserves progression -> Level: {prog.CurrentLevel}, MM: {mmMgr.ActiveMindMethodId} | {(ok ? "PASS" : "FAIL")}");

            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

        private static bool P07_3_23_ExistingBasicAttackDamageUnchanged()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);
            CooldownManager.ResetForTesting();

            Monster monster = bm.CurrentMonster;
            monster.Health.InitializeHealth(500f, monster);
            float hpBefore = monster.Health.CurrentHealth;
            for (int i = 0; i < 3 && monster.Health.CurrentHealth >= hpBefore; i++)
            {
                BasicAttackProcessor.ExecuteBasicAttack(hero, monster, null);
            }
            float hpAfter = monster.Health.CurrentHealth;

            bool ok = hpAfter < hpBefore;
            Debug.Log($"[P07_3_23] Existing basic attack damage unchanged -> HPDelta: {hpBefore - hpAfter:F1} | {(ok ? "PASS" : "FAIL")}");

            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

