        #region Prototype 07.3 Play Mode Acceptance Tests (T01 - T25)

        [MenuItem("Tools/Wuxia RPG/Run Prototype 07.3 Play Mode Acceptance Tests (T01 to T25)")]
        public static bool RunPrototype07_3PlayModeAcceptanceTests()
        {
            Debug.Log("==================================================");
            Debug.Log("   STARTING PROTOTYPE 07.3 REAL PLAY MODE ACCEPTANCE (T01 - T25)");
            Debug.Log("==================================================");

            Prototype01SceneBuilder.BuildPrototype02Data();
            Prototype01SceneBuilder.BuildPrototype01Scene();
            EditorSceneManager.OpenScene("Assets/_Game/Scenes/Prototype01.unity", OpenSceneMode.Single);

            int passed = 0;
            int total = 25;

            if (P07_3_PM_T01_GameStartsNormally()) passed++;
            if (P07_3_PM_T02_SelectUnlockedSkill()) passed++;
            if (P07_3_PM_T03_SkillExecutesAgainstValidMonster()) passed++;
            if (P07_3_PM_T04_MonsterHPVisiblyDecreases()) passed++;
            if (P07_3_PM_T05_DamageResultMatchesPipeline()) passed++;
            if (P07_3_PM_T06_RageDecreasesExactlyOnce()) passed++;
            if (P07_3_PM_T07_CooldownStartsExactlyOnce()) passed++;
            if (P07_3_PM_T08_CooldownPreventsImmediateSecondExecution()) passed++;
            if (P07_3_PM_T09_CooldownExpiresCorrectly()) passed++;
            if (P07_3_PM_T10_SkillWithTwoDamageEffectsExecutesBoth()) passed++;
            if (P07_3_PM_T11_RageConsumedOnceForWholeSkill()) passed++;
            if (P07_3_PM_T12_CooldownStartsOnceForWholeSkill()) passed++;
            if (P07_3_PM_T13_DeadMonsterCannotReceiveDamage()) passed++;
            if (P07_3_PM_T14_DeadHeroCannotExecuteSkill()) passed++;
            if (P07_3_PM_T15_InvalidTargetHandledSafely()) passed++;
            if (P07_3_PM_T16_ZeroEffectSkillDoesNotCrash()) passed++;
            if (P07_3_PM_T17_SwitchingSkillStillWorks()) passed++;
            if (P07_3_PM_T18_SwitchingMindMethodStillWorks()) passed++;
            if (P07_3_PM_T19_MindMethodSkillOwnershipCorrect()) passed++;
            if (P07_3_PM_T20_BattleRestartStillWorks()) passed++;
            if (P07_3_PM_T21_HeroProgressionRemainsUnchanged()) passed++;
            if (P07_3_PM_T22_EquipmentInventoryCurrencyUnchanged()) passed++;
            if (P07_3_PM_T23_BasicAttackBehaviorUnchanged()) passed++;
            if (P07_3_PM_T24_MonsterAttackBehaviorUnchanged()) passed++;
            if (P07_3_PM_T25_NoVisibleRegression()) passed++;

            Debug.Log("==================================================");
            Debug.Log($"   PROTOTYPE 07.3 PLAY MODE ACCEPTANCE: {passed}/25 {(passed == total ? "PASSED" : "FAILED")}");
            Debug.Log("==================================================");
            return passed == total;
        }

        private static float p07_3_recordedRageBefore = 0f;
        private static SkillExecutionResult p07_3_lastExecResult = null;
        private static float p07_3_monsterHpBefore = 0f;

        private static bool P07_3_PM_T01_GameStartsNormally()
        {
            bool pass = UnityEngine.SceneManagement.SceneManager.GetActiveScene().name == "Prototype01";
            Hero hero = Object.FindAnyObjectByType<Hero>();
            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            if (hero != null) { hero.Health.Revive(hero.Health.MaxHealth); hero.EnableEntityActions(); }
            if (bm != null && bm.CurrentMonster != null) { bm.CurrentMonster.Health.Revive(500f); bm.CurrentMonster.EnableEntityActions(); }
            pass = pass && hero != null && bm != null && bm.CurrentMonster != null;
            Debug.Log($"[T01 GAME STARTS NORMALLY] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Scene loaded, Hero and Monster present (active={pass}).\n" +
                      $"Expected behavior: Game starts normally.");
            return pass;
        }

        private static bool P07_3_PM_T02_SelectUnlockedSkill()
        {
            MindMethodManager mmMgr = Object.FindAnyObjectByType<MindMethodManager>();
            mmMgr.LoadDatabaseIfMissing();
            mmMgr.ResetPersistence();
            mmMgr.InitializeFromDatabase();
            mmMgr.SetActiveMindMethod("mm_taiji");
            mmMgr.UnlockSkill("skill_taiji_2_a");
            bool selected = mmMgr.SelectSkillForSlot(SkillSlotType.Skill, "skill_taiji_2_a");
            var sk = mmMgr.GetSelectedSkillForSlot(SkillSlotType.Skill);
            bool pass = selected && sk != null && sk.SkillId == "skill_taiji_2_a";
            Debug.Log($"[T02 SELECT UNLOCKED SKILL] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Selected Skill='{sk?.SkillId}', Cost={sk?.RageCost}, CD={sk?.Cooldown}s.\n" +
                      $"Expected behavior: Hero can select an unlocked Skill.");
            return pass;
        }

        private static bool P07_3_PM_T03_SkillExecutesAgainstValidMonster()
        {
            Hero hero = Object.FindAnyObjectByType<Hero>();
            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            hero.Rage.ResetRage(50f);
            CooldownManager.ResetAllCooldowns();
            p07_3_recordedRageBefore = hero.Rage.CurrentRage;
            p07_3_monsterHpBefore = bm.CurrentMonster.Health.CurrentHealth;

            p07_3_lastExecResult = hero.ExecuteSelectedSkill(SkillSlotType.Skill, bm.CurrentMonster);
            bool pass = p07_3_lastExecResult != null && p07_3_lastExecResult.Success;
            Debug.Log($"[T03 SKILL EXECUTES AGAINST MONSTER] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Skill execution Success={pass}, SkillId={p07_3_lastExecResult?.SkillId}.\n" +
                      $"Expected behavior: Skill executes against valid Monster.");
            return pass;
        }

        private static bool P07_3_PM_T04_MonsterHPVisiblyDecreases()
        {
            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            float curHp = bm.CurrentMonster.Health.CurrentHealth;
            bool pass = curHp < p07_3_monsterHpBefore;
            Debug.Log($"[T04 MONSTER HP DECREASES] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Monster HP before={p07_3_monsterHpBefore:F1}, after={curHp:F1} (decreased={pass}).\n" +
                      $"Expected behavior: Monster HP visibly decreases.");
            return pass;
        }

        private static bool P07_3_PM_T05_DamageResultMatchesPipeline()
        {
            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            float delta = p07_3_monsterHpBefore - bm.CurrentMonster.Health.CurrentHealth;
            bool pass = p07_3_lastExecResult != null && p07_3_lastExecResult.DamageResult.HasValue &&
                        Mathf.Approximately(delta, p07_3_lastExecResult.DamageResult.Value.FinalDamage);
            Debug.Log($"[T05 DAMAGE MATCHES PIPELINE] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: HP delta={delta:F1}, DamageResult={p07_3_lastExecResult?.DamageResult?.FinalDamage:F1}.\n" +
                      $"Expected behavior: Damage result matches configured damage pipeline.");
            return pass;
        }

        private static bool P07_3_PM_T06_RageDecreasesExactlyOnce()
        {
            Hero hero = Object.FindAnyObjectByType<Hero>();
            bool pass = Mathf.Approximately(hero.Rage.CurrentRage, 20f); // 50 - 30 = 20
            Debug.Log($"[T06 RAGE DECREASES ONCE] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Rage before={p07_3_recordedRageBefore:F0}, after={hero.Rage.CurrentRage:F0} (cost=30).\n" +
                      $"Expected behavior: Rage decreases exactly once.");
            return pass;
        }

