        private static bool P07_3_PM_T10_SkillWithTwoDamageEffectsExecutesBoth()
        {
            Hero hero = Object.FindAnyObjectByType<Hero>();
            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            MindMethodManager mmMgr = Object.FindAnyObjectByType<MindMethodManager>();

            var skillDef = mmMgr.FindSkillDefinition("skill_taiji_2_a");
            var eff1 = ScriptableObject.CreateInstance<DamageEffectDefinitionSO>();
            eff1.Initialize(0.8f, SkillTargetPolicy.SingleTarget, DamageType.Skill);
            var eff2 = ScriptableObject.CreateInstance<DamageEffectDefinitionSO>();
            eff2.Initialize(1.2f, SkillTargetPolicy.SingleTarget, DamageType.Skill);
            skillDef.SetEffects(new List<SkillEffectDefinitionSO> { eff1, eff2 });

            hero.Rage.ResetRage(50f);
            CooldownManager.ResetAllCooldowns();

            var res = hero.ExecuteSelectedSkill(SkillSlotType.Skill, bm.CurrentMonster);
            bool pass = res.Success && res.EffectResults != null && res.EffectResults.Count == 2 &&
                        res.EffectResults[0].Success && res.EffectResults[1].Success;

            Debug.Log($"[T10 TWO EFFECTS EXECUTE BOTH] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Executed 2 effects Success={pass}, Count={res.EffectResults?.Count}.\n" +
                      $"Expected behavior: Skill with two DamageEffects executes both effects.");

            eff1.Initialize(1.5f);
            skillDef.SetEffects(new List<SkillEffectDefinitionSO> { eff1 });
            Object.DestroyImmediate(eff2);
            return pass;
        }

