            bool pass = !res.Success && res.FailureReason == SkillExecutionFailureReason.TargetInvalidOrDead;

            Debug.Log($"[T13 DEAD MONSTER BLOCKED] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Damage rejected={pass} (Reason={res.FailureReason}).\n" +
                      $"Expected behavior: Dead Monster cannot receive Skill damage.");

            Object.DestroyImmediate(deadGO);
            return pass;
        }

        private static bool P07_3_PM_T14_DeadHeroCannotExecuteSkill()
        {
            Hero hero = Object.FindAnyObjectByType<Hero>();
            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            hero.Health.TakeDamage(99999f);
            if (hero.IsAlive) hero.Health.TakeDamage(99999f);

            var res = hero.ExecuteSelectedSkill(SkillSlotType.NormalAttack, bm.CurrentMonster);
            bool pass = !res.Success && res.FailureReason == SkillExecutionFailureReason.SourceInvalidOrDead;

            Debug.Log($"[T14 DEAD HERO BLOCKED] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Execution rejected={pass} (Reason={res.FailureReason}).\n" +
                      $"Expected behavior: Dead Hero cannot execute Skill.");

            // Revive hero for next tests
            hero.Health.Revive(hero.Health.MaxHealth);
            hero.EnableEntityActions();
            return pass;
        }

        private static bool P07_3_PM_T15_InvalidTargetHandledSafely()
        {
