                hero.SetCurrentTarget(null);
                var res = hero.ExecuteSelectedSkill(SkillSlotType.NormalAttack, null);
                if (res == null) noException = false;
            }
            catch (System.Exception ex)
            {
                noException = false;
                Debug.LogError($"[T15] Exception: {ex}");
            }

            Debug.Log($"[T15 INVALID TARGET HANDLED SAFELY] {(noException ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Dynamic fallback resolved target safely={noException}.\n" +
                      $"Expected behavior: Invalid target is handled safely.");
            return noException;
        }

