            Debug.Log($"[T16 ZERO EFFECT DOES NOT CRASH] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Zero-effect skill executed Success={res.Success}, Effects={res.EffectResults?.Count}.\n" +
                      $"Expected behavior: Zero-effect Skill does not crash.");

