        private static bool P07_4_01_HealEffectExecutesSuccessfully()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);
            CooldownManager.ResetForTesting();

            hero.Health.InitializeHealth(200f, hero);
            hero.Health.TakeDamage(100f);
            float hpBefore = hero.Health.CurrentHealth;

            var healEff = ScriptableObject.CreateInstance<HealEffectDefinitionSO>();
            healEff.Initialize(50f, HealAmountMode.FlatValue, SkillTargetPolicy.Self);

            var req = new SkillExecutionRequest(hero, null, SkillSlotType.Skill, hero);
            var res = healEff.Execute(req, hero, null);

            bool ok = res.Success && res.EffectType == SkillEffectType.Heal &&
                      res.RequestedAmount == 50f && res.ActualAmount == 50f &&
                      hero.Health.CurrentHealth == hpBefore + 50f;

            Debug.Log($"[P07_4_01] HealEffect executes successfully -> Success: {res.Success}, ActualHeal: {res.ActualAmount}, FinalHP: {hero.Health.CurrentHealth} | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(healEff);
            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

        private static bool P07_4_02_HealEffectUsesHealthComponentAsSoleAuthority()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);
            CooldownManager.ResetForTesting();

            hero.Health.InitializeHealth(200f, hero);
            hero.Health.TakeDamage(80f);

            bool eventFired = false;
            hero.Health.OnHealthChanged += (cur, max) => { eventFired = true; };

            var healEff = ScriptableObject.CreateInstance<HealEffectDefinitionSO>();
            healEff.Initialize(40f, HealAmountMode.FlatValue, SkillTargetPolicy.Self);
            var res = healEff.Execute(new SkillExecutionRequest(hero, null, SkillSlotType.Skill, hero), hero, null);

            bool ok = res.Success && eventFired && hero.Health.CurrentHealth == 160f;
            Debug.Log($"[P07_4_02] HealEffect uses HealthComponent as sole authority -> EventFired: {eventFired}, HP: {hero.Health.CurrentHealth} | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(healEff);
            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

