            var resNull = healEff.Execute(new SkillExecutionRequest(hero, null, SkillSlotType.Skill, null), null, null);

            GameObject deadGO = new GameObject("DeadTarget");
            Monster deadM = deadGO.AddComponent<Monster>();
            deadM.InitializeMonster();
            deadM.Health.TakeDamage(99999f);

            var resDead = healEff.Execute(new SkillExecutionRequest(hero, null, SkillSlotType.Skill, deadM), deadM, null);

            bool ok = !resNull.Success && !resDead.Success;
            Debug.Log($"[P07_4_06] Invalid Heal target handled safely -> NullSuccess: {resNull.Success}, DeadSuccess: {resDead.Success} | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(deadGO);
            Object.DestroyImmediate(healEff);
            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

