        private static bool P07_4_11_BuffExpirationRemovesContributionFromFinalStats()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);
            CooldownManager.ResetForTesting();

            var testTime = new TestTimeProvider(100f);
            CooldownManager.TimeProvider = testTime;

            float initialAtk = hero.Stats.GetValue(StatType.Attack);

            var buffEff = ScriptableObject.CreateInstance<BuffEffectDefinitionSO>();
            buffEff.Initialize("buff_expire_test", "Expiring Buff", StatType.Attack, 40f, 5f);
            buffEff.Execute(new SkillExecutionRequest(hero, null, SkillSlotType.Skill, hero), hero, null);

            float buffedAtk = hero.Stats.GetValue(StatType.Attack);

            // Advance time past 5s duration
            testTime.Advance(6f);
            hero.StatusController.Tick(testTime.CurrentTime);
            float unbuffedAtk = hero.Stats.GetValue(StatType.Attack);

            bool ok = buffedAtk == initialAtk + 40f && unbuffedAtk == initialAtk && !hero.StatusController.HasBuff("buff_expire_test");
            Debug.Log($"[P07_4_11] Buff expiration removes contribution -> Initial: {initialAtk}, Buffed: {buffedAtk}, Unbuffed: {unbuffedAtk} | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(buffEff);
            CooldownManager.TimeProvider = new UnityTimeProvider();
            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

