        private static bool P07_4_16_BuffStackPolicyDoesNotCreateUncontrolledDuplication()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);
            CooldownManager.ResetForTesting();

            var testTime = new TestTimeProvider(100f);
            CooldownManager.TimeProvider = testTime;

            var buffEff = ScriptableObject.CreateInstance<BuffEffectDefinitionSO>();
            buffEff.Initialize("buff_stack_test", "Stack Buff", StatType.Attack, 10f, 10f, BuffStackingPolicy.Stack, SkillTargetPolicy.Self, maxStackCount: 3);

            buffEff.Execute(new SkillExecutionRequest(hero, null, SkillSlotType.Skill, hero), hero, null); // 1
            buffEff.Execute(new SkillExecutionRequest(hero, null, SkillSlotType.Skill, hero), hero, null); // 2
            buffEff.Execute(new SkillExecutionRequest(hero, null, SkillSlotType.Skill, hero), hero, null); // 3
            buffEff.Execute(new SkillExecutionRequest(hero, null, SkillSlotType.Skill, hero), hero, null); // 4 (capped at 3)

