        private static bool P07_4_23_MultiEffectSkillExecutesDamageAndHeal()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);
            CooldownManager.ResetForTesting();

            mmMgr.SetActiveMindMethod("mm_taiji");
            var skillDef = mmMgr.FindSkillDefinition("skill_taiji_2_a");

            var dmgEff = ScriptableObject.CreateInstance<DamageEffectDefinitionSO>();
            dmgEff.Initialize(1.2f, SkillTargetPolicy.SingleTarget);
            var healEff = ScriptableObject.CreateInstance<HealEffectDefinitionSO>();
            healEff.Initialize(40f, HealAmountMode.FlatValue, SkillTargetPolicy.Self);
            skillDef.SetEffects(new List<SkillEffectDefinitionSO> { dmgEff, healEff });

            hero.Health.InitializeHealth(200f, hero);
            hero.Health.TakeDamage(80f); // HP is 120
            hero.Rage.ResetRage(50f);

            Monster monster = bm.CurrentMonster;
            monster.Health.InitializeHealth(500f, monster);
            float monsterHpBefore = monster.Health.CurrentHealth;

            var res = hero.ExecuteSelectedSkill(SkillSlotType.Skill, monster);

            bool ok = res.Success && res.EffectResults != null && res.EffectResults.Count == 2 &&
                      res.EffectResults[0].EffectType == SkillEffectType.Damage && res.EffectResults[0].Success &&
                      res.EffectResults[1].EffectType == SkillEffectType.Heal && res.EffectResults[1].Success &&
                      monster.Health.CurrentHealth < monsterHpBefore && hero.Health.CurrentHealth == 160f;

            Debug.Log($"[P07_4_23] Multi-effect executes Damage + Heal -> Success: {res.Success}, Effects: {res.EffectResults?.Count}, HeroHP: {hero.Health.CurrentHealth} | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(dmgEff);
            Object.DestroyImmediate(healEff);
            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

