        private static bool P07_4_44_NoSkillIdSpecificHardCodedLogicExists()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);
            CooldownManager.ResetForTesting();

            var customSkill = ScriptableObject.CreateInstance<SkillDefinitionSO>();
            var customBuff = ScriptableObject.CreateInstance<BuffEffectDefinitionSO>();
            customBuff.Initialize("buff_arbitrary_id_123", "Arbitrary Buff", StatType.Defense, 35f, 10f);
            customSkill.InitializeSkill("skill_arbitrary_xyz_999", "mm_taiji", SkillSlotType.Skill, "Arbitrary Skill", "", null, 0f, 0f, 0f, false, new List<SkillEffectDefinitionSO> { customBuff });

            float defBefore = hero.Stats.GetValue(StatType.Defense);
            var effList = EffectResolver.ResolveEffectsForSkill(customSkill);
            var req = new SkillExecutionRequest(hero, customSkill, SkillSlotType.Skill, hero);
            var res = EffectResolver.Instance.ProcessEffects(req, effList);
            float defAfter = hero.Stats.GetValue(StatType.Defense);

            bool ok = res != null && res.Count == 1 && res[0].Success && defAfter == defBefore + 35f;
            Debug.Log($"[P07_4_44] No Skill-ID-specific hard-coded logic -> Custom skill executed purely from config: {ok} | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(customBuff);
            Object.DestroyImmediate(customSkill);
            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

