        private static bool P07_4_PM_T01_GameStartsNormally()
        {
            bool pass = UnityEngine.SceneManagement.SceneManager.GetActiveScene().name == "Prototype01";
            Hero hero = Object.FindAnyObjectByType<Hero>();
            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            if (hero != null) { hero.Health.Revive(hero.Health.MaxHealth); hero.EnableEntityActions(); }
            if (bm != null && bm.CurrentMonster != null) { bm.CurrentMonster.Health.Revive(500f); bm.CurrentMonster.EnableEntityActions(); }
            pass = pass && hero != null && bm != null && bm.CurrentMonster != null;
            Debug.Log($"[T01 GAME STARTS NORMALLY] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Scene loaded, Hero and Monster present (active={pass}).\n" +
                      $"Expected behavior: Game starts normally.");
            return pass;
        }

        private static bool P07_4_PM_T02_SelectSkillWithDamageEffect()
        {
            MindMethodManager mmMgr = Object.FindAnyObjectByType<MindMethodManager>();
            mmMgr.LoadDatabaseIfMissing();
            mmMgr.ResetPersistence();
            mmMgr.InitializeFromDatabase();
            mmMgr.SetActiveMindMethod("mm_taiji");
            mmMgr.UnlockSkill("skill_taiji_2_a");
            bool selected = mmMgr.SelectSkillForSlot(SkillSlotType.Skill, "skill_taiji_2_a");
            var sk = mmMgr.GetSelectedSkillForSlot(SkillSlotType.Skill);
            bool pass = selected && sk != null && sk.SkillId == "skill_taiji_2_a";
            Debug.Log($"[T02 SELECT DAMAGE SKILL] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Selected Skill='{sk?.SkillId}', Effects={sk?.Effects?.Count}.\n" +
                      $"Expected behavior: Hero can select a Skill with DamageEffect.");
            return pass;
        }

        private static bool P07_4_PM_T03_DamageWorks()
        {
            Hero hero = Object.FindAnyObjectByType<Hero>();
            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            hero.Rage.ResetRage(50f);
            CooldownManager.ResetAllCooldowns();
            float hpBefore = bm.CurrentMonster.Health.CurrentHealth;

            var res = hero.ExecuteSelectedSkill(SkillSlotType.Skill, bm.CurrentMonster);
            float hpAfter = bm.CurrentMonster.Health.CurrentHealth;

            bool pass = res.Success && hpAfter < hpBefore;
            Debug.Log($"[T03 DAMAGE WORKS] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Damage dealt={hpBefore - hpAfter:F1}, HP: {hpBefore:F0}->{hpAfter:F0}.\n" +
                      $"Expected behavior: Damage works.");
            return pass;
        }

        private static bool P07_4_PM_T04_SelectSkillWithHealEffect()
        {
            MindMethodManager mmMgr = Object.FindAnyObjectByType<MindMethodManager>();
            var sk = mmMgr.FindSkillDefinition("skill_taiji_3_a");

            var healEff = ScriptableObject.CreateInstance<HealEffectDefinitionSO>();
            healEff.Initialize(40f, HealAmountMode.FlatValue, SkillTargetPolicy.Self);
            sk.SetEffects(new List<SkillEffectDefinitionSO> { healEff });

            mmMgr.UnlockSkill("skill_taiji_3_a");
            bool selected = mmMgr.SelectSkillForSlot(SkillSlotType.ExternalSkill1, "skill_taiji_3_a");
            bool pass = selected && sk.Effects.Count == 1 && sk.Effects[0].EffectType == SkillEffectType.Heal;

            Debug.Log($"[T04 SELECT HEAL SKILL] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Selected Heal Skill='{sk.SkillId}', Effect={sk.Effects[0].EffectType}.\n" +
                      $"Expected behavior: Select a Skill with HealEffect.");
            return pass;
        }

