        private static bool P07_4_PM_T07_HealDoesNotExceedMaxHP()
        {
            Hero hero = Object.FindAnyObjectByType<Hero>();
            hero.Rage.ResetRage(50f);
            CooldownManager.ResetAllCooldowns();

            // Re-execute heal when HP is 160/200 (should heal only 40, capping at 200)
            hero.ExecuteSelectedSkill(SkillSlotType.ExternalSkill1, hero); // heals 40 -> 200
            CooldownManager.ResetAllCooldowns();
            hero.Rage.ResetRage(50f);
            var res = hero.ExecuteSelectedSkill(SkillSlotType.ExternalSkill1, hero); // already full 200

            bool pass = hero.Health.CurrentHealth == hero.Health.MaxHealth && res.EffectResults[0].ActualAmount == 0f;
            Debug.Log($"[T07 HEAL NOT EXCEED MAX HP] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Current HP={hero.Health.CurrentHealth}/{hero.Health.MaxHealth}, ExcessHealRejected=True.\n" +
                      $"Expected behavior: Heal does not exceed Max HP.");
            return pass;
        }

