        private static bool P07_5_01_StatusDefinitionProperties()
        {
            var def = ScriptableObject.CreateInstance<StatusEffectDefinitionSO>();
            def.Initialize("status_bleed_test", "Chảy Máu", 6f, 1.5f, 4, StatusStackPolicy.Stack, StatusCategory.Dot, 18f, DamageType.Skill);

            bool ok = def.StatusId == "status_bleed_test" &&
                      def.StatusName == "Chảy Máu" &&
                      Mathf.Approximately(def.DefaultDuration, 6f) &&
                      Mathf.Approximately(def.TickInterval, 1.5f) &&
                      def.MaxStacks == 4 &&
                      def.StackPolicy == StatusStackPolicy.Stack &&
                      def.Category == StatusCategory.Dot &&
                      Mathf.Approximately(def.DamagePerTick, 18f) &&
                      def.DamageType == DamageType.Skill;

            Debug.Log($"[P07_5_01] Status definition properties valid -> {ok} | {(ok ? "PASS" : "FAIL")}");
            Object.DestroyImmediate(def);
            return ok;
        }

