        {
            var def = ScriptableObject.CreateInstance<StatusEffectDefinitionSO>();
            def.Initialize("status_immut_test", "Immut", 5f, 1f, 3, StatusStackPolicy.Stack, StatusCategory.Dot, 10f);

            var inst = new RuntimeStatusInstance(def, null, null, 100f);
            inst.AddStack(100f);
            inst.RefreshDuration(100f);

            bool ok = Mathf.Approximately(def.DefaultDuration, 5f) && def.MaxStacks == 3 && Mathf.Approximately(def.DamagePerTick, 10f);
            Debug.Log($"[P07_5_02] Status definition remains immutable -> {ok} | {(ok ? "PASS" : "FAIL")}");
            Object.DestroyImmediate(def);
            return ok;
        }

