        private static bool P07_5_05_RuntimeStatusInitialState()
        {
            var def = ScriptableObject.CreateInstance<StatusEffectDefinitionSO>();
            def.Initialize("status_init", "Init", 5f, 1f, 3, StatusStackPolicy.Stack, StatusCategory.Dot, 12f);

            var inst = new RuntimeStatusInstance(def, null, null, 100f);
            bool ok = inst.StatusId == "status_init" &&
                      Mathf.Approximately(inst.StartTime, 100f) &&
                      Mathf.Approximately(inst.ExpirationTime, 105f) &&
