        private static bool P07_5_06_RuntimeStatusDurationAndRemaining()
        {
            var def = ScriptableObject.CreateInstance<StatusEffectDefinitionSO>();
            def.Initialize("status_dur", "Duration Test", 10f, 1f, 1);

            var testTime = new TestTimeProvider(100f);
            CooldownManager.TimeProvider = testTime;

            var inst = new RuntimeStatusInstance(def, null, null, testTime.CurrentTime);
            testTime.Advance(4f);
            float rem = inst.RemainingDuration;
            bool activeMid = inst.IsActive && !inst.IsExpired;

            testTime.Advance(7f); // Total elapsed = 11s (past 10s)
            bool expiredAfter = inst.IsExpired && !inst.IsActive && Mathf.Approximately(inst.RemainingDuration, 0f);

            bool ok = Mathf.Approximately(rem, 6f) && activeMid && expiredAfter;
            Debug.Log($"[P07_5_06] Runtime status duration and remaining calculation -> Rem4s: {rem:F1}s, Expired: {expiredAfter} | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(def);
            CooldownManager.TimeProvider = new UnityTimeProvider();
            return ok;
        }

