        private static bool P07_5_17_DotTickFiresEventBusDamaged()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);
            Monster monster = bm.CurrentMonster;
            var statusController = monster.gameObject.AddComponent<EntityStatusController>();
            statusController.Initialize(monster);

            var def = ScriptableObject.CreateInstance<StatusEffectDefinitionSO>();
            def.Initialize("dot_event_test", "Event Bleed", 5f, 1f, 1, StatusStackPolicy.RefreshDuration, StatusCategory.Dot, 35f);

            var testTime = new TestTimeProvider(100f);
            CooldownManager.TimeProvider = testTime;

            bool eventFired = false;
            float eventDmg = 0f;
            System.Action<Entity, DamageResult> handler = (target, result) =>
            {
                if (target == monster)
                {
                    eventFired = true;
                    eventDmg = result.FinalDamage;
                }
            };

            EventBus.OnEntityDamaged += handler;
            statusController.ApplyStatus(def, hero);
            testTime.Advance(1.1f);
            statusController.Tick(testTime.CurrentTime);
            EventBus.OnEntityDamaged -= handler;

            bool ok = eventFired && Mathf.Approximately(eventDmg, 35f);
            Debug.Log($"[P07_5_17] DoT tick fires EventBus.OnEntityDamaged -> Fired: {eventFired}, Dmg: {eventDmg} | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(def);
            CooldownManager.TimeProvider = new UnityTimeProvider();
            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

