            CooldownManager.TimeProvider = testTime;

            statusController.ApplyStatus(def, hero);
            testTime.Advance(4f); // Expired
            statusController.Tick(testTime.CurrentTime); // Cleans up

            float hpBefore = monster.Health.CurrentHealth;
            testTime.Advance(2f);
            statusController.Tick(testTime.CurrentTime);
            float hpAfter = monster.Health.CurrentHealth;

            bool ok = Mathf.Approximately(hpBefore, hpAfter);
            Debug.Log($"[P07_5_29] No damage occurs after status expiration -> HPDelta: {hpBefore - hpAfter:F1} | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(def);
            CooldownManager.TimeProvider = new UnityTimeProvider();
            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

        private static bool P07_5_30_DeterministicFloatingPointTiming()
        {
            var def = ScriptableObject.CreateInstance<StatusEffectDefinitionSO>();
            def.Initialize("dot_float_test", "Float Test", 5f, 1f, 1);

            var testTime = new TestTimeProvider(100f);
            CooldownManager.TimeProvider = testTime;

            var inst = new RuntimeStatusInstance(def, null, null, testTime.CurrentTime);
            testTime.SetTime(104.999f);
            bool activeBefore = inst.IsActive;

            testTime.SetTime(105.001f);
            bool expiredAfter = inst.IsExpired;

            bool ok = activeBefore && expiredAfter;
            Debug.Log($"[P07_5_30] Deterministic timing boundary -> ActiveAt104.999: {activeBefore}, ExpiredAt105.001: {expiredAfter} | {(ok ? "PASS" : "FAIL")}");

            Object.DestroyImmediate(def);
            CooldownManager.TimeProvider = new UnityTimeProvider();
            return ok;
        }

