            Debug.Log($"   PROTOTYPE 07.5 PLAY MODE ACCEPTANCE: {passed}/30 {(passed == total ? "PASSED" : "FAILED")}");
            Debug.Log("==================================================");
            return passed == total;
        }

        private static bool P07_5_PM_T01_GameStartsNormally()
        {
