            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            Hero hero = Object.FindAnyObjectByType<Hero>();

            hero.Health.Revive(hero.Health.MaxHealth);
            hero.EnableEntityActions();
            bm.StartBattle();
            bool pass = bm.IsBattleActive && hero.IsAlive && bm.CurrentMonster != null && bm.CurrentMonster.IsAlive;

            Debug.Log($"[T27 BATTLE RESTART] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Battle active={bm.IsBattleActive}, HeroAlive={hero.IsAlive}, MonsterAlive={bm.CurrentMonster?.IsAlive}.\n" +
                      $"Expected behavior: Battle restart works.");
            return pass;
        }

        private static bool P07_5_PM_T28_HeroProgressionPreserved()
        {
            ProgressionManager prog = ProgressionManager.Instance;
            Hero hero = Object.FindAnyObjectByType<Hero>();

            bool pass = prog != null && hero != null && prog.CurrentLevel >= 1;
            Debug.Log($"[T28 HERO PROGRESSION PRESERVED] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Level={prog?.CurrentLevel}, EXP={prog?.CurrentExp:F0}.\n" +
                      $"Expected behavior: Hero progression preserved.");
            return pass;
        }

