            Debug.Log($"[T29 EQUIPMENT/INVENTORY PRESERVED] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: EquipmentManager active={eq != null}, Inventory active={inv != null}.\n" +
                      $"Expected behavior: Equipment and inventory preserved.");
