        }

        private static bool P07_5_PM_T30_RegressionAgainstP07_1ToP07_4()
        {
            EffectResolver resolver = EffectResolver.Instance as EffectResolver;
            Hero hero = Object.FindAnyObjectByType<Hero>();
            bool pass = resolver != null && hero != null && hero.Health != null && hero.Rage != null;

            Debug.Log($"[T30 REGRESSION AGAINST P07.1-P07.4] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Full combat, effect, status, rage, and health pipelines active.\n" +
                      $"Expected behavior: No regression against P07.1 through P07.4.");
            return pass;
        }

