        private static bool P07_6_01_DebuffAtkFlat()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);
            Monster monster = bm.CurrentMonster;
            float baseAtk = monster.Stats.GetValue(StatType.Attack, 10f);

            monster.StatusController.ApplyDebuff("test_atk_flat", DebuffType.Attack, DebuffModifierMode.Flat, 3f, 5f, EffectPowerTier.TierB, hero);
            float debuffedAtk = monster.Stats.GetValue(StatType.Attack);
            bool ok = Mathf.Approximately(debuffedAtk, baseAtk - 3f);

            Debug.Log($"[P07_6_01] Attack Debuff Flat reduction -> Base: {baseAtk}, Debuffed: {debuffedAtk} | {(ok ? "PASS" : "FAIL")}");
            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

        private static bool P07_6_02_DebuffAtkPercent()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);
            Monster monster = bm.CurrentMonster;
            float baseAtk = monster.Stats.GetValue(StatType.Attack, 10f);

            monster.StatusController.ApplyDebuff("test_atk_pct", DebuffType.Attack, DebuffModifierMode.Percentage, 20f, 5f, EffectPowerTier.TierB, hero);
            float debuffedAtk = monster.Stats.GetValue(StatType.Attack);
            float expected = baseAtk * 0.8f;
            bool ok = Mathf.Abs(debuffedAtk - expected) < 0.01f;

            Debug.Log($"[P07_6_02] Attack Debuff Percent reduction -> Base: {baseAtk}, Expected: {expected:F2}, Actual: {debuffedAtk:F2} | {(ok ? "PASS" : "FAIL")}");
            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

