        private static bool P07_6_24_DebuffRemovalEvents()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);
            Monster monster = bm.CurrentMonster;

            bool appliedFired = false;
            bool expiredFired = false;

            EventBus.OnDebuffApplied += (ent, id) => { if (ent == monster && id == "deb_ev") appliedFired = true; };
            EventBus.OnDebuffExpired += (ent, id) => { if (ent == monster && id == "deb_ev") expiredFired = true; };

            monster.StatusController.ApplyDebuff("deb_ev", DebuffType.Defense, DebuffModifierMode.Flat, 2f, 1f, EffectPowerTier.TierB, hero);
            monster.StatusController.RemoveDebuff("deb_ev");

            bool ok = appliedFired && expiredFired;
            Debug.Log($"[P07_6_24] Debuff Removal Events -> Applied: {appliedFired}, Expired: {expiredFired} | {(ok ? "PASS" : "FAIL")}");
            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

