            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);
            Monster monster = bm.CurrentMonster;
            monster.StatusController.ApplyAntiCCImmunity(5f, hero);

            bool immuneFired = false;
            EventBus.OnCrowdControlImmune += (ent, ccType) => { if (ent == monster && ccType == CrowdControlType.Stun) immuneFired = true; };

            bool applied = monster.StatusController.ApplyCrowdControl("cc_stun_imm", CrowdControlType.Stun, 3f, EffectPowerTier.TierB, hero);
            bool ok = !applied && immuneFired && !monster.IsStunned;

            Debug.Log($"[P07_6_48] Anti-CC Immunity Blocks Stun -> Applied: {applied}, ImmuneFired: {immuneFired}, IsStunned: {monster.IsStunned} | {(ok ? "PASS" : "FAIL")}");
            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

