            Debug.Log($"[P07_6_52] Anti-CC Expiration Permits CC -> Applied: {applied}, IsStunned: {monster.IsStunned} | {(ok ? "PASS" : "FAIL")}");
            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

        private static bool P07_6_53_EffectPowerTierAssignments()
        {
            var debA = ScriptableObject.CreateInstance<DebuffEffectDefinitionSO>();
            debA.Initialize("deb_a", "Minor", DebuffType.Attack, 5f, DebuffModifierMode.Flat, 3f, EffectPowerTier.TierA);

            var debB = ScriptableObject.CreateInstance<DebuffEffectDefinitionSO>();
            debB.Initialize("deb_b", "Standard", DebuffType.Attack, 10f, DebuffModifierMode.Flat, 5f, EffectPowerTier.TierB);

            var debC = ScriptableObject.CreateInstance<DebuffEffectDefinitionSO>();
            debC.Initialize("deb_c", "Major", DebuffType.Attack, 20f, DebuffModifierMode.Flat, 7f, EffectPowerTier.TierC);

            bool ok = debA.PowerTier == EffectPowerTier.TierA &&
                      debB.PowerTier == EffectPowerTier.TierB &&
                      debC.PowerTier == EffectPowerTier.TierC;

            Debug.Log($"[P07_6_53] Effect Power Tier Assignments -> A: {debA.PowerTier}, B: {debB.PowerTier}, C: {debC.PowerTier} | {(ok ? "PASS" : "FAIL")}");
            Object.DestroyImmediate(debA);
            Object.DestroyImmediate(debB);
            Object.DestroyImmediate(debC);
            return ok;
        }

        private static bool P07_6_54_RegressionPreviousPrototypes()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);
            mmMgr.SetActiveMindMethod("mm_taiji");

            // Apply P07.4 Buff
            var buff = ScriptableObject.CreateInstance<BuffEffectDefinitionSO>();
            buff.Initialize("buff_test_reg", "Buff Reg", StatType.Attack, 10f, 5f, BuffStackingPolicy.RefreshDuration);
            hero.StatusController.ApplyBuff(buff, hero);
            // Apply P07.5 DoT
            var dot = ScriptableObject.CreateInstance<StatusEffectDefinitionSO>();
            dot.Initialize("dot_test_reg", "Poison", 5f, 1f, 1, StatusStackPolicy.RefreshDuration, StatusCategory.Dot, 10f);
            bm.CurrentMonster.StatusController.ApplyStatus(dot, hero);
            // Apply P07.6 CC & Debuff
            bm.CurrentMonster.StatusController.ApplyDebuff("deb_reg", DebuffType.Defense, DebuffModifierMode.Flat, 5f, 5f, EffectPowerTier.TierB, hero);
            bm.CurrentMonster.StatusController.ApplyCrowdControl("cc_reg", CrowdControlType.Root, 5f, EffectPowerTier.TierB, hero);

            bool ok = hero.StatusController.ActiveBuffs.Count == 1 &&
                      bm.CurrentMonster.StatusController.ActiveStatuses.Count == 1 &&
                      bm.CurrentMonster.StatusController.ActiveDebuffs.Count == 1 &&
                      bm.CurrentMonster.StatusController.ActiveCrowdControls.Count == 1 &&
                      bm.CurrentMonster.IsRooted;

            Debug.Log($"[P07_6_54] Regression Previous Prototypes -> Buffs: {hero.StatusController.ActiveBuffs.Count}, DoTs: {bm.CurrentMonster.StatusController.ActiveStatuses.Count}, Debuffs: {bm.CurrentMonster.StatusController.ActiveDebuffs.Count}, CC: {bm.CurrentMonster.StatusController.ActiveCrowdControls.Count} | {(ok ? "PASS" : "FAIL")}");
            Object.DestroyImmediate(buff);
            Object.DestroyImmediate(dot);
            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

        private static bool P07_6_55_DeterministicFloatingPointTiming()
        {
            var testTime = new TestTimeProvider(100f);
            CooldownManager.TimeProvider = testTime;

            var deb = new RuntimeDebuffInstance("deb_float", DebuffType.Attack, DebuffModifierMode.Flat, 5f, 2.5f, EffectPowerTier.TierB, null, null, testTime.CurrentTime);
            bool expiredEarly = deb.IsExpired;

            testTime.SetTime(102.4f);
            bool expiredMid = deb.IsExpired;

            testTime.SetTime(102.6f);
            bool expiredLate = deb.IsExpired;

            bool ok = !expiredEarly && !expiredMid && expiredLate;
            Debug.Log($"[P07_6_55] Deterministic Floating Point Timing -> Early: {expiredEarly}, Mid: {expiredMid}, Late: {expiredLate} | {(ok ? "PASS" : "FAIL")}");

            CooldownManager.TimeProvider = new UnityTimeProvider();
            return ok;
        }

