        #region Prototype 07.6 (Play Mode Acceptance Tests T01 to T35)

        [MenuItem("Tools/Wuxia RPG/Run Prototype 07.6 Play Mode Acceptance Tests (T01 to T35)")]
        public static bool RunPrototype07_6PlayModeAcceptanceTests()
        {
            Debug.Log("==================================================");
            Debug.Log("   STARTING PROTOTYPE 07.6 REAL PLAY MODE ACCEPTANCE TESTS (T01 - T35)");
            Debug.Log("==================================================");

            Prototype01SceneBuilder.BuildPrototype02Data();
            Prototype01SceneBuilder.BuildPrototype01Scene();
            EditorSceneManager.OpenScene("Assets/_Game/Scenes/Prototype01.unity", OpenSceneMode.Single);

            Hero setupHero = Object.FindAnyObjectByType<Hero>();
            BattleManager setupBm = Object.FindAnyObjectByType<BattleManager>();
            MindMethodManager setupMm = Object.FindAnyObjectByType<MindMethodManager>();

            if (setupHero != null)
            {
                setupHero.InitializeHero();
                setupHero.Health.Revive(setupHero.Health.MaxHealth);
                setupHero.EnableEntityActions();
            }

            if (setupBm != null)
            {
                if (setupBm.CurrentMonster != null)
                {
                    setupBm.CurrentMonster.InitializeMonster();
                    setupBm.CurrentMonster.Health.Revive(setupBm.CurrentMonster.Health.MaxHealth);
                    setupBm.CurrentMonster.EnableEntityActions();
                }
                if (!setupBm.IsBattleActive)
                {
                    setupBm.StartBattle();
                }
            }

            if (setupMm != null)
            {
                setupMm.LoadDatabaseIfMissing();
                setupMm.ResetPersistence();
                setupMm.InitializeFromDatabase();
                setupMm.SetActiveMindMethod("mm_taiji");
                setupMm.UnlockSkill("skill_taiji_2_a");
                setupMm.SelectSkillForSlot(SkillSlotType.Skill, "skill_taiji_2_a");
            }

            int passed = 0;
            int total = 35;

            if (P07_6_PM_T01_AtkDebuffFlatApplied()) passed++;
            if (P07_6_PM_T02_AtkDebuffPercentApplied()) passed++;
            if (P07_6_PM_T03_DefDebuffFlatApplied()) passed++;
            if (P07_6_PM_T04_DefDebuffPercentApplied()) passed++;
            if (P07_6_PM_T05_AtkSpeedDebuffApplied()) passed++;
            if (P07_6_PM_T06_MoveSpeedDebuffApplied()) passed++;
            if (P07_6_PM_T07_CritRateDebuffApplied()) passed++;
            if (P07_6_PM_T08_DodgeRateDebuffApplied()) passed++;
            if (P07_6_PM_T09_RageGainDebuffApplied()) passed++;
            if (P07_6_PM_T10_HealingReceivedDebuffApplied()) passed++;
            if (P07_6_PM_T11_DamageDealtDebuffApplied()) passed++;
            if (P07_6_PM_T12_StunActionLocks()) passed++;
            if (P07_6_PM_T13_StunInterruptsAction()) passed++;
            if (P07_6_PM_T14_StunExpiresNaturally()) passed++;
            if (P07_6_PM_T15_RootActionLocks()) passed++;
            if (P07_6_PM_T16_RootDoesNotInterruptAction()) passed++;
            if (P07_6_PM_T17_RootExpiresNaturally()) passed++;
            if (P07_6_PM_T18_FreezeActionLocks()) passed++;
            if (P07_6_PM_T19_FreezeDistinctIdentity()) passed++;
            if (P07_6_PM_T20_FreezeShatterFalseNoTrigger()) passed++;
            if (P07_6_PM_T21_FreezeShatterTrueTriggersHook()) passed++;
            if (P07_6_PM_T22_CcResistance0PercentFullDuration()) passed++;
            if (P07_6_PM_T23_CcResistance30PercentDurationReduced()) passed++;
            if (P07_6_PM_T24_CcResistance50PercentDurationReduced()) passed++;
            if (P07_6_PM_T25_CcResistance100PercentResists()) passed++;
            if (P07_6_PM_T26_CcResistanceClamping()) passed++;
            if (P07_6_PM_T27_AntiCcBlocksStun()) passed++;
            if (P07_6_PM_T28_AntiCcBlocksRoot()) passed++;
            if (P07_6_PM_T29_AntiCcBlocksFreeze()) passed++;
            if (P07_6_PM_T30_AntiCcExpirationPermitsCC()) passed++;
            if (P07_6_PM_T31_DebuffRefreshDurationPolicy()) passed++;
            if (P07_6_PM_T32_DebuffReplacePolicy()) passed++;
            if (P07_6_PM_T33_DebuffStackPolicy()) passed++;
            if (P07_6_PM_T34_EffectPowerTierClassification()) passed++;
            if (P07_6_PM_T35_EndToEndCombatAcceptance()) passed++;

            Debug.Log("==================================================");
            Debug.Log($"   PROTOTYPE 07.6 PLAY MODE ACCEPTANCE: {passed}/35 {(passed == total ? "PASSED" : "FAILED")}");
            Debug.Log("==================================================");
            return passed == total;
        }

        private static bool P07_6_PM_T01_AtkDebuffFlatApplied()
        {
            Hero hero = Object.FindAnyObjectByType<Hero>();
            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            Monster monster = bm.CurrentMonster;
            float baseAtk = monster.Stats.GetValue(StatType.Attack, 10f);

            monster.StatusController.ApplyDebuff("pm_atk_flat", DebuffType.Attack, DebuffModifierMode.Flat, 4f, 5f, EffectPowerTier.TierB, hero);
            float actualAtk = monster.Stats.GetValue(StatType.Attack);
            bool pass = Mathf.Approximately(actualAtk, baseAtk - 4f);

            Debug.Log($"[T01 ATK DEBUFF FLAT] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Base ATK={baseAtk:F1}, Debuffed ATK={actualAtk:F1} (-4 flat).\n" +
                      $"Expected behavior: Monster ATK reduced by 4 flat.");
            monster.StatusController.RemoveDebuff("pm_atk_flat");
            return pass;
        }

        private static bool P07_6_PM_T02_AtkDebuffPercentApplied()
        {
            Hero hero = Object.FindAnyObjectByType<Hero>();
            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            Monster monster = bm.CurrentMonster;
            float baseAtk = monster.Stats.GetValue(StatType.Attack, 10f);

            monster.StatusController.ApplyDebuff("pm_atk_pct", DebuffType.Attack, DebuffModifierMode.Percentage, 30f, 5f, EffectPowerTier.TierB, hero);
            float actualAtk = monster.Stats.GetValue(StatType.Attack);
            bool pass = Mathf.Abs(actualAtk - baseAtk * 0.7f) < 0.05f;

            Debug.Log($"[T02 ATK DEBUFF PERCENT] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Base ATK={baseAtk:F1}, Debuffed ATK={actualAtk:F1} (-30%).\n" +
                      $"Expected behavior: Monster ATK reduced by 30%.");
            monster.StatusController.RemoveDebuff("pm_atk_pct");
            return pass;
        }

