            hero.StatusController.ApplyCrowdControl("pm_stun", CrowdControlType.Stun, 3f, EffectPowerTier.TierB, monster);
            bool pass = !hero.CanMove && !hero.CanBasicAttack && !hero.CanUseSkill && !hero.CanUseUltimate && !hero.CanDash && hero.IsStunned;

            Debug.Log($"[T12 STUN ACTION LOCKS] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: CanMove={hero.CanMove}, CanAtk={hero.CanBasicAttack}, CanSkill={hero.CanUseSkill}, IsStunned={hero.IsStunned}.\n" +
                      $"Expected behavior: Stun locks all action permissions.");
            hero.StatusController.RemoveCrowdControl("pm_stun");
            return pass;
        }

        private static bool P07_6_PM_T13_StunInterruptsAction()
        {
            Hero hero = Object.FindAnyObjectByType<Hero>();
            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            Monster monster = bm.CurrentMonster;

            bool interrupted = false;
            EventBus.OnCrowdControlInterrupted += (ent, type) => { if (ent == hero && type == CrowdControlType.Stun) interrupted = true; };

            hero.StatusController.ApplyCrowdControl("pm_stun_int", CrowdControlType.Stun, 3f, EffectPowerTier.TierB, monster);
            bool pass = interrupted;

            Debug.Log($"[T13 STUN INTERRUPTS ACTION] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Interrupted event fired={interrupted}.\n" +
                      $"Expected behavior: Stun interrupts ongoing action.");
