            monster.StatusController.ApplyDebuff("pm_deb_ref", DebuffType.Attack, DebuffModifierMode.Flat, 5f, 4f, EffectPowerTier.TierB, hero, StatusStackPolicy.RefreshDuration);
            var d1 = monster.StatusController.GetDebuff("pm_deb_ref");
            float end1 = d1.EndTime;

            monster.StatusController.ApplyDebuff("pm_deb_ref", DebuffType.Attack, DebuffModifierMode.Flat, 5f, 4f, EffectPowerTier.TierB, hero, StatusStackPolicy.RefreshDuration);
            var d2 = monster.StatusController.GetDebuff("pm_deb_ref");
            float end2 = d2.EndTime;

            bool pass = d2.StackCount == 1 && end2 >= end1;
            Debug.Log($"[T31 DEBUFF REFRESH DURATION] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: Stacks={d2.StackCount}, End1={end1:F1}s, End2={end2:F1}s.\n" +
                      $"Expected behavior: Duration refreshed, stacks remain at 1.");
            monster.StatusController.RemoveDebuff("pm_deb_ref");
            return pass;
        }

