        private static bool P07_6_PM_T35_EndToEndCombatAcceptance()
        {
            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            Monster monster = bm.CurrentMonster;
            Hero hero = Object.FindAnyObjectByType<Hero>();
            MindMethodManager mmMgr = Object.FindAnyObjectByType<MindMethodManager>();

            hero.Health.Revive(hero.Health.MaxHealth);
            hero.EnableEntityActions();
            monster.Health.Revive(500f);
            monster.EnableEntityActions();

            // 1. Hero applies ATK debuff to monster
            monster.StatusController.ApplyDebuff("e2e_atk_deb", DebuffType.Attack, DebuffModifierMode.Flat, 3f, 5f, EffectPowerTier.TierB, hero);
            // 2. Monster applies Root to Hero
            hero.StatusController.ApplyCrowdControl("e2e_root", CrowdControlType.Root, 3f, EffectPowerTier.TierB, monster);
            // 3. Hero is rooted: Cannot move, but CAN execute skill
            bool rootCheck = !hero.CanMove && hero.CanUseSkill;
            // 4. Hero casts normal attack / skill while rooted
            var skillResult = hero.ExecuteSelectedSkill(SkillSlotType.NormalAttack, monster);
            // 5. Freeze monster and trigger shatter
            monster.StatusController.ApplyCrowdControl("e2e_freeze", CrowdControlType.Freeze, 4f, EffectPowerTier.TierB, hero);
            bool shatterTriggered = monster.StatusController.TryTriggerFreezeShatter(hero);

            // Cleanup
            monster.StatusController.ClearAll();
            hero.StatusController.ClearAll();

            bool pass = rootCheck && skillResult.Success && shatterTriggered && bm.IsBattleActive;
            Debug.Log($"[T35 END TO END COMBAT ACCEPTANCE] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: RootedHeroCanCast={rootCheck}, SkillSuccess={skillResult.Success}, FreezeShatter={shatterTriggered}, BattleActive={bm.IsBattleActive}.\n" +
                      $"Expected behavior: Full end-to-end combat sequence with debuffs, CC, and shatter succeeds.");
            return pass;
        }

