            Monster monster = bm.CurrentMonster;
            hero.StatusController.ApplyCrowdControl("cc_stun", CrowdControlType.Stun, 5f, EffectPowerTier.TierB, monster);

            bool beforeMove = hero.CanMove;
            bool beforeAtk = hero.CanBasicAttack;
            bool beforeSkill = hero.CanUseSkill;
            bool beforeUlt = hero.CanUseUltimate;
            bool beforeDash = hero.CanDash;

            hero.StatusController.CleanseCrowdControl();

            bool afterMove = hero.CanMove;
            bool afterAtk = hero.CanBasicAttack;
            bool afterSkill = hero.CanUseSkill;
            bool afterUlt = hero.CanUseUltimate;
            bool afterDash = hero.CanDash;

            bool ok = !beforeMove && !beforeAtk && !beforeSkill && !beforeUlt && !beforeDash &&
                      afterMove && afterAtk && afterSkill && afterUlt && afterDash;

            Debug.Log($"[P07_7_41] Cleanse Stun Restores All Actions -> Before: {beforeMove}, After: {afterMove} | {(ok ? "PASS" : "FAIL")}");
