        private static bool P07_7_49_CleanseStatRecalculationImmediate()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);
            Monster monster = bm.CurrentMonster;
            float baseAtk = monster.Stats.GetValue(StatType.Attack, 10f);

            monster.StatusController.ApplyDebuff("deb_recalc", DebuffType.Attack, DebuffModifierMode.Flat, 4f, 10f, EffectPowerTier.TierB, hero);
            float debuffedAtk = monster.Stats.GetValue(StatType.Attack);

            monster.StatusController.CleanseDebuffs();
            float restoredAtk = monster.Stats.GetValue(StatType.Attack);

            bool ok = Mathf.Approximately(debuffedAtk, baseAtk - 4f) && Mathf.Approximately(restoredAtk, baseAtk);

            Debug.Log($"[P07_7_49] Cleanse Stat Recalculation Immediate -> Base: {baseAtk}, Debuffed: {debuffedAtk}, Restored: {restoredAtk} | {(ok ? "PASS" : "FAIL")}");
            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

