            var buff = ScriptableObject.CreateInstance<BuffEffectDefinitionSO>();
            buff.Initialize("buff_def_recalc", "Def Recalc", StatType.Defense, 15f, 10f, BuffStackingPolicy.RefreshDuration);
            monster.StatusController.ApplyBuff(buff, monster);

            float buffedDef = monster.Stats.GetValue(StatType.Defense);
            monster.StatusController.DispelAllBuffs();
            float restoredDef = monster.Stats.GetValue(StatType.Defense);

            bool ok = Mathf.Approximately(buffedDef, baseDef + 15f) && Mathf.Approximately(restoredDef, baseDef);

            Debug.Log($"[P07_7_50] Dispel Stat Recalculation Immediate -> Base: {baseDef}, Buffed: {buffedDef}, Restored: {restoredDef} | {(ok ? "PASS" : "FAIL")}");
            Object.DestroyImmediate(buff);
            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

        private static bool P07_7_51_SkillDamagePlusCleanse()
        {
            SetupSkillTestEncounter(out GameObject heroGO, out Hero hero, out GameObject bmGO, out BattleManager bm, out GameObject mmMgrGO, out MindMethodManager mmMgr);
            Monster monster = bm.CurrentMonster;
            monster.Health.InitializeHealth(500f, monster);
            hero.StatusController.ApplyDebuff("hero_deb", DebuffType.Attack, DebuffModifierMode.Flat, 5f, 10f, EffectPowerTier.TierB, monster);

            mmMgr.SetActiveMindMethod("mm_taiji");
            var skillDef = mmMgr.FindSkillDefinition("skill_taiji_2_a");
            var dmg = ScriptableObject.CreateInstance<DamageEffectDefinitionSO>();
            dmg.Initialize(1.5f, SkillTargetPolicy.SingleTarget, DamageType.Skill);
            var cln = ScriptableObject.CreateInstance<CleanseEffectDefinitionSO>();
            cln.Initialize(StatusRemovalCategory.NegativeStatus, 1, policy: SkillTargetPolicy.Self);
            skillDef.SetEffects(new List<SkillEffectDefinitionSO> { dmg, cln });

            hero.Rage.ResetRage(100f);
            float hpBefore = monster.Health.CurrentHealth;

            var res = hero.ExecuteSelectedSkill(SkillSlotType.Skill, monster);

            bool ok = res.Success && monster.Health.CurrentHealth < hpBefore && hero.StatusController.ActiveDebuffs.Count == 0;

            Debug.Log($"[P07_7_51] Skill Damage + Cleanse -> Success: {res.Success}, MonsterHp: {monster.Health.CurrentHealth}, HeroDebuffs: {hero.StatusController.ActiveDebuffs.Count} | {(ok ? "PASS" : "FAIL")}");
            Object.DestroyImmediate(dmg);
            Object.DestroyImmediate(cln);
            TeardownSkillTestEncounter(heroGO, bmGO, mmMgrGO);
            return ok;
        }

