        #region Prototype 07.7 (Play Mode Acceptance Tests T01 to T35)

        [MenuItem("Tools/Wuxia RPG/Run Prototype 07.7 Play Mode Acceptance Tests (T01 to T35)")]
        public static bool RunPrototype07_7PlayModeAcceptanceTests()
        {
            Debug.Log("==================================================");
            Debug.Log("   STARTING PROTOTYPE 07.7 REAL PLAY MODE ACCEPTANCE TESTS (T01 - T35)");
            Debug.Log("==================================================");

            Prototype01SceneBuilder.BuildPrototype02Data();
            Prototype01SceneBuilder.BuildPrototype01Scene();
            EditorSceneManager.OpenScene("Assets/_Game/Scenes/Prototype01.unity", OpenSceneMode.Single);

            Hero setupHero = Object.FindAnyObjectByType<Hero>();
            BattleManager setupBm = Object.FindAnyObjectByType<BattleManager>();
            MindMethodManager setupMm = Object.FindAnyObjectByType<MindMethodManager>();

            if (setupHero != null)
            {
                setupHero.InitializeHero();
                setupHero.Health.Revive(setupHero.Health.MaxHealth);
                setupHero.EnableEntityActions();
            }

            if (setupBm != null)
            {
                if (setupBm.CurrentMonster != null)
                {
                    setupBm.CurrentMonster.InitializeMonster();
                    setupBm.CurrentMonster.Health.Revive(setupBm.CurrentMonster.Health.MaxHealth);
                    setupBm.CurrentMonster.EnableEntityActions();
                }
                if (!setupBm.IsBattleActive)
                {
                    setupBm.StartBattle();
                }
            }

            if (setupMm != null)
            {
                setupMm.LoadDatabaseIfMissing();
                setupMm.ResetPersistence();
                setupMm.InitializeFromDatabase();
                setupMm.SetActiveMindMethod("mm_taiji");
                setupMm.UnlockSkill("skill_taiji_2_a");
                setupMm.SelectSkillForSlot(SkillSlotType.Skill, "skill_taiji_2_a");
            }

            int passed = 0;
            int total = 35;

            if (P07_7_PM_T01_HeroCleansesSingleDebuff()) passed++;
            if (P07_7_PM_T02_HeroCleansesMultipleDebuffsMaxCount()) passed++;
            if (P07_7_PM_T03_HeroCleansesAllNegativeStatuses()) passed++;
            if (P07_7_PM_T04_HeroCleansesDoT()) passed++;
            if (P07_7_PM_T05_HeroCleansesStunRestoresAction()) passed++;
            if (P07_7_PM_T06_HeroCleansesRootRestoresMovement()) passed++;
            if (P07_7_PM_T07_HeroCleansesFreezeRestoresAll()) passed++;
            if (P07_7_PM_T08_HeroCleansesFreezeNoShatter()) passed++;
            if (P07_7_PM_T09_HeroCleansesSpecificDebuffType()) passed++;
            if (P07_7_PM_T10_HeroCleansesSpecificCcType()) passed++;
            if (P07_7_PM_T11_HeroCleansesSpecificStatusId()) passed++;
            if (P07_7_PM_T12_CleanseIgnoresPositiveBuffs()) passed++;
            if (P07_7_PM_T13_CleanseDoesNotRemoveAntiCcImmunity()) passed++;
            if (P07_7_PM_T14_DispelRemovesMonsterBuff()) passed++;
            if (P07_7_PM_T15_DispelMultipleBuffsMaxCount()) passed++;
            if (P07_7_PM_T16_DispelAllBuffs()) passed++;
            if (P07_7_PM_T17_DispelSpecificStatType()) passed++;
            if (P07_7_PM_T18_DispelSpecificBuffId()) passed++;
            if (P07_7_PM_T19_DispelIgnoresNegativeDebuffs()) passed++;
            if (P07_7_PM_T20_DispelIgnoresCrowdControl()) passed++;
            if (P07_7_PM_T21_DispelDoesNotRemoveAntiCcImmunity()) passed++;
            if (P07_7_PM_T22_SelectionModeOldest()) passed++;
            if (P07_7_PM_T23_SelectionModeNewest()) passed++;
