            Monster monster = bm.CurrentMonster;
            Hero hero = Object.FindAnyObjectByType<Hero>();

            monster.StatusController.ClearAll();
            var time = new TestTimeProvider(10f);
            CooldownManager.TimeProvider = time;

            monster.StatusController.ApplyDebuff("pm_old", DebuffType.Attack, DebuffModifierMode.Flat, 5f, 20f, EffectPowerTier.TierB, hero);
            time.Advance(5f);
            monster.StatusController.ApplyDebuff("pm_new", DebuffType.Attack, DebuffModifierMode.Flat, 5f, 20f, EffectPowerTier.TierB, hero);

            monster.StatusController.Cleanse(StatusRemovalCategory.Debuff, 1, StatusSelectionMode.Oldest);
            bool pass = !monster.StatusController.ActiveDebuffs.ContainsKey("pm_old") && monster.StatusController.ActiveDebuffs.ContainsKey("pm_new");

            Debug.Log($"[T22 SELECTION MODE OLDEST] {(pass ? "PASS" : "FAIL")}");
            CooldownManager.ResetForTesting();
            monster.StatusController.ClearAll();
            return pass;
        }

