            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            Monster monster = bm.CurrentMonster;
            Hero hero = Object.FindAnyObjectByType<Hero>();

            monster.StatusController.ClearAll();
            monster.StatusController.ApplyDebuff("pm_low", DebuffType.Attack, DebuffModifierMode.Flat, 5f, 10f, EffectPowerTier.TierA, hero);
            monster.StatusController.ApplyDebuff("pm_high", DebuffType.Attack, DebuffModifierMode.Flat, 5f, 10f, EffectPowerTier.TierC, hero);

            monster.StatusController.Cleanse(StatusRemovalCategory.Debuff, 1, StatusSelectionMode.LowestPriority);
            bool pass = !monster.StatusController.ActiveDebuffs.ContainsKey("pm_low") && monster.StatusController.ActiveDebuffs.ContainsKey("pm_high");

            Debug.Log($"[T25 SELECTION MODE LOWEST PRIORITY] {(pass ? "PASS" : "FAIL")}");
            monster.StatusController.ClearAll();
            return pass;
        }

        private static bool P07_7_PM_T26_SelectionModeRandomDeterminism()
        {
            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            Monster monster = bm.CurrentMonster;
            Hero hero = Object.FindAnyObjectByType<Hero>();

            monster.StatusController.ClearAll();
            monster.StatusController.ApplyDebuff("pm_ra", DebuffType.Attack, DebuffModifierMode.Flat, 5f, 10f, EffectPowerTier.TierB, hero);
            monster.StatusController.ApplyDebuff("pm_rb", DebuffType.Attack, DebuffModifierMode.Flat, 5f, 10f, EffectPowerTier.TierB, hero);
            monster.StatusController.ApplyDebuff("pm_rc", DebuffType.Attack, DebuffModifierMode.Flat, 5f, 10f, EffectPowerTier.TierB, hero);

            EntityStatusController.RandomRangeProvider = max => 0;
            var res = monster.StatusController.Cleanse(StatusRemovalCategory.Debuff, 1, StatusSelectionMode.Random);
            EntityStatusController.RandomRangeProvider = null;

            bool pass = res.Success && monster.StatusController.ActiveDebuffs.Count == 2;

            Debug.Log($"[T26 SELECTION MODE RANDOM DETERMINISM] {(pass ? "PASS" : "FAIL")}");
            monster.StatusController.ClearAll();
            return pass;
        }

        private static bool P07_7_PM_T27_PartialStackCleanse()
        {
            Hero hero = Object.FindAnyObjectByType<Hero>();
