            hero.StatusController.ClearAll();
            hero.StatusController.ApplyDebuff("pm_stk", DebuffType.Attack, DebuffModifierMode.Flat, 2f, 10f, EffectPowerTier.TierB, monster, StatusStackPolicy.Stack);
            hero.StatusController.ApplyDebuff("pm_stk", DebuffType.Attack, DebuffModifierMode.Flat, 2f, 10f, EffectPowerTier.TierB, monster, StatusStackPolicy.Stack);
            hero.StatusController.ApplyDebuff("pm_stk", DebuffType.Attack, DebuffModifierMode.Flat, 2f, 10f, EffectPowerTier.TierB, monster, StatusStackPolicy.Stack);

            hero.StatusController.Cleanse(StatusRemovalCategory.Debuff, 1, stacksToRemove: 1);
            int remStacks = hero.StatusController.GetDebuff("pm_stk") != null ? hero.StatusController.GetDebuff("pm_stk").StackCount : 0;
            bool pass = remStacks == 2;

            Debug.Log($"[T27 PARTIAL STACK CLEANSE] {(pass ? "PASS" : "FAIL")}");
            hero.StatusController.ClearAll();
            return pass;
        }

