            hero.StatusController.ClearAll();
            hero.StatusController.ApplyDebuff("pm_ev_deb", DebuffType.Attack, DebuffModifierMode.Flat, 5f, 10f, EffectPowerTier.TierB, monster);

            bool eventFired = false;
            EventBus.OnDebuffCleansed += (ent, id, src) =>
            {
                if (ent == hero && id == "pm_ev_deb") eventFired = true;
            };

            hero.StatusController.CleanseDebuffs();
            bool pass = eventFired;

            Debug.Log($"[T29 CLEANSE TRIGGERS DEBUFF CLEANSED EVENT] {(pass ? "PASS" : "FAIL")}");
            hero.StatusController.ClearAll();
            return pass;
        }

