        private static bool P07_7_PM_T32_MultiEffectSkillDamagePlusCleanse()
        {
            CooldownManager.ResetForTesting();
            Hero hero = Object.FindAnyObjectByType<Hero>();
            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            Monster monster = bm.CurrentMonster;
            MindMethodManager mmMgr = Object.FindAnyObjectByType<MindMethodManager>();

            hero.StatusController.ClearAll();
            hero.StatusController.ApplyDebuff("pm_skill_deb", DebuffType.Attack, DebuffModifierMode.Flat, 5f, 10f, EffectPowerTier.TierB, monster);
            monster.Health.Revive(500f);
            float hpBefore = monster.Health.CurrentHealth;

            var skillDef = mmMgr.FindSkillDefinition("skill_taiji_2_a");
            var dmg = ScriptableObject.CreateInstance<DamageEffectDefinitionSO>();
            dmg.Initialize(1.5f, SkillTargetPolicy.SingleTarget, DamageType.Skill);
            var cln = ScriptableObject.CreateInstance<CleanseEffectDefinitionSO>();
            cln.Initialize(StatusRemovalCategory.NegativeStatus, 1, policy: SkillTargetPolicy.Self);
            skillDef.SetEffects(new List<SkillEffectDefinitionSO> { dmg, cln });

            hero.Rage.ResetRage(100f);
            var res = hero.ExecuteSelectedSkill(SkillSlotType.Skill, monster);

            bool pass = res.Success && monster.Health.CurrentHealth < hpBefore && hero.StatusController.ActiveDebuffs.Count == 0;

            Debug.Log($"[T32 MULTI EFFECT SKILL DAMAGE PLUS CLEANSE] {(pass ? "PASS" : "FAIL")}");
            Object.DestroyImmediate(dmg);
            Object.DestroyImmediate(cln);
            hero.StatusController.ClearAll();
            CooldownManager.ResetForTesting();
            return pass;
        }

