        private static bool P07_7_PM_T34_MultiEffectSkillSingleRageAndCooldown()
        {
            CooldownManager.ResetForTesting();
            Hero hero = Object.FindAnyObjectByType<Hero>();
            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            Monster monster = bm.CurrentMonster;
            MindMethodManager mmMgr = Object.FindAnyObjectByType<MindMethodManager>();

            var skillDef = mmMgr.FindSkillDefinition("skill_taiji_2_a");
            var dmg = ScriptableObject.CreateInstance<DamageEffectDefinitionSO>();
            dmg.Initialize(1.0f, SkillTargetPolicy.SingleTarget);
            var cln = ScriptableObject.CreateInstance<CleanseEffectDefinitionSO>();
            cln.Initialize(StatusRemovalCategory.NegativeStatus, 1, policy: SkillTargetPolicy.Self);

            skillDef.SetEffects(new List<SkillEffectDefinitionSO> { dmg, cln });

            hero.Rage.ResetRage(50f);
            float rageBefore = hero.Rage.CurrentRage;

            var res = hero.ExecuteSelectedSkill(SkillSlotType.Skill, monster);
            float rageAfter = hero.Rage.CurrentRage;

            bool onCd = CooldownManager.IsOnCooldown(skillDef.SkillId, out _);
            bool pass = res.Success && Mathf.Approximately(rageBefore - rageAfter, skillDef.RageCost) && onCd;

            Debug.Log($"[T34 MULTI EFFECT SKILL SINGLE RAGE AND COOLDOWN] {(pass ? "PASS" : "FAIL")}");
            Object.DestroyImmediate(dmg);
            Object.DestroyImmediate(cln);
            CooldownManager.ResetForTesting();
            return pass;
        }

        private static bool P07_7_PM_T35_EndToEndCombatAcceptance()
        {
            BattleManager bm = Object.FindAnyObjectByType<BattleManager>();
            Monster monster = bm.CurrentMonster;
            Hero hero = Object.FindAnyObjectByType<Hero>();

            hero.Health.Revive(hero.Health.MaxHealth);
            hero.EnableEntityActions();
            hero.StatusController.ClearAll();

            monster.Health.Revive(500f);
            monster.EnableEntityActions();
            monster.StatusController.ClearAll();

            // 1. Monster applies ATK debuff to Hero
            hero.StatusController.ApplyDebuff("e2e_atk_deb", DebuffType.Attack, DebuffModifierMode.Flat, 5f, 10f, EffectPowerTier.TierB, monster);
            bool heroDebuffed = hero.StatusController.ActiveDebuffs.ContainsKey("e2e_atk_deb");

            // 2. Hero cleanses ATK debuff
            var clnRes = hero.StatusController.CleanseDebuffs();
            bool heroCleaned = clnRes.Success && hero.StatusController.ActiveDebuffs.Count == 0;

            // 3. Monster applies Stun CC to Hero
            hero.StatusController.ApplyCrowdControl("e2e_stun", CrowdControlType.Stun, 5f, EffectPowerTier.TierB, monster);
            bool heroStunned = hero.IsStunned && !hero.CanMove;

            // 4. Hero cleanses Stun CC
            var ccRes = hero.StatusController.CleanseCrowdControl();
            bool heroUnstunned = ccRes.Success && !hero.IsStunned && hero.CanMove;

            // 5. Monster applies DEF buff to itself
            var buff = ScriptableObject.CreateInstance<BuffEffectDefinitionSO>();
            buff.Initialize("e2e_mon_def", "DefBuff", StatType.Defense, 20f, 10f, BuffStackingPolicy.RefreshDuration);
            monster.StatusController.ApplyBuff(buff, monster);
            bool monsterBuffed = monster.StatusController.ActiveBuffs.ContainsKey("e2e_mon_def");

            // 6. Hero dispels DEF buff from Monster
            var dspRes = monster.StatusController.DispelAllBuffs();
            bool monsterDispelled = dspRes.Success && monster.StatusController.ActiveBuffs.Count == 0;

            // 7. Hero executes skill attack on monster
            float hpBefore = monster.Health.CurrentHealth;
            var skillResult = hero.ExecuteSelectedSkill(SkillSlotType.NormalAttack, monster);
            bool hitLanded = skillResult.Success && monster.Health.CurrentHealth < hpBefore;

            // Cleanup
            monster.StatusController.ClearAll();
            hero.StatusController.ClearAll();
            Object.DestroyImmediate(buff);

            bool pass = heroDebuffed && heroCleaned && heroStunned && heroUnstunned &&
                        monsterBuffed && monsterDispelled && hitLanded && bm.IsBattleActive;

            Debug.Log($"[T35 END TO END COMBAT ACCEPTANCE] {(pass ? "PASS" : "FAIL")}\n" +
                      $"Observed behavior: HeroDebuffed={heroDebuffed}, Cleaned={heroCleaned}, Stunned={heroStunned}, Unstunned={heroUnstunned}, MonBuffed={monsterBuffed}, Dispelled={monsterDispelled}, HitLanded={hitLanded}, BattleActive={bm.IsBattleActive}.\n" +
                      $"Expected behavior: Full end-to-end combat sequence with cleanse, dispel, CC, and attacks succeeds.");
            return pass;
        }

